window.__LIZZWORD_DEEP_SHARD && window.__LIZZWORD_DEEP_SHARD("0064", [{"word":"scientific","ipa_uk":"/ˌsaɪənˈtɪfɪk/","ipa_us":"/ˌsaɪənˈtɪfɪk/","definition_zh":"科学的；科学上的；符合科学方法的；受过科学训练的","definition_en":"belonging to science, or carried out by its systematic, testable methods of observation and experiment","core_image":"一张实验台上并排放着温度计、编号样本与对照记录，每个步骤都能被复核","scene":"Every step was logged and repeated, which is what makes the finding scientific rather than a lucky guess.","sceneCN":"这里 scientific 指「符合科学方法的」（第 3 个义项：按可检验、可重复的程序得出结论）；结论有记录、可复现，而非侥幸猜测。图中可辨识物件：温度计、编号样本、对照记录本、铅笔。","pos":[{"tag":"adj.","zh":"科学的；科学上的；符合科学方法的；受过科学训练的（比较级 more scientific，最高级 most scientific）"}],"collocations":[{"phrase":"scientific research","zh":"科学研究"},{"phrase":"scientific method","zh":"科学方法"},{"phrase":"scientific evidence","zh":"科学证据"},{"phrase":"scientific community","zh":"科学界"},{"phrase":"scientific discovery","zh":"科学发现"},{"phrase":"scientific explanation","zh":"科学解释"},{"phrase":"scientific notation","zh":"科学记数法"}],"forms":[{"label":"比较级","form":"more scientific"},{"label":"最高级","form":"most scientific"},{"label":"副词形式","form":"scientifically（科学地；从科学角度）"},{"label":"名词形式（学科总体）","form":"science（科学；学科）"},{"label":"名词形式（人）","form":"scientist（科学家）"},{"label":"反义形式","form":"unscientific（不科学的；违背科学方法的）"}],"derivatives":[{"word":"science","pos":"n.","zh":"科学；学科；专门知识"},{"word":"scientist","pos":"n.","zh":"科学家；科研人员"},{"word":"scientifically","pos":"adv.","zh":"科学地；按科学方法地"},{"word":"unscientific","pos":"adj.","zh":"不科学的；不符合科学方法的"},{"word":"scientism","pos":"n.","zh":"科学主义；对科学方法的过度推崇"}],"senses":[{"no":"01","title":"Knowledge-producing inquiry","titleCN":"求知式的探究：以系统研究产生可靠知识","definition":"the broad sense: the whole enterprise of producing reliable knowledge through study","definitionCN":"广义上指通过研究产生可靠知识的整套事业","example":"Scientific progress depends on people repeating one another's experiments.","exampleCN":"科学进步有赖于人们重复他人的实验。","why":"Late Latin scientificus meant literally 'knowledge-making', joining scientia 'knowledge' with facere 'to make'; the adjective first named what produces knowledge.","whyCN":"晚期拉丁 scientificus 字面意为「制造知识」，由 scientia「知识」与 facere「制造」组合而成；这个形容词最初命名的是「能产生知识的东西」。"},{"no":"02","title":"Belonging to a field of science","titleCN":"属于某个科学领域：作为建制与学科的科学","definition":"relating to science as a discipline, institution or profession","definitionCN":"与作为学科、建制或职业的科学相关","example":"Scientific journals review submissions before publication.","exampleCN":"科学期刊在发表前会对来稿进行同行评审。","why":"Once the enterprise had a name, the adjective could simply label anything that belonged to it, with no reference to method at all.","whyCN":"这门事业一旦有了名称，形容词就可以单纯标注「属于它」的事物，完全不必涉及方法。"},{"no":"03","title":"Method that can be checked","titleCN":"可检验的方法：观察、测量、对照与重复","definition":"done by observation, measurement, controlled testing and replication","definitionCN":"通过观察、测量、对照实验与重复验证来完成","example":"The claim is scientific because a new measurement could falsify it.","exampleCN":"这个论断之所以科学，是因为新的测量有可能证伪它。","why":"Modern usage narrowed the adjective to procedure: a claim counts as scientific when its method, not its topic, passes the test.","whyCN":"现代用法把形容词收窄到程序上：一个论断是否科学，看的是方法而非题目是否通过检验。"},{"no":"04","title":"Exact measurement","titleCN":"精确测量：用标准单位记录细微变化","definition":"requiring or using precise, standardized measurement","definitionCN":"要求或采用精确、标准化的测量","example":"Scientific instruments record changes far too small for the eye.","exampleCN":"科学仪器能记录肉眼远远看不见的变化。","why":"Instruments and standard units made exactness a hallmark, so scientific came to mean measured rather than merely studied.","whyCN":"仪器与标准单位让精确性成为标志，于是 scientific 逐渐表示「经过测量的」，而不只是「被研究过的」。"},{"no":"05","title":"Technical names and notation","titleCN":"术语与记号：学科专用的命名系统","definition":"belonging to the specialized language, names or notation of a discipline","definitionCN":"属于某一学科专用的语言、命名或记法","example":"The scientific name of the dog is Canis lupus familiaris.","exampleCN":"狗的学名是 Canis lupus familiaris。","why":"Linnaean taxonomy fixed Latin binomials as scientific names, which gave the adjective a technical-label sense.","whyCN":"林奈分类法把拉丁双名固定为学名，由此赋予该形容词「技术标签」的义项。"},{"no":"06","title":"Opposed to speculation","titleCN":"有据可依：与臆测、迷信相对","definition":"based on evidence rather than opinion, tradition or superstition","definitionCN":"以证据为依据，而非依据意见、传统或迷信","example":"A scientific explanation must fit the data and predict something new.","exampleCN":"科学解释必须符合数据，并能预测新的现象。","why":"The contrast with guesswork sharpened the word: whatever survives testing is called scientific.","whyCN":"与猜测的对立让这个词的边界变得清晰：凡是通过检验留存下来的，就被称为科学的。"},{"no":"07","title":"Trained in a researcher's habits","titleCN":"具有科研者的习惯：怀疑、求证、留记录","definition":"showing the habits of mind a trained researcher is expected to keep","definitionCN":"表现出受过训练的研究者应有的思维习惯","example":"She took a scientific attitude and asked to see the raw data.","exampleCN":"她抱着科学的态度，要求查看原始数据。","why":"The adjective transferred from work to workers, naming the mindset a researcher is expected to show.","whyCN":"形容词从工作转用到人身上，命名研究者被期待展现的那种心态。"},{"no":"08","title":"Methodical in wider use","titleCN":"方法化：实验室之外的系统做法","definition":"applied by extension to any careful, orderly, step-by-step procedure","definitionCN":"引申指任何细致、有序、按步骤推进的做法","example":"He applied a scientific approach to scheduling the warehouse.","exampleCN":"他用科学的方法来安排仓库的排班。","why":"Because method was the core, the word spread by metaphor to any disciplined, step-by-step practice.","whyCN":"由于方法才是核心，这个词通过隐喻扩散到任何有纪律、按步骤进行的实践。"},{"no":"09","title":"Of science as a school subject","titleCN":"理科课程：作为教学科目的科学","definition":"relating to science taught or studied as a school subject","definitionCN":"与作为学校科目被教授或学习的科学相关","example":"The school added scientific subjects to the primary curriculum.","exampleCN":"学校在小学课程中增设了理科科目。","why":"In education the adjective simply labels the subject group, a plain relational use with no methodological claim.","whyCN":"在教育语境中，该形容词只是给科目分组贴标签，是纯粹的关系用法，不含方法论主张。"}],"etymology":{"intro":{"en":"Scientific joins the Latin noun scientia 'knowledge' with the suffix -ficus 'making', from facere 'to make'. The dates below are approximate.","cn":"scientific 把拉丁名词 scientia「知识」与后缀 -ficus「制造」连接起来，后者出自 facere「制造」。以下年代均为约数。"},"items":[{"era":"LATIN SCIRE","en":"Latin scire meant 'to know', and its noun scientia meant 'knowledge, understanding'. The verb is well recorded; its deeper origin is disputed, and any Indo-European root behind it is a reconstruction, not a documented word.","cn":"拉丁 scire 意为「知道」，其名词 scientia 意为「知识、理解」。动词本身记录充分；更深来源有争议，其背后的任何印欧词根都属重构，而非有记录的实际词。"},{"era":"SCIENTIA + FACERE","en":"Late Latin scientificus, literally 'knowledge-making', combined scientia with -ficus from facere 'to make'. The compound belongs to learned medieval writing rather than to classical Latin.","cn":"晚期拉丁 scientificus 字面意为「制造知识的」，把 scientia 与出自 facere「制造」的 -ficus 组合起来。该复合词属于中世纪学术写作，而非古典拉丁。"},{"era":"ENGLISH ARRIVAL","en":"English scientific appears in the late sixteenth century, at first meaning 'producing knowledge' and only later 'belonging to science'. The exact first citation is uncertain.","cn":"英语 scientific 于 16 世纪后期出现，最初意为「产生知识的」，后来才转为「属于科学的」。最早的确切书证年代存疑。"},{"era":"THE METHOD","en":"From the seventeenth century the word attached increasingly to procedure: observation, experiment, measurement and replication, the programme associated with the Royal Society.","cn":"自 17 世纪起，这个词越来越附着于程序：观察、实验、测量与重复，这正是皇家学会所倡导的纲领。"},{"era":"NARROWING AND SPREAD","en":"By the nineteenth century scientific named both the disciplines and their standards, while the adverb scientifically carried the method into ordinary speech.","cn":"到 19 世纪，scientific 既命名各门学科，也命名其标准；副词 scientifically 则把这种方法意识带进了日常语言。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first attestation date only): the first English date is usually given as the 1580s, but the precise citation is uncertain; the origin of scire before its recorded 'know' sense is a reconstruction.","cn":"来源不确定（仅首见年代存疑）：英语首见年代通常给作 16 世纪 80 年代，确切书证存疑；scire 在「知道」义之前的更早来源属重构。"}]},"similar":{"note":{"en":"The first group holds same-family or look-alike words that are easily confused; the second holds near-synonyms that stress method or evidence.","cn":"第一组是同族或形近、容易混淆的词；第二组是强调方法或证据的近义词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"science","ipa":"/ˈsaɪəns/","tag":"noun, not adjective","definition":"The noun for the body of knowledge and the activity that produces it; scientific is the adjective describing what belongs to it.","definitionCN":"名词，指知识体系及产生知识的活动；scientific 则是描述「属于它」的形容词。"},{"word":"scientist","ipa":"/ˈsaɪəntɪst/","tag":"person, not quality","definition":"A person who does research in a science. It names the worker, while scientific names the quality of the work.","definitionCN":"指从事科学研究的人，命名的是工作者；scientific 命名的是工作的性质。"},{"word":"conscientious","ipa":"/ˌkɒnʃiˈenʃəs/","tag":"same root, different meaning","definition":"Means 'careful to do what is right'. It shares Latin scire 'know' through conscientia 'knowledge with oneself', but it is about moral diligence, not research.","definitionCN":"意为「认真尽责的」。它经由 conscientia「与自我共知」共享拉丁 scire「知道」，但说的是道德上的勤勉，与研究无关。"},{"word":"unscientific","ipa":"/ˌʌnsaɪənˈtɪfɪk/","tag":"negated form","definition":"The direct negative: not following scientific method, or contrary to accepted findings. It is not a synonym of 'wrong'.","definitionCN":"直接的否定形式：不遵循科学方法或与公认结论相悖；它并不等于「错误」。"}]},{"heading":"NEAR MEANING","entries":[{"word":"systematic","ipa":"/sɪˈstæmətɪk/","tag":"order, not evidence","definition":"Carried out in a fixed, orderly plan. A systematic review can still be unscientific if it ignores the evidence.","definitionCN":"按固定、有序的计划进行。系统性综述若无视证据，仍可能是不科学的。"},{"word":"empirical","ipa":"/ɪmˈpɪrɪkl/","tag":"observation-based","definition":"Based on observation or experiment rather than theory. It names the source of knowledge; scientific also covers method and institutions.","definitionCN":"以观察或实验而非理论为依据。它命名知识的来源；scientific 还涵盖方法与建制。"},{"word":"rigorous","ipa":"/ˈrɪɡərəs/","tag":"strictness of standard","definition":"Extremely thorough and strict. It praises the tightness of a procedure, where scientific describes its kind.","definitionCN":"极为彻底、严格。它称赞程序的严密程度，而 scientific 描述程序的种类。"},{"word":"technical","ipa":"/ˈteknɪkl/","tag":"specialist detail","definition":"Relating to the practical details of a field. Scientific work is often technical, but technical writing need not be scientific.","definitionCN":"与某领域的实际操作细节相关。科学工作常是技术性的，但技术写作未必科学。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"scientia 'knowledge' + -fic 'making': the adjective literally says 'knowledge-making'.","cn":"scientia「知识」+ -fic「制造」：这个形容词字面就是「制造知识的」。"},{"en":"The family runs science, scientist, scientific, scientifically and unscientific.","cn":"同族词包括 science、scientist、scientific、scientifically、unscientific。"},{"en":"Fixed phrases mark the senses: scientific method, scientific evidence, scientific community, scientific notation.","cn":"固定搭配标出义项：科学方法、科学证据、科学界、科学记数法。"},{"en":"The test is replication: another lab must be able to get the same result.","cn":"检验标准是重复：另一个实验室必须能得到相同结果。"},{"en":"A scientific name is a Latin binomial, not a description, which is why the label sense is separate.","cn":"学名是拉丁双名而非描述，这正是「标签」义项独立存在的原因。"}],"abstract":[{"en":"Picture a notebook where every page is numbered, so anyone can walk the same path twice.","cn":"想象一本每一页都编号的笔记本，任何人都能把同一条路走两遍。"},{"en":"Picture a ruler laid beside a shadow that no eye could judge alone.","cn":"想象一把尺子摆在影子旁，而那影子肉眼无法单独判断。"},{"en":"Picture a claim wearing a badge that says 'I can be checked'.","cn":"想象一个论断挂着写有「可被检验」的徽章。"}]},"examples":[{"en":"Scientific research on the reef has continued for thirty years.","cn":"对这片珊瑚礁的科学研究已持续了三十年。"},{"en":"The committee demanded a scientific explanation for the sudden die-off.","cn":"委员会要求对这次突然大量死亡给出科学解释。"},{"en":"Her scientific training showed in the way she questioned every assumption.","cn":"她的科学训练体现在她质疑每一个假设的方式上。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「science（知识）+ fik（做出来）」——把观察做成知识 → scientific 科学的","word":"scientific"},"root":"拉丁 scire「知道」→ scientia「知识」→ scientificus「产生知识的」→ 英语 scientific。","sensesIntro":{"en":"Nine senses follow one movement: knowledge is made, then the making is standardized into method, measured with instruments, written in technical names, and finally trusted as evidence.","cn":"九个义项沿同一个动作展开：知识被制造出来，随后制造过程被标准化为方法、用仪器测量、写成术语，最终被当作证据来信任。"},"semanticMap":{"core":{"en":"CORE IMAGE: a bench where every step is numbered, measured and repeatable.","cn":"核心意象：一张实验台，每一步都被编号、测量并可重复。"},"chain":["MAKE KNOWLEDGE","BELONG TO A FIELD","TEST AND REPEAT","MEASURE EXACTLY","NAME TECHNICALLY","TRUST THE EVIDENCE"],"branches":[{"senses":"S1","en":"KNOWLEDGE-MAKING: the oldest layer, where the adjective describes activity that produces reliable knowledge.","cn":"制造知识：最古老的一层，形容词描述的是产生可靠知识的活动。"},{"senses":"S2 · S9","en":"MEMBERSHIP: once science is an institution and a school subject, the adjective merely marks belonging.","cn":"归属：一旦科学成为建制与科目，形容词只需标记「属于其中」。"},{"senses":"S3 · S6","en":"CHECKABILITY: method and evidence become the test that separates scientific from speculative.","cn":"可检验性：方法与证据成为分界线，把科学的与臆测的区分开来。"},{"senses":"S4 · S5","en":"PRECISION: standardized measurement and technical naming make results transferable.","cn":"精确性：标准化测量与技术命名让结果可以被传递。"},{"senses":"S7 · S8","en":"TRANSFER: the habits of a trained researcher, then any orderly procedure, borrow the adjective.","cn":"迁移：先是受过训练的研究者的习惯，随后任何有序的做法都借用了这个形容词。"}]},"affixes":{"intro":{"en":"Scientific is a Latin compound adjective in English: a noun for knowledge, a suffix meaning 'making', with no prefix.","cn":"scientific 是英语中的拉丁复合形容词：一个表示知识的词干，一个意为「制造」的后缀，没有前缀。"},"latinIntro":{"en":"Latin scientia 'knowledge' and facere 'to make' supply the whole word; scire 'to know' is the verb behind scientia.","cn":"拉丁 scientia「知识」与 facere「制造」提供了整个词；scire「知道」是 scientia 背后的动词。"},"items":[{"word":"scientific","structure":"scientia + -ficus (making)","meaning":"knowledge-making; belonging to science","meaningCN":"制造知识的；属于科学的","example":"The report follows strict scientific standards.","exampleCN":"这份报告遵循严格的科学标准。"},{"word":"science","structure":"scientia (knowledge)","meaning":"organized knowledge; a discipline","meaningCN":"成体系的知识；一门学科","example":"Science explains why the metal expands.","exampleCN":"科学解释了这种金属为何膨胀。"},{"word":"scientist","structure":"science + -ist (person)","meaning":"a person who studies nature systematically","meaningCN":"系统研究自然的人","example":"The scientist repeated the trial three times.","exampleCN":"这位科学家把试验重复了三次。"},{"word":"scientifically","structure":"scientific + -ally (adverb)","meaning":"in a scientific manner","meaningCN":"以科学的方式","example":"The samples were compared scientifically.","exampleCN":"样本经过了科学比较。"},{"word":"unscientific","structure":"un- (not) + scientific","meaning":"not following scientific method","meaningCN":"不遵循科学方法的","example":"The claim rests on unscientific anecdote.","exampleCN":"该说法依赖不科学的轶事。"},{"word":"conscience","structure":"con- (with) + scire (to know)","meaning":"inner knowledge of right and wrong","meaningCN":"内心对是非的知晓","example":"He could not quiet his conscience.","exampleCN":"他无法让良心平静下来。"},{"word":"conscious","structure":"con- + scire (to know)","meaning":"awake and aware","meaningCN":"清醒而有知觉的","example":"The patient was conscious after the fall.","exampleCN":"跌倒之后病人仍然清醒。"},{"word":"scientism","structure":"science + -ism (system of belief)","meaning":"the view that science alone answers all questions","meaningCN":"认为唯有科学能回答一切问题的立场","example":"Critics call the policy a form of scientism.","exampleCN":"批评者把这项政策称为一种科学主义。"}],"latinEntries":[{"word":"scire","structure":"scire (verb, fourth conjugation)","meaning":"to know, to understand","meaningCN":"知道；理解"},{"word":"scientia","structure":"scientia, scientiae (f., first declension)","meaning":"knowledge, understanding, skill","meaningCN":"知识；理解；技艺"},{"word":"facere","structure":"facere (verb, third conjugation)","meaning":"to make, to do","meaningCN":"制造；做"}],"derivatives":[{"word":"science","pos":"n.","zh":"科学；学科；专门知识"},{"word":"scientist","pos":"n.","zh":"科学家；科研人员"},{"word":"scientifically","pos":"adv.","zh":"科学地；按科学方法地"},{"word":"unscientific","pos":"adj.","zh":"不科学的；不符合科学方法的"},{"word":"scientism","pos":"n.","zh":"科学主义"}]}},{"word":"scientifically","ipa_uk":"/ˌsaɪənˈtɪfɪkli/","ipa_us":"/ˌsaɪənˈtɪfɪkli/","definition_zh":"科学地；按科学方法地；从科学角度；系统地","definition_en":"in a manner that follows scientific methods, standards or knowledge","core_image":"一支笔在实验记录上逐项打勾，每一行都对应一个可复核的步骤","scene":"The samples were collected, stored and analysed scientifically, with every step written down.","sceneCN":"这里 scientifically 指「按科学方法地」（第 1 个义项：遵循观察、对照与可重复的程序）；采样、保存、分析各环节都有记录。图中可辨识物件：样品瓶、编号标签、记录表、打勾的笔。","pos":[{"tag":"adv.","zh":"科学地；按科学方法地；从科学角度；系统地"}],"collocations":[{"phrase":"scientifically proven","zh":"经科学证明的"},{"phrase":"scientifically tested","zh":"经过科学测试的"},{"phrase":"scientifically speaking","zh":"从科学角度说"},{"phrase":"scientifically established","zh":"已被科学确认的"},{"phrase":"scientifically rigorous","zh":"在科学上严谨的"},{"phrase":"scientifically literate","zh":"具备科学素养的"}],"forms":[{"label":"形容词形式","form":"scientific（科学的）"},{"label":"名词形式","form":"science（科学）"},{"label":"施动者名词","form":"scientist（科学家）"},{"label":"反义副词","form":"unscientifically（不科学地）"},{"label":"比较级","form":"more scientifically（更科学地）"},{"label":"最高级","form":"most scientifically（最科学地）"}],"derivatives":[{"word":"scientific","pos":"adj.","zh":"科学的；符合科学方法的"},{"word":"science","pos":"n.","zh":"科学；学科"},{"word":"scientist","pos":"n.","zh":"科学家"},{"word":"unscientifically","pos":"adv.","zh":"不科学地；违背科学方法地"},{"word":"scientifically","pos":"adv.","zh":"科学地"}],"senses":[{"no":"01","title":"By scientific methods","titleCN":"按科学方法：观察、对照、可重复","definition":"in a way that follows observation, controlled testing and replication","definitionCN":"以遵循观察、对照实验与重复验证的方式","example":"The drug was tested scientifically before approval.","exampleCN":"这种药在获批前经过了科学测试。","why":"The adverb simply adds -ly to the adjective, so it inherits the core sense: acting the way scientific procedure acts.","whyCN":"副词只是给形容词加 -ly，因此继承了核心义：以科学程序行事的方式。"},{"no":"02","title":"In agreement with established knowledge","titleCN":"符合既有科学知识：站得住脚","definition":"in a manner consistent with accepted scientific findings","definitionCN":"以与公认科学结论相一致的方式","example":"The claim cannot be defended scientifically.","exampleCN":"这个说法在科学上站不住脚。","why":"Here the adverb judges consistency with the body of knowledge rather than the procedure used.","whyCN":"此处副词评判的是与知识体系的一致性，而不是所采用的程序。"},{"no":"03","title":"In scientific terms","titleCN":"从科学术语看：按学科分类描述","definition":"as described, classified or measured by a particular scientific field","definitionCN":"按某一科学领域的描述、分类或测量方式","example":"Scientifically, the lake is classified as oligotrophic.","exampleCN":"从科学上说，这个湖被归为贫营养湖。","why":"The technical-label sense of the adjective reappears as a viewpoint marker: speaking within a discipline.","whyCN":"形容词的术语标签义在此重现为视角标记：在某一学科内部说话。"},{"no":"04","title":"With rigorous precision","titleCN":"以严格的精确度：计量到最小单位","definition":"with careful measurement and control of every variable","definitionCN":"对每个变量都进行细致测量与控制","example":"The mixture was prepared scientifically, down to the last gram.","exampleCN":"混合物的配制精确到最后一克，完全按科学方式操作。","why":"Measurement was made a hallmark of the adjective, so the adverb can praise exactness of execution.","whyCN":"测量被视为该形容词的标志，因此副词可以称赞执行上的精确。"},{"no":"05","title":"Systematically, outside the lab","titleCN":"系统地：实验室之外的条理化做法","definition":"in any orderly, evidence-based way beyond a laboratory setting","definitionCN":"在实验室之外以任何有序、有据可依的方式","example":"She sorted the archive scientifically by date and author.","exampleCN":"她按日期与作者系统地整理了档案。","why":"The extended sense of the adjective carries over: method borrowed by any disciplined practice.","whyCN":"形容词的引申义顺延过来：方法被任何有纪律的实践所借用。"},{"no":"06","title":"From the standpoint of science","titleCN":"站在科学的立场：以科学共同体为准","definition":"judged by the standards of science as an institution","definitionCN":"以作为建制的科学之标准来评判","example":"Scientifically speaking, the two treatments are equivalent.","exampleCN":"从科学角度说，这两种疗法效果相当。","why":"Institutional membership becomes a standpoint: what the scientific community would accept.","whyCN":"建制归属变成了一个立场：科学共同体将会接受什么。"},{"no":"07","title":"By verifiable evidence","titleCN":"凭可验证的证据：结论可复核","definition":"in a manner that can be checked and repeated by others","definitionCN":"以他人能够核查与重复的方式","example":"Scientifically established findings can still be revised.","exampleCN":"经科学确认的结论仍可能被修正。","why":"Checkability, the test that separates scientific from speculative, reappears as the adverb's evidential sense.","whyCN":"可检验性是区分科学与臆测的标准，在此重现为副词「有证据」的义项。"},{"no":"08","title":"As a school subject","titleCN":"按理科教学的方式：以实验带动学习","definition":"in the manner of science teaching, through experiment and observation","definitionCN":"以科学教学的方式，通过实验与观察","example":"The children were taught scientifically, through their own experiments.","exampleCN":"孩子们通过自己做实验，接受了科学式的教学。","why":"The subject sense of the adjective transfers to the adverb: the way a science lesson is conducted.","whyCN":"形容词的科目义转用到副词上：科学课被进行的这种方式。"}],"etymology":{"intro":{"en":"Scientifically is an English adverb built from scientific plus -ally, which goes back to Latin -alis plus the English adverb ending -ly. The dates below are approximate.","cn":"scientifically 是英语副词，由 scientific 加 -ally 构成，而 -ally 可追溯到拉丁 -alis 加英语副词词尾 -ly。以下年代均为约数。"},"items":[{"era":"LATIN -ALIS","en":"Latin adjectives in -alis formed relational adjectives, and English borrowed the pattern through French. The suffix says 'of or belonging to', not 'in the manner of'.","cn":"拉丁以 -alis 构成关系形容词，英语经法语借入这一模式。该后缀表示「属于」，而非「以……方式」。"},{"era":"ENGLISH -AL + -LY","en":"English turned relational adjectives into manner adverbs with -ly, from Old English -lice. When the adjective already ended in -al, the two endings merged in spelling as -ally.","cn":"英语用 -ly（源自古英语 -lice）把关系形容词变成方式副词。当形容词本身以 -al 结尾时，两个词尾在拼写上合并为 -ally。"},{"era":"COINAGE","en":"Scientifically is formed inside English from the adjective; it is not a direct Latin adverb. It appears in learned writing in the eighteenth century, when scientific was settling into its modern sense.","cn":"scientifically 是在英语内部由形容词构成的，并非直接的拉丁副词。它出现于 18 世纪学术写作中，正值 scientific 的现代义逐渐定型。"},{"era":"SPREAD","en":"As experimental science expanded in the nineteenth century, the adverb moved from treatises into journalism and everyday argument about evidence.","cn":"随着 19 世纪实验科学的扩张，这个副词从论文走进新闻与日常关于证据的争论。"},{"era":"MODERN USE","en":"Today it works chiefly as a manner adverb ('tested scientifically') and as a viewpoint marker ('scientifically speaking'), with the viewpoint use now the more common one in speech.","cn":"今天它主要作方式副词（「经科学测试」）与视角标记（「从科学角度说」），口语中视角用法更为常见。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first attestation date only): the first English citation of the adverb is uncertain and usually placed in the eighteenth century; no classical Latin adverb scientifically existed.","cn":"来源不确定（仅首见年代存疑）：该副词的英语首见书证存疑，通常定在 18 世纪；古典拉丁中并不存在 scientifically 这个副词。"}]},"similar":{"note":{"en":"The first group holds the adjective and its relatives, which differ in part of speech; the second holds adverbs of method.","cn":"第一组是形容词及其同族词，区别在于词性；第二组是表示方法的副词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"scientific","ipa":"/ˌsaɪənˈtɪfɪk/","tag":"adjective, not adverb","definition":"Describes a thing or method as belonging to science; scientifically describes how an action is done.","definitionCN":"描述事物或方法属于科学；scientifically 描述动作以何种方式完成。"},{"word":"scientist","ipa":"/ˈsaɪəntɪst/","tag":"person noun","definition":"A researcher. It cannot replace the adverb: one does not 'do something scientist'.","definitionCN":"指科研人员。它不能替代副词：不能说「以科学家的方式做某事」就等于 scientist。"},{"word":"unscientifically","ipa":"/ˌʌnsaɪənˈtɪfɪkli/","tag":"negated adverb","definition":"The direct negative: in a way that ignores scientific method. It is not simply 'incorrectly'.","definitionCN":"直接的否定副词：以无视科学方法的方式；并不简单等于「错误地」。"},{"word":"scientifically","ipa":"/ˌsaɪənˈtɪfɪkli/","tag":"spelling trap","definition":"Note the double l: -al plus -ly. The misspelling 'scientificaly' drops one l and is not standard.","definitionCN":"注意双写 l：-al 加 -ly。少写一个 l 的 scientificaly 不是标准拼写。"}]},{"heading":"NEAR MEANING","entries":[{"word":"systematically","ipa":"/sɪˈstæmətɪkli/","tag":"order, not evidence","definition":"In a fixed, orderly plan. It stresses sequence, while scientifically stresses evidence and method.","definitionCN":"按固定有序的计划。它强调顺序，而 scientifically 强调证据与方法。"},{"word":"empirically","ipa":"/ɪmˈpɪrɪkli/","tag":"observation only","definition":"By observation or experiment rather than theory. It names the source of knowledge, not the whole scientific standard.","definitionCN":"通过观察或实验而非理论。它命名知识来源，而非整套科学标准。"},{"word":"rigorously","ipa":"/ˈrɪɡərəsli/","tag":"strictness","definition":"With extreme thoroughness and strictness. A procedure can be rigorous without being scientific, and vice versa.","definitionCN":"以极度彻底和严格的方式。程序可以严谨而不科学，也可以科学而不严谨。"},{"word":"methodically","ipa":"/məˈθɒdɪkli/","tag":"step-by-step","definition":"Step by step, in a settled order. It describes pacing rather than the standard of proof.","definitionCN":"按既定顺序一步步地。它描述节奏，而非证明标准。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"scientific + -ally: the -al belongs to the adjective, the -ly makes the adverb.","cn":"scientific + -ally：-al 属于形容词，-ly 才构成副词。"},{"en":"The family runs science, scientist, scientific, scientifically, unscientifically.","cn":"同族词包括 science、scientist、scientific、scientifically、unscientifically。"},{"en":"Fixed frames mark the senses: scientifically proven, scientifically tested, scientifically speaking.","cn":"固定框架标出义项：经科学证明、经科学测试、从科学角度说。"},{"en":"The suffix order is a real spelling rule: adjective in -al plus -ly gives -ally, as in naturally and basically.","cn":"后缀顺序是真实的拼写规则：以 -al 结尾的形容词加 -ly 得 -ally，如 naturally、basically。"},{"en":"Viewpoint use usually sits at the front of the sentence: scientifically speaking, ...","cn":"视角用法通常位于句首：scientifically speaking，……"}],"abstract":[{"en":"Picture a checklist where each box must be ticked by a second person.","cn":"想象一张清单，每个方框都必须由第二个人打勾。"},{"en":"Picture a ruler passed from hand to hand so that everyone measures the same edge.","cn":"想象一把尺子在人们手中传递，让每个人都量同一条边。"},{"en":"Picture a sentence standing on a scale, being weighed before it is believed.","cn":"想象一句话站在天平上，先称重再被相信。"}]},"examples":[{"en":"The soil was sampled scientifically at twelve points across the field.","cn":"在田地的十二个点上按科学方法采集了土壤样本。"},{"en":"Scientifically, the two materials behave in almost the same way.","cn":"从科学上说，这两种材料的表现几乎相同。"},{"en":"Claims that cannot be tested scientifically are not automatically false, only unproven.","cn":"无法用科学方法检验的主张并不自动为假，只是尚未被证明。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「science（知识）+ fically（按……方式）」——按知识的方式做事 → scientifically 科学地","word":"scientifically"},"root":"拉丁 scire「知道」→ scientia「知识」→ scientificus → 英语 scientific + -ally → scientifically。","sensesIntro":{"en":"Eight senses follow one adverb through its uses: how the work is done, how it agrees with knowledge, how a field would phrase it, how exact it is, and where it stands as a viewpoint.","cn":"八个义项让同一个副词走过它的各种用法：工作如何完成、如何与知识相符、某学科会如何表述、精确到何种程度，以及它作为视角所处的位置。"},"semanticMap":{"core":{"en":"CORE IMAGE: every step ticked off on a checklist that anyone could re-run.","cn":"核心意象：每个步骤都在一张人人可重跑的清单上被打勾。"},"chain":["FOLLOW METHOD","MATCH KNOWLEDGE","SPEAK IN A FIELD","MEASURE PRECISELY","EXTEND THE METHOD","MARK A VIEWPOINT"],"branches":[{"senses":"S1","en":"PROCEDURE: the basic manner sense, acting as scientific procedure acts.","cn":"程序：最基本的方式义，以科学程序的方式行事。"},{"senses":"S2 · S7","en":"AGREEMENT: the adverb judges whether a claim fits accepted findings and can be rechecked.","cn":"相符：副词评判主张是否符合公认结论、是否可复核。"},{"senses":"S3 · S6","en":"VIEWPOINT: speaking within a discipline, or judging by the standards of the scientific community.","cn":"视角：在学科内部表述，或以科学共同体的标准评判。"},{"senses":"S4","en":"EXACTNESS: execution measured down to the last unit.","cn":"精确：执行精确到最后一个单位。"},{"senses":"S5 · S8","en":"TRANSFER: method borrowed outside the lab, or the way a science lesson is run.","cn":"迁移：方法被实验室之外借用，或科学课被开展的方式。"}]},"affixes":{"intro":{"en":"Scientifically stacks three layers: the Latin knowledge stem, the Latin relational suffix -al, and the English adverb ending -ly.","cn":"scientifically 叠了三层：拉丁的知识词干、拉丁关系后缀 -al，以及英语副词词尾 -ly。"},"latinIntro":{"en":"Latin scientia and facere build the adjective, and Latin -alis supplies the relational ending that English later joined to -ly.","cn":"拉丁 scientia 与 facere 构成形容词，拉丁 -alis 提供关系词尾，英语后来把它与 -ly 相接。"},"items":[{"word":"scientifically","structure":"scientific + -ally (-al + -ly)","meaning":"in a scientific manner","meaningCN":"以科学的方式","example":"The water was tested scientifically.","exampleCN":"水样经过了科学检测。"},{"word":"scientific","structure":"scientia + -ficus","meaning":"knowledge-making; belonging to science","meaningCN":"制造知识的；属于科学的","example":"Scientific work requires controls.","exampleCN":"科学工作需要对照组。"},{"word":"science","structure":"scientia (knowledge)","meaning":"organized knowledge","meaningCN":"成体系的知识","example":"Science grew out of natural philosophy.","exampleCN":"科学由自然哲学发展而来。"},{"word":"scientist","structure":"science + -ist (person)","meaning":"one who does research","meaningCN":"从事研究的人","example":"A scientist checked the readings.","exampleCN":"一位科研人员核对了读数。"},{"word":"unscientifically","structure":"un- (not) + scientifically","meaning":"in a way that ignores method","meaningCN":"以无视科学方法的方式","example":"The mixture was combined unscientifically, by eye.","exampleCN":"混合物是凭眼睛估量、不科学地调配的。"},{"word":"scientism","structure":"science + -ism","meaning":"the belief that science answers everything","meaningCN":"认为科学能回答一切的信念","example":"Scientism mistakes method for a philosophy.","exampleCN":"科学主义把方法误当作哲学。"},{"word":"conscience","structure":"con- (with) + scire (know)","meaning":"inner sense of right and wrong","meaningCN":"内心的是非感","example":"Her conscience would not let her lie.","exampleCN":"她的良心不允许她撒谎。"},{"word":"conscious","structure":"con- + scire (know)","meaning":"aware, awake","meaningCN":"有知觉的；清醒的","example":"He was conscious of the risk.","exampleCN":"他意识到了风险。"}],"latinEntries":[{"word":"scientia","structure":"scientia, scientiae (f., first declension)","meaning":"knowledge, understanding","meaningCN":"知识；理解"},{"word":"-ficus","structure":"-ficus, -a, -um (adjective suffix, from facere)","meaning":"making, producing","meaningCN":"制造……的；产生……的"},{"word":"-alis","structure":"-alis, -ale (adjective suffix)","meaning":"of or belonging to","meaningCN":"属于……的"}],"derivatives":[{"word":"scientific","pos":"adj.","zh":"科学的"},{"word":"science","pos":"n.","zh":"科学；学科"},{"word":"scientist","pos":"n.","zh":"科学家"},{"word":"unscientifically","pos":"adv.","zh":"不科学地"},{"word":"scientism","pos":"n.","zh":"科学主义"}]}},{"word":"selection","ipa_uk":"/sɪˈlekʃn/","ipa_us":"/sɪˈlekʃn/","definition_zh":"选择；挑选；被选中的人或物；可供选择的种类；自然选择","definition_en":"the act of choosing one or more items from a group, the items chosen, or the range from which they are chosen","core_image":"一只手从一排编号卡片中抽出几张，其余的仍留在盒子里","scene":"The panel spent two days on the selection of the final ten candidates.","sceneCN":"这里 selection 指「挑选过程」（第 1 个义项：从一组人中选出若干）；评审用两天完成最终十人的甄选。图中可辨识物件：编号档案、评审桌、候选名单、留空的档案位。","pos":[{"tag":"n.","zh":"选择；挑选；被选中的人或物；可供选择的种类；（生物学）自然选择（可数或不可数，视义项而定）"}],"collocations":[{"phrase":"selection process","zh":"选拔过程"},{"phrase":"natural selection","zh":"自然选择"},{"phrase":"a wide selection","zh":"种类繁多的选择"},{"phrase":"selection criteria","zh":"选拔标准"},{"phrase":"selection pressure","zh":"选择压力"},{"phrase":"a selection of","zh":"一批精选的……"},{"phrase":"random selection","zh":"随机抽取"}],"forms":[{"label":"复数","form":"selections"},{"label":"动词形式","form":"select（挑选；选择）"},{"label":"形容词形式","form":"selective（有选择的；选择性的）"},{"label":"被选形容词","form":"selected（被选中的）"},{"label":"施动者名词","form":"selector（选择者；选择器）"},{"label":"另一名词","form":"selectivity（选择性）"}],"derivatives":[{"word":"select","pos":"v.","zh":"挑选；选择"},{"word":"selected","pos":"adj.","zh":"被选中的；精选的"},{"word":"selective","pos":"adj.","zh":"选择性的；有选择余地的"},{"word":"selector","pos":"n.","zh":"选择者；选择器"},{"word":"selectivity","pos":"n.","zh":"选择性"}],"senses":[{"no":"01","title":"The act of choosing out","titleCN":"挑选动作：从一组中选出若干","definition":"the act of picking one or more items from a larger group","definitionCN":"从更大的群体中挑选一个或多个项目的动作","example":"The selection of the site took longer than building the bridge.","exampleCN":"选址花的时间比建桥还长。","why":"Latin selectio named the act of choosing out, from se- 'apart' plus legere 'to gather or pick'; the noun begins as an action, not a result.","whyCN":"拉丁 selectio 命名「挑出来」的动作，由 se-「分开」与 legere「收集、挑选」构成；这个名词的起点是动作而非结果。"},{"no":"02","title":"The items chosen","titleCN":"被选中的一批：精选出来的东西","definition":"a set of things or people that have been chosen","definitionCN":"被选中的一组事物或人","example":"The gallery published a selection of his early drawings.","exampleCN":"画廊出版了一批他的早期素描精选。","why":"English shifted the action noun to its result, a common path: the choosing becomes the chosen set.","whyCN":"英语把动作名词转向其结果，这是常见路径：挑选这一动作变成了被挑出的那一批。"},{"no":"03","title":"The range on offer","titleCN":"可供选择的种类：货架上的范围","definition":"the variety of goods or options available to choose from","definitionCN":"可供挑选的商品或选项的丰富程度","example":"The shop stocks a wide selection of dried herbs.","exampleCN":"这家店有种类繁多的干香草。","why":"From 'the chosen set' the word widened again to 'the set one may choose from', reversing the direction of the image.","whyCN":"从「被选中的一批」出发，词义又拓宽为「可供从中挑选的一批」，意象方向恰好反转。"},{"no":"04","title":"Natural selection","titleCN":"自然选择：环境筛选可遗传的变异","definition":"in biology, the process by which inherited variations that aid survival become more common","definitionCN":"生物学上指有助于生存的可遗传变异变得更普遍的过程","example":"Natural selection explains why the beetles darkened on soot-covered trees.","exampleCN":"自然选择解释了甲虫为何在覆满煤烟的树上变暗。","why":"Darwin borrowed the ordinary word for choosing and kept its core: some variants are picked out, others are not.","whyCN":"达尔文借用了日常的「挑选」一词并保留其核心：某些变异被选中，另一些则没有。"},{"no":"05","title":"Artificial selection","titleCN":"人工选择：由人按目标筛选繁育","definition":"selective breeding of plants or animals by human preference","definitionCN":"按人的偏好对动植物进行的选择性繁育","example":"Artificial selection turned wild mustard into cabbage and kale.","exampleCN":"人工选择把野芥菜变成了卷心菜和羽衣甘蓝。","why":"The prefix marks the chooser: here a human breeder occupies the place nature fills in natural selection.","whyCN":"前缀标明了选择者：此处由人类育种者占据自然选择中自然所处的位置。"},{"no":"06","title":"Selection pressure","titleCN":"选择压力：环境对变异施加的筛除力","definition":"the environmental force that favours some traits and removes others","definitionCN":"偏爱某些性状、淘汰另一些性状的环境力量","example":"Predation is a strong selection pressure on shell thickness.","exampleCN":"捕食对壳的厚度构成很强的选择压力。","why":"Pressure extends the choosing image into a continuous force, as if the environment were pressing on a population.","whyCN":"pressure 把「挑选」的意象延伸为持续施加的力量，仿佛环境在群体身上施加压力。"},{"no":"07","title":"Selected text in computing","titleCN":"计算中的选中区域：被标记的文本或对象","definition":"the part of a document or interface a user has marked for an action","definitionCN":"用户在文档或界面中标记出来以备操作的部分","example":"Delete the selection before you paste the new table.","exampleCN":"粘贴新表格前请先删除选中的内容。","why":"Software reused the everyday act: the user picks out a region, and that region becomes 'the selection'.","whyCN":"软件沿用了日常动作：用户挑出一块区域，这块区域便成为「选中项」。"},{"no":"08","title":"A player picked for a team","titleCN":"入选队员：被选进代表队的人","definition":"in sport, a person chosen to represent a team or squad","definitionCN":"体育中被选入代表队或阵容的人","example":"His selection for the national side surprised the pundits.","exampleCN":"他入选国家队让评论员感到意外。","why":"Sports usage personalizes the result sense: the chosen item is a person, and the noun names that person's status.","whyCN":"体育用法把结果义人格化：被选中的「物」成了人，名词命名的就是此人的身份。"},{"no":"09","title":"Sampling selection bias","titleCN":"抽样选择偏差：选样方式扭曲结论","definition":"in statistics, distortion caused by the way a sample was chosen","definitionCN":"统计学上由样本选取方式造成的偏差","example":"Surveying only gym members introduced a clear selection bias.","exampleCN":"只调查健身房会员引入了明显的选择偏差。","why":"Statistics names the choosing step as a source of error: how the sample was selected shapes what it can show.","whyCN":"统计学把「挑选」这一步命名为误差来源：样本如何被选取，决定了它能显示什么。"}],"etymology":{"intro":{"en":"Selection comes from Latin selectio, the action noun of seligere 'to pick out', built from se- 'apart' and legere 'to gather, choose'. The dates below are approximate.","cn":"selection 出自拉丁 selectio，它是 seligere「挑出」的动作名词，由 se-「分开」与 legere「收集、挑选」构成。以下年代均为约数。"},"items":[{"era":"LATIN LEGERE","en":"Latin legere meant 'to gather, to pick, to read'. The reading sense grew from picking out letters, and the same verb underlies lecture, legend, collect and elect.","cn":"拉丁 legere 意为「收集、采摘、阅读」。阅读义由「挑出字母」发展而来，同一动词也支撑 lecture、legend、collect、elect。"},{"era":"SE- + LEGERE","en":"Adding se- 'apart' produced seligere 'to choose out', with the past participle selectus. The prefix marks separation from the rest of the group.","cn":"加上 se-「分开」构成 seligere「挑出来」，过去分词为 selectus。前缀标出的是与群体其余部分的分隔。"},{"era":"LATIN SELECTIO","en":"The action noun selectio meant 'a choosing out'. It is recorded in classical Latin, chiefly in the plain sense of picking or selecting.","cn":"动作名词 selectio 意为「挑出」。古典拉丁已有记录，主要用于挑选、选择的普通义。"},{"era":"ENGLISH ARRIVAL","en":"English selection appears in the sixteenth century, first as the act of choosing, then quickly also as the chosen set. The exact first citation is uncertain.","cn":"英语 selection 于 16 世纪出现，先是「挑选」的动作，随后很快也指被选中之物。最早的确切书证年代存疑。"},{"era":"BIOLOGY","en":"Darwin's natural selection (1859) gave the word its scientific centre of gravity: the environment picks out variants, and the picked variants spread.","cn":"达尔文的 natural selection（1859）赋予该词科学重心：环境挑出某些变异，被挑中的变异扩散开来。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first attestation date only): the deep origin of legere before its 'gather' sense is debated and any Indo-European root is a reconstruction; the first English date is uncertain.","cn":"来源不确定（仅首见年代存疑）：legere 在「收集」义之前的更深来源有争议，任何印欧词根均属重构；英语首见年代亦存疑。"}]},"similar":{"note":{"en":"The first group holds words from the same legere family plus one dangerous look-alike; the second holds near-synonyms for choosing or the chosen set.","cn":"第一组是同出 legere 词族的词，外加一个危险的形近词；第二组是表示挑选或所选之物的近义词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"section","ipa":"/ˈsekʃn/","tag":"look-alike, NOT cognate","definition":"A part cut off from a whole. It comes from Latin secare 'to cut', not from legere, so section and selection share no root.","definitionCN":"指从整体上切下的一部分。它出自拉丁 secare「切」，并非 legere，因此 section 与 selection 并无共同词根。"},{"word":"elect","ipa":"/ɪˈlekt/","tag":"same family, public choosing","definition":"To choose by vote, from e- 'out' plus legere; the choosing is collective and formal, unlike ordinary selection.","definitionCN":"指通过投票选出，由 e-「向外」加 legere 构成；这种选择是集体而正式的，不同于一般的 selection。"},{"word":"collect","ipa":"/kəˈlekt/","tag":"same family, gathering","definition":"To gather things together, from com- 'together' plus legere. It stresses bringing in, not picking out.","definitionCN":"把东西聚在一起，由 com-「共同」加 legere 构成。它强调聚拢，而非挑出。"},{"word":"selective","ipa":"/sɪˈlektɪv/","tag":"adjective of the same verb","definition":"Describes the tendency to choose carefully or to affect only some cases; selection is the act or the chosen set.","definitionCN":"描述谨慎挑选的倾向或只影响部分情形；selection 则是动作或被选中的一批。"}]},{"heading":"NEAR MEANING","entries":[{"word":"choice","ipa":"/tʃɔɪs/","tag":"the decision itself","definition":"The act or right of deciding between options. Selection often implies a procedure or a filter; choice stresses the decision.","definitionCN":"指在选项之间作出决定的行为或权利。selection 常含程序或筛选之意；choice 强调的是决定本身。"},{"word":"pick","ipa":"/pɪk/","tag":"informal choosing","definition":"An informal word for choosing, often by preference rather than rule. Selection is the neutral, often institutional term.","definitionCN":"选择的口语词，常凭偏好而非规则。selection 是中性、常带建制色彩的正式说法。"},{"word":"assortment","ipa":"/əˈsɔːtmənt/","tag":"mixed range","definition":"A collection of different kinds of things. It matches the 'wide range' sense, but not the act or the biology senses.","definitionCN":"不同种类事物的集合。它对应「种类繁多」的义项，但不覆盖动作义或生物学义。"},{"word":"sample","ipa":"/ˈsæmpl/","tag":"a part taken to represent","definition":"A small part taken to stand for the whole. A sample is chosen, but selection names the choosing or the chosen group.","definitionCN":"抽取出来代表整体的一小部分。样本是被选出的，而 selection 命名挑选行为或选出的群体。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"se- 'apart' + legere 'pick': selection is literally a picking-out.","cn":"se-「分开」+ legere「挑选」：selection 字面就是「挑出来」。"},{"en":"The legere family runs select, selection, selective, elect, collect, lecture, legend.","cn":"legere 词族包括 select、selection、selective、elect、collect、lecture、legend。"},{"en":"Fixed phrases mark the senses: selection process, natural selection, a wide selection, selection criteria.","cn":"固定搭配标出义项：选拔过程、自然选择、种类繁多、选拔标准。"},{"en":"Section is NOT a relative: it comes from secare 'to cut'.","cn":"section 并非同族词：它出自 secare「切」。"},{"en":"In computing, the highlighted block is called the selection because the user picked it out.","cn":"在计算领域，被高亮的那一块被称为 selection，因为用户把它挑了出来。"}],"abstract":[{"en":"Picture a hand entering a drawer of cards and leaving most of them behind.","cn":"想象一只手伸进一抽屉卡片，把大部分留在了里面。"},{"en":"Picture a strainer that keeps the grains and lets the water through.","cn":"想象一只滤网，留住谷粒而让水通过。"},{"en":"Picture a spotlight that lights one actor and leaves the rest of the stage dark.","cn":"想象一束追光只照亮一位演员，其余舞台留在暗处。"}]},"examples":[{"en":"Selection of the new manager will take place next month.","cn":"新经理的遴选将在下个月进行。"},{"en":"The bookstore offers a generous selection of dictionaries.","cn":"这家书店提供种类丰富的词典。"},{"en":"Natural selection acts on variation that is already present in the population.","cn":"自然选择作用于群体中已经存在的变异。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「se（分开）+ lect（挑）」——从一堆里分着挑出来 → selection 挑选、被选的一批","word":"selection"},"root":"拉丁 legere「收集、挑选」→ se- + legere = seligere「挑出」→ selectio「挑出（动作）」→ 英语 selection。","sensesIntro":{"en":"Nine senses follow one gesture: a hand picks some items out of a group, and the word can name the gesture, the picked items, the whole group on offer, or the natural version of the same filter.","cn":"九个义项沿同一个动作展开：一只手从群体中挑出若干，这个词既可命名动作、被挑出之物、可供挑选的整批，也可命名同一筛选机制在自然界的版本。"},"semanticMap":{"core":{"en":"CORE IMAGE: a hand lifting a few numbered cards out of a full box.","cn":"核心意象：一只手从装满编号卡片的盒子里抽出几张。"},"chain":["PICK OUT","NAME THE ACT","NAME THE PICKED","WIDEN TO THE RANGE","LET NATURE PICK","FILTER BY RULE"],"branches":[{"senses":"S1","en":"THE ACT: the original Latin sense, choosing as an event.","cn":"动作：最原始的拉丁义，挑选作为一次事件。"},{"senses":"S2 · S8","en":"THE PICKED: the result sense, including the sports use where the chosen item is a person.","cn":"被选者：结果义，包括体育用法中被选中的「物」是人。"},{"senses":"S3","en":"THE RANGE: a reversal of direction, the whole set one may choose from.","cn":"可选范围：方向反转，指可供挑选的整批。"},{"senses":"S4 · S5 · S6","en":"NATURE AS CHOOSER: natural selection, artificial selection and the pressure that drives them.","cn":"自然作为选择者：自然选择、人工选择以及驱动它们的选择压力。"},{"senses":"S7 · S9","en":"SYSTEMS AND ERROR: software marks a selection, and statistics names selection bias.","cn":"系统与误差：软件标记选中区域，统计学则命名选择偏差。"}]},"affixes":{"intro":{"en":"Selection is a Latin action noun: a prefix of separation, the verb legere, and the noun suffix -tio.","cn":"selection 是拉丁动作名词：一个表示分离的前缀、动词 legere，以及名词后缀 -tio。"},"latinIntro":{"en":"Latin se- 'apart' and legere 'to gather, pick' build seligere; its past participle selectus gives select, selection, selective and selector.","cn":"拉丁 se-「分开」与 legere「收集、挑选」构成 seligere；其过去分词 selectus 衍生 select、selection、selective、selector。"},"items":[{"word":"selection","structure":"se- + legere + -tio (action noun)","meaning":"a picking out; the picked set","meaningCN":"挑出的动作；被挑出的一批","example":"The selection was announced on Friday.","exampleCN":"选拔结果于周五公布。"},{"word":"select","structure":"selectus (past participle of seligere)","meaning":"to choose from a group","meaningCN":"从一组中挑选","example":"Select the row you want to keep.","exampleCN":"选中你想保留的那一行。"},{"word":"selected","structure":"select + -ed (past participle adjective)","meaning":"chosen for a purpose","meaningCN":"为某目的被选中的","example":"The selected poems fill one thin volume.","exampleCN":"选出的诗作收在一本薄薄的集子里。"},{"word":"selective","structure":"select + -ive (tending to)","meaning":"choosing carefully; affecting only some","meaningCN":"谨慎挑选的；只影响部分的","example":"The herbicide is selective and spares the crop.","exampleCN":"这种除草剂具有选择性，不伤害作物。"},{"word":"selector","structure":"select + -or (agent noun)","meaning":"one who selects; a switching device","meaningCN":"选择者；选择开关","example":"The selector chose samples from the top shelf.","exampleCN":"采样员从上层架子取了样本。"},{"word":"election","structure":"e- (out) + legere + -tio","meaning":"a choosing out by vote","meaningCN":"以投票方式选出","example":"The election was held in the spring.","exampleCN":"选举在春季举行。"},{"word":"collect","structure":"com- (together) + legere","meaning":"to gather together","meaningCN":"收集；聚拢","example":"They collect rainwater in barrels.","exampleCN":"他们用木桶收集雨水。"},{"word":"lecture","structure":"legere (to read) + -tura","meaning":"a reading aloud, then a formal talk","meaningCN":"朗读，后指正式讲授","example":"The lecture covered seed dispersal.","exampleCN":"讲座讲了种子传播。"},{"word":"legible","structure":"legere (to read) + -ibilis (able to be)","meaning":"readable","meaningCN":"可读的；字迹清晰的","example":"The pencil note was barely legible.","exampleCN":"铅笔字迹几乎看不清。"}],"latinEntries":[{"word":"legere","structure":"legere (verb, third conjugation)","meaning":"to gather, pick, read","meaningCN":"收集；采摘；阅读"},{"word":"seligere","structure":"se- (apart) + legere","meaning":"to choose out, select","meaningCN":"挑出；选择"},{"word":"selectio","structure":"selectio, selectionis (f., third declension)","meaning":"a choosing out, selection","meaningCN":"挑出；选择"}],"derivatives":[{"word":"select","pos":"v.","zh":"挑选；选择"},{"word":"selected","pos":"adj.","zh":"被选中的；精选的"},{"word":"selective","pos":"adj.","zh":"选择性的"},{"word":"selector","pos":"n.","zh":"选择者；选择器"},{"word":"selectivity","pos":"n.","zh":"选择性"}]}},{"word":"selective","ipa_uk":"/sɪˈlektɪv/","ipa_us":"/sɪˈlektɪv/","definition_zh":"有选择性的；挑拣严格的；选择性的（只影响特定对象的）；选择吸附的","definition_en":"choosing carefully, or affecting only particular members of a group rather than all of them","core_image":"一把筛子只让某一种颗粒落下，其余的被留在上面","scene":"The herbicide is selective: it kills the weeds but leaves the crop standing.","sceneCN":"这里 selective 指「只影响特定对象的」（第 3 个义项：作用范围限于某类对象而非全部）；除草剂杀杂草而不伤作物。图中可辨识物件：喷雾器、杂草、作物、筛状示意。","pos":[{"tag":"adj.","zh":"有选择性的；挑拣严格的；只影响特定对象的（比较级 more selective，最高级 most selective）"}],"collocations":[{"phrase":"selective breeding","zh":"选择性繁育"},{"phrase":"selective memory","zh":"选择性记忆"},{"phrase":"selective admission","zh":"择优录取"},{"phrase":"highly selective","zh":"要求极高的；极挑剔的"},{"phrase":"selective pressure","zh":"选择压力"},{"phrase":"selective inhibition","zh":"选择性抑制"}],"forms":[{"label":"比较级","form":"more selective"},{"label":"最高级","form":"most selective"},{"label":"副词形式","form":"selectively（有选择地）"},{"label":"名词形式","form":"selectivity（选择性）"},{"label":"动词形式","form":"select（挑选）"},{"label":"名词形式","form":"selection（挑选；被选的一批）"}],"derivatives":[{"word":"select","pos":"v.","zh":"挑选；选择"},{"word":"selection","pos":"n.","zh":"挑选；被选中的人或物"},{"word":"selectively","pos":"adv.","zh":"有选择地；有区别地"},{"word":"selectivity","pos":"n.","zh":"选择性"},{"word":"selected","pos":"adj.","zh":"被选中的"}],"senses":[{"no":"01","title":"Choosing with care","titleCN":"谨慎挑选：不随便接受","definition":"careful in what one chooses or accepts","definitionCN":"在选择或接受时十分谨慎","example":"She is selective about the films she reviews.","exampleCN":"她对自己评论的影片挑得很严。","why":"The suffix -ive on select makes an adjective of tendency: a person or body that tends to pick rather than take everything.","whyCN":"select 加后缀 -ive 构成倾向性形容词：倾向于挑选而非全盘接受的人或机构。"},{"no":"02","title":"Hard to get into","titleCN":"录取门槛高：只收少数人","definition":"admitting only a small proportion of applicants","definitionCN":"只录取申请者中的一小部分","example":"The programme is one of the most selective in the country.","exampleCN":"该项目是全国录取门槛最高的之一。","why":"Institutions narrow the sense: the picking becomes a filter on applicants, and selectivity turns into prestige.","whyCN":"建制把词义收窄：挑选变成了对申请者的筛子，选择性于是转化为声望。"},{"no":"03","title":"Affecting only a target","titleCN":"只作用于特定对象：不波及全体","definition":"acting on a particular kind of thing and leaving others untouched","definitionCN":"只作用于某一类事物，不影响其他事物","example":"A selective drug lowers the heart rate without dulling the mind.","exampleCN":"一种选择性药物能降低心率而不使头脑迟钝。","why":"Pharmacology and chemistry sharpened the word: selectivity is measured by how narrowly the effect lands.","whyCN":"药理学与化学把这个词磨得更锋利：选择性以作用范围有多窄来衡量。"},{"no":"04","title":"Selective memory","titleCN":"选择性记忆：只记住合意的部分","definition":"remembering some events and conveniently forgetting others","definitionCN":"记住某些事件而便利地忘记另一些","example":"His selective memory lost every promise he had made.","exampleCN":"他的选择性记忆把他许过的承诺全都丢了。","why":"The filter image moves into the mind: memory keeps only what suits, as if it had a screen.","whyCN":"筛子意象移入心智：记忆只留下合意的部分，仿佛自带筛网。"},{"no":"05","title":"Selective breeding","titleCN":"选择性繁育：按目标性状留种","definition":"breeding plants or animals only from individuals that show desired traits","definitionCN":"只用表现出所需性状的个体进行繁育","example":"Selective breeding produced a wheat that ripens early.","exampleCN":"选择性繁育培育出一种早熟小麦。","why":"The human chooser returns here, matching artificial selection: each generation is picked by a criterion.","whyCN":"此处人类选择者回归，与人工选择相呼应：每一代都按某个标准被挑过。"},{"no":"06","title":"Selective pressure","titleCN":"选择压力：环境只留下适应的变异","definition":"a force in the environment that favours some variants over others","definitionCN":"环境中偏爱某些变异、淘汰另一些变异的力量","example":"Drought is a selective pressure on root depth.","exampleCN":"干旱对根深构成一种选择压力。","why":"The adjective marks the unevenness: some variants survive the filter, and the unevenness is called pressure.","whyCN":"形容词标出这种不均衡：有些变异通过了筛子，这种不均衡就被称为压力。"},{"no":"07","title":"Selective absorption","titleCN":"选择性吸收：只吸收特定波段","definition":"in physics and chemistry, taking up only certain wavelengths or substances","definitionCN":"物理与化学中指只吸收某些波长或某些物质","example":"Ozone shows strong selective absorption in the ultraviolet.","exampleCN":"臭氧在紫外波段表现出强烈的选择性吸收。","why":"Spectroscopy measures the narrowness of a response, and the everyday filter image becomes a precise technical property.","whyCN":"光谱学测量响应的狭窄程度，日常的筛子意象于是变成了精确的技术属性。"},{"no":"08","title":"Selective in communication","titleCN":"有选择地传达：只说一部分","definition":"giving information only to certain people or only in part","definitionCN":"只向某些人、或只按部分内容提供信息","example":"He was selective in what he told the committee.","exampleCN":"他向委员会汇报时有所选择。","why":"The word moves from things to speech: a speaker filters the message, releasing only part of it.","whyCN":"这个词从物转到言语：说话者过滤信息，只放出一部分。"}],"etymology":{"intro":{"en":"Selective is an English adjective built on the Latin participle selectus, from seligere 'to choose out' (se- 'apart' + legere 'to pick'). The dates below are approximate.","cn":"selective 是英语形容词，建立在拉丁分词 selectus 之上，后者出自 seligere「挑出」（se-「分开」+ legere「挑选」）。以下年代均为约数。"},"items":[{"era":"LATIN PARTICIPLE","en":"The past participle selectus 'chosen out' supplied English with select, and the participle also underlies the adjective. The root verb legere meant 'to gather, pick, read'.","cn":"过去分词 selectus「被挑出的」为英语提供了 select，该分词同样是形容词的基础。词根动词 legere 意为「收集、挑选、阅读」。"},{"era":"ENGLISH -IVE","en":"English formed adjectives of tendency with -ive, from Latin -ivus. Selective therefore means 'having the tendency to select', not merely 'having been selected'.","cn":"英语用 -ive（源自拉丁 -ivus）构成倾向性形容词。因此 selective 意为「有挑选倾向的」，而不只是「被选中的」。"},{"era":"NINETEENTH CENTURY","en":"The word spread with the growth of breeding, chemistry and electrical engineering, where the question was always how narrowly an effect could be aimed. The earliest technical uses are uncertain in date.","cn":"随着育种、化学与电气工程的发展，这个词流行开来，而这些领域关心的始终是「效果能被瞄得多准」。最早的技术用法年代存疑。"},{"era":"TWENTIETH CENTURY","en":"Selective became ordinary in education and medicine: selective schools, selective drugs, selective memory. Each kept the filter image.","cn":"20 世纪 selective 在教育与医学中成为常用词：择优学校、选择性药物、选择性记忆。每一处都保留了筛子的意象。"},{"era":"MODERN USE","en":"Today the word is chiefly contrastive: it always implies that some members are passed over, which is why it so often appears beside 'only' or 'not all'.","cn":"今天这个词主要用于对比：它总暗含有些成员被略过，这正是它常与 only、not all 同现的原因。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first attestation date only): the first English citation of selective is usually placed in the nineteenth century but is not firmly fixed; the deep origin of legere is a reconstruction.","cn":"来源不确定（仅首见年代存疑）：selective 的英语首见书证通常定在 19 世纪，但并不确凿；legere 的更深来源属重构。"}]},"similar":{"note":{"en":"The first group holds same-family adjectives that are easily swapped by mistake; the second holds near-synonyms about choosing or limiting.","cn":"第一组是同族形容词，容易被误换；第二组是表示挑选或限定的近义词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"selected","ipa":"/sɪˈlektɪd/","tag":"result, not tendency","definition":"Means 'chosen' after the fact. Selective means having the habit or power of choosing, so the two cannot be swapped.","definitionCN":"意为「事后被选中的」。selective 意为具备挑选的习惯或能力，两者不能互换。"},{"word":"selection","ipa":"/sɪˈlekʃn/","tag":"noun, not adjective","definition":"The act of choosing or the chosen set; it cannot modify a noun the way selective does.","definitionCN":"指挑选动作或被选中之物；它不能像 selective 那样修饰名词。"},{"word":"select","ipa":"/sɪˈlekt/","tag":"verb or restricted adjective","definition":"As a verb it names the action; as an adjective it means 'of high quality and restricted access', a narrower sense than selective.","definitionCN":"作动词时命名动作；作形容词时意为「精选而门槛高的」，比 selective 的义域更窄。"},{"word":"elective","ipa":"/ɪˈlektɪv/","tag":"optional, not filtering","definition":"Means 'chosen by the voter' or 'optional', as in an elective course. It shares legere but says nothing about filtering.","definitionCN":"意为「由选举产生的」或「选修的」，如 elective course。它同出 legere，但与筛选无关。"}]},{"heading":"NEAR MEANING","entries":[{"word":"discriminating","ipa":"/dɪˈskrɪmɪneɪtɪŋ/","tag":"showing good judgment","definition":"Showing refined judgment in taste. It praises discernment, while selective may merely describe a filter.","definitionCN":"在品味上表现出精细判断。它称赞鉴别力，而 selective 可能只是描述一个筛子。"},{"word":"exclusive","ipa":"/ɪkˈskluːsɪv/","tag":"shutting others out","definition":"Restricted to a privileged few. Selective stresses the act of filtering; exclusive stresses who is kept out.","definitionCN":"限于少数特权者。selective 强调筛选动作，exclusive 强调被排除在外的对象。"},{"word":"targeted","ipa":"/ˈtɑːɡɪtɪd/","tag":"aimed deliberately","definition":"Directed at a specific group or place. It stresses aim, while selective stresses the narrowness of effect.","definitionCN":"针对特定群体或地点。它强调瞄准，而 selective 强调效果范围的狭窄。"},{"word":"specific","ipa":"/spəˈsɪfɪk/","tag":"precisely identified","definition":"Clearly defined or particular. A specific drug is named exactly; a selective drug is one that acts narrowly.","definitionCN":"明确界定或特定的。specific 的药是被精确命名的，selective 的药是作用范围窄的。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"select + -ive: the suffix marks a tendency, so selective is 'given to picking'.","cn":"select + -ive：后缀标记倾向，故 selective 是「惯于挑选的」。"},{"en":"The family runs select, selected, selection, selective, selectively, selectivity.","cn":"同族词包括 select、selected、selection、selective、selectively、selectivity。"},{"en":"Fixed phrases mark the senses: selective breeding, selective memory, selective admission, highly selective.","cn":"固定搭配标出义项：选择性繁育、选择性记忆、择优录取、门槛极高。"},{"en":"The core contrast is 'some, not all', which is why the word pairs naturally with only.","cn":"核心对比是「部分而非全部」，因此这个词天然与 only 搭配。"},{"en":"selected is the result; selective is the habit or the narrow aim.","cn":"selected 是结果；selective 是习惯或狭窄的作用范围。"}],"abstract":[{"en":"Picture a sieve tilted so that only one size of grain falls through.","cn":"想象一只斜放的筛子，只让一种大小的谷粒落下。"},{"en":"Picture a doorman who checks one list and waves most people past.","cn":"想象一名门卫只核对一张名单，把大多数人挡在外面。"},{"en":"Picture a lamp with a narrow beam that leaves the rest of the room untouched.","cn":"想象一盏窄光束的灯，房间其余部分不受影响。"}]},"examples":[{"en":"The university is highly selective, admitting fewer than one in ten applicants.","cn":"这所大学录取门槛极高，十个申请者中录取不到一个。"},{"en":"Selective grazing changed which grasses survived in the meadow.","cn":"选择性啃食改变了草甸中哪些草得以存活。"},{"en":"He gave a selective account of the meeting, leaving out his own errors.","cn":"他对会议作了有选择的叙述，略去了自己的失误。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「select（挑）+ ive（爱……的）」——爱挑的 → selective 有选择性的、只挑一部分的","word":"selective"},"root":"拉丁 legere「收集、挑选」→ seligere「挑出」→ selectus → 英语 select + -ive → selective。","sensesIntro":{"en":"Eight senses follow one filter: a screen lets part of a group through, and the word can describe a careful person, a strict school, a narrow drug, a partial memory or a biased account.","cn":"八个义项沿同一只筛子展开：筛网让群体的一部分通过，这个词既可描述谨慎的人、门槛高的学校、作用窄的药物，也可描述有偏的记忆或不完整的叙述。"},"semanticMap":{"core":{"en":"CORE IMAGE: a sieve that passes one kind of grain and holds the rest.","cn":"核心意象：一只筛子只放过某一种颗粒，其余留在上面。"},"chain":["PICK SOME","LEAVE THE REST","SET A THRESHOLD","AIM NARROWLY","KEEP PARTIAL","FILTER THE MESSAGE"],"branches":[{"senses":"S1","en":"THE PICKER: the adjective of tendency, describing someone careful about what they accept.","cn":"挑选者：倾向性形容词，描述对接受之物十分谨慎的人。"},{"senses":"S2","en":"THE THRESHOLD: institutions convert picking into admission rules and prestige.","cn":"门槛：建制把挑选转化为录取规则与声望。"},{"senses":"S3 · S7","en":"NARROW AIM: pharmacology and spectroscopy measure how tightly an effect is confined.","cn":"瞄准狭窄：药理学与光谱学测量效果被约束得多紧。"},{"senses":"S4 · S8","en":"PARTIAL KEEPING: memory and speech release only part of what they hold.","cn":"部分保留：记忆与言语只放出所持内容的一部分。"},{"senses":"S5 · S6","en":"BREEDING AND PRESSURE: a human or an environment applies the filter across generations.","cn":"繁育与压力：人或环境跨世代地施加这只筛子。"}]},"affixes":{"intro":{"en":"Selective is a Latin participle stem plus an English tendency suffix, with the separation prefix se- at the front.","cn":"selective 是拉丁分词词干加英语倾向后缀，前面还有表示分离的前缀 se-。"},"latinIntro":{"en":"Latin legere 'to pick' with se- 'apart' gives seligere and selectus; -ivus supplies the English -ive that marks a tendency.","cn":"拉丁 legere「挑选」加 se-「分开」得 seligere 与 selectus；-ivus 提供英语 -ive，用以标记倾向。"},"items":[{"word":"selective","structure":"select + -ive (tending to)","meaning":"given to choosing; narrow in effect","meaningCN":"惯于挑选的；作用范围窄的","example":"The filter is selective for nitrate.","exampleCN":"该滤材对硝酸盐有选择性。"},{"word":"select","structure":"selectus (participle of seligere)","meaning":"to pick out","meaningCN":"挑选出来","example":"Select a sample at random.","exampleCN":"随机选取一个样本。"},{"word":"selection","structure":"se- + legere + -tio","meaning":"a picking out; the picked set","meaningCN":"挑出的动作；被挑出的一批","example":"The selection covers three decades.","exampleCN":"这批选品涵盖三十年。"},{"word":"selected","structure":"select + -ed","meaning":"chosen","meaningCN":"被选中的","example":"The selected lines were copied out.","exampleCN":"被选中的行已抄出。"},{"word":"selectively","structure":"selective + -ly","meaning":"in a selective way","meaningCN":"有选择地","example":"The drug acts selectively on the nerve.","exampleCN":"该药选择性地作用于该神经。"},{"word":"selectivity","structure":"selective + -ity (quality)","meaning":"the degree of narrowness of effect","meaningCN":"作用范围的狭窄程度","example":"High selectivity means fewer side effects.","exampleCN":"高选择性意味着更少的副作用。"},{"word":"elective","structure":"e- (out) + legere + -ive","meaning":"chosen by vote; optional","meaningCN":"选举产生的；选修的","example":"She took an elective course in geology.","exampleCN":"她选修了一门地质学课程。"},{"word":"collective","structure":"com- (together) + legere + -ive","meaning":"shared by a group","meaningCN":"群体共享的","example":"The decision was collective.","exampleCN":"这个决定是集体作出的。"}],"latinEntries":[{"word":"legere","structure":"legere (verb, third conjugation)","meaning":"to gather, pick, read","meaningCN":"收集；采摘；阅读"},{"word":"seligere","structure":"se- (apart) + legere","meaning":"to choose out","meaningCN":"挑出；选择"},{"word":"-ivus","structure":"-ivus, -a, -um (adjective suffix)","meaning":"tending to, serving for","meaningCN":"倾向于……的；用于……的"}],"derivatives":[{"word":"select","pos":"v.","zh":"挑选"},{"word":"selection","pos":"n.","zh":"挑选；被选的一批"},{"word":"selectively","pos":"adv.","zh":"有选择地"},{"word":"selectivity","pos":"n.","zh":"选择性"},{"word":"selected","pos":"adj.","zh":"被选中的"}]}},{"word":"sensitivity","ipa_uk":"/ˌsensəˈtɪvəti/","ipa_us":"/ˌsensəˈtɪvəti/","definition_zh":"敏感性；灵敏度；体贴；易受伤害的状态；（仪器）响应能力","definition_en":"the quality of responding strongly to small changes, or of being easily hurt or moved","core_image":"一片薄薄的膜在极轻的触碰下就凹陷下去，旁边有指针随之摆动","scene":"The test measures the sensitivity of the film to very low light.","sceneCN":"这里 sensitivity 指「感光灵敏度」（第 2 个义项：对微小刺激作出可测响应）；实验测的是胶片对极弱光的响应能力。图中可辨识物件：感光片、微光光源、指针表、遮光罩。","pos":[{"tag":"n.","zh":"敏感性；灵敏度；体贴；易受伤害的状态；仪器的响应能力（多为不可数，指具体敏感之处时可用复数 sensitivities）"}],"collocations":[{"phrase":"sensitivity analysis","zh":"敏感性分析"},{"phrase":"light sensitivity","zh":"光敏度；畏光"},{"phrase":"cultural sensitivity","zh":"文化敏感性"},{"phrase":"sensitivity to","zh":"对……的敏感"},{"phrase":"increase the sensitivity","zh":"提高灵敏度"},{"phrase":"sensitivity training","zh":"敏感度训练"}],"forms":[{"label":"复数（具体敏感之处）","form":"sensitivities"},{"label":"形容词形式","form":"sensitive（敏感的；灵敏的）"},{"label":"副词形式","form":"sensitively（敏感地；体贴地）"},{"label":"动词形式","form":"sensitize（使敏感；使感光）"},{"label":"名词形式（传感器）","form":"sensor（传感器）"},{"label":"另一形容词","form":"sensory（感官的）"}],"derivatives":[{"word":"sensitive","pos":"adj.","zh":"敏感的；灵敏的；体贴的"},{"word":"sensitively","pos":"adv.","zh":"敏感地；体贴地"},{"word":"sensitize","pos":"v.","zh":"使敏感；使具有感光性"},{"word":"sensor","pos":"n.","zh":"传感器；感应器"},{"word":"hypersensitive","pos":"adj.","zh":"过度敏感的；过敏的"}],"senses":[{"no":"01","title":"The state of being easily affected","titleCN":"易受影响的状态：一点变化就有反应","definition":"the quality of being readily affected by small changes or influences","definitionCN":"容易被细微变化或影响所左右的性质","example":"The sensitivity of the instrument made the whole room a source of noise.","exampleCN":"仪器的敏感度让整个房间都成了噪声源。","why":"Latin sentire 'to feel' gives sensus 'feeling'; the abstract noun -itas names the capacity to feel or be moved at all.","whyCN":"拉丁 sentire「感觉」产生 sensus「感觉」；抽象名词后缀 -itas 命名的是「能够感受或被触动」这一能力本身。"},{"no":"02","title":"Instrument responsiveness","titleCN":"仪器灵敏度：最小可测变化","definition":"the smallest change a device can detect and report","definitionCN":"装置能够察觉并报告的最小变化","example":"A higher sensitivity lets the detector find traces of lead.","exampleCN":"更高的灵敏度让探测器能发现微量铅。","why":"Instruments were given the same word as nerves: both convert a faint input into a measurable output.","whyCN":"仪器被赋予与神经相同的词：两者都把微弱的输入转换为可测量的输出。"},{"no":"03","title":"Easily hurt or offended","titleCN":"易受伤、易被触怒：情绪上的薄皮","definition":"the tendency to be hurt or offended by small remarks or events","definitionCN":"容易因细微言语或事件而受伤或被冒犯的倾向","example":"His sensitivity about his accent made meetings difficult.","exampleCN":"他对口音的敏感让会议变得难开。","why":"The physical sense moved inward: what can be easily affected can also be easily wounded.","whyCN":"物理义向内移动：容易被影响的东西，也容易受伤。"},{"no":"04","title":"Thoughtful awareness of others","titleCN":"体贴周到：察觉他人的感受","definition":"careful awareness of other people's feelings and needs","definitionCN":"对他人感受与需要的细心体察","example":"She handled the family's loss with great sensitivity.","exampleCN":"她以极大的体贴处理了这个家庭的丧亲之痛。","why":"The same capacity turned outward becomes a virtue: to feel finely is also to notice what others feel.","whyCN":"同一种能力转向他人便成了美德：感受得细腻，也就更能察觉他人所感。"},{"no":"05","title":"Medical sensitization","titleCN":"医学上的敏感化：对某物反应过强","definition":"in medicine, an exaggerated response to a substance or stimulus","definitionCN":"医学上指对某物质或刺激产生的过度反应","example":"Skin sensitivity to the ointment appeared after a week.","exampleCN":"用药一周后出现了对该软膏的皮肤敏感。","why":"Clinical usage measures the threshold: a lowered threshold is named sensitivity, and the noun carries the diagnosis.","whyCN":"临床用法测量阈值：阈值降低便被称为敏感，这个名词承载着诊断结论。"},{"no":"06","title":"Sensitivity in statistics","titleCN":"统计敏感性：条件变化对结论的影响","definition":"the degree to which a result changes when assumptions or inputs change","definitionCN":"当假设或输入改变时，结果随之改变的程度","example":"The sensitivity analysis showed the forecast depends on one price.","exampleCN":"敏感性分析显示预测取决于一个价格。","why":"Modelling borrowed the word for 'easily affected': a model is sensitive when small inputs move its output.","whyCN":"建模借用了「易受影响」这一含义：当微小输入能推动输出时，模型就是敏感的。"},{"no":"07","title":"Confidentiality needs","titleCN":"保密敏感度：须谨慎处理的程度","definition":"the degree to which information must be handled with care","definitionCN":"信息必须被谨慎处理的程度","example":"Documents of this sensitivity cannot leave the building.","exampleCN":"这种敏感级别的文件不能带出大楼。","why":"From 'easily affected' comes 'easily damaged if mishandled', which is exactly what classified information is.","whyCN":"从「易受影响」引出「处理不当便易受损」，而这正是机密信息的处境。"},{"no":"08","title":"Sensitivity to a market","titleCN":"市场敏感度：对价格或需求的反应","definition":"in economics, the extent to which demand or price responds to a change","definitionCN":"经济学中指需求或价格对某一变化的反应程度","example":"The sensitivity of demand to price rose during the shortage.","exampleCN":"短缺期间需求对价格的敏感度上升了。","why":"Economics uses the same measurement logic: how far does one variable move when another is nudged?","whyCN":"经济学使用同样的测量逻辑：当一个变量被轻轻推动时，另一个变量会移动多远？"}],"etymology":{"intro":{"en":"Sensitivity joins the Latin verb sentire 'to feel' with the abstract suffix -itas, through the adjective sensitivus. The dates below are approximate.","cn":"sensitivity 经由形容词 sensitivus，把拉丁动词 sentire「感觉」与抽象后缀 -itas 结合起来。以下年代均为约数。"},"items":[{"era":"LATIN SENTIRE","en":"Latin sentire meant 'to feel, perceive, think'. Its noun sensus gave English sense, and the same verb underlies sensation, sentiment and consent.","cn":"拉丁 sentire 意为「感觉、察觉、思考」。其名词 sensus 产生英语 sense，同一动词也支撑 sensation、sentiment、consent。"},{"era":"SENSITIVUS","en":"Medieval Latin formed sensitivus 'capable of feeling', used for the faculty of sense in philosophy. The word named a capacity, not an instrument reading.","cn":"中世纪拉丁构成 sensitivus「能够感觉的」，在哲学中用于指感官能力。这个词命名的是能力，而非仪器读数。"},{"era":"ENGLISH ARRIVAL","en":"English sensitivity appears in the eighteenth century, first in physiology and philosophy, then in ordinary description of temperament. The exact first citation is uncertain.","cn":"英语 sensitivity 于 18 世纪出现，先用于生理学与哲学，随后用于对性情的日常描述。最早的确切书证年代存疑。"},{"era":"INSTRUMENTS","en":"Nineteenth-century photography and telegraphy needed a word for how faint a signal a material could register, and sensitivity moved into the laboratory.","cn":"19 世纪的摄影与电报需要为「材料能记录多弱的信号」找一个词，sensitivity 由此进入实验室。"},{"era":"MEASUREMENT","en":"Twentieth-century statistics and economics turned the word into a computed quantity: a sensitivity analysis asks how far an output moves when an input is nudged.","cn":"20 世纪的统计学与经济学把这个词变成可计算的量：敏感性分析问的是一个输入被轻推时，输出移动多远。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first attestation date only): the first English date of sensitivity is uncertain; the deeper origin of sentire before its 'feel' sense is debated and any Indo-European root is a reconstruction.","cn":"来源不确定（仅首见年代存疑）：sensitivity 的英语首见年代存疑；sentire 在「感觉」义之前的更深来源有争议，任何印欧词根均属重构。"}]},"similar":{"note":{"en":"The first group holds same-family nouns and adjectives that differ in part of speech or scope; the second holds near-synonyms for responsiveness.","cn":"第一组是同族名词与形容词，差别在词性或范围；第二组是表示响应能力的近义词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"sensitive","ipa":"/ˈsensətɪv/","tag":"adjective, not noun","definition":"Describes a thing or person that responds readily; sensitivity is the noun naming that quality.","definitionCN":"描述易于响应的事物或人；sensitivity 是命名该性质的名词。"},{"word":"sensibility","ipa":"/ˌsensəˈbɪləti/","tag":"same root, different suffix","definition":"Means refined emotional or aesthetic awareness. It shares sentire but names taste and feeling, not measurable response.","definitionCN":"意为细腻的情感或审美感受力。它同出 sentire，但命名的是品味与情致，而非可测量的响应。"},{"word":"sensation","ipa":"/senˈseɪʃn/","tag":"the felt event","definition":"A physical feeling or a startling event. It is what is felt; sensitivity is the capacity to feel it.","definitionCN":"指身体感觉或引起轰动的事件。它是被感受到的东西；sensitivity 是感受它的能力。"},{"word":"sensor","ipa":"/ˈsensə(r)/","tag":"the device itself","definition":"The instrument that detects a change. Sensitivity is its property; the sensor is the object that has it.","definitionCN":"指探测变化的装置。sensitivity 是它的属性，sensor 是拥有该属性的物件。"}]},{"heading":"NEAR MEANING","entries":[{"word":"responsiveness","ipa":"/rɪˈspɒnsɪvnəs/","tag":"general reacting","definition":"The quality of reacting quickly to something. It is broader: a person, a market or a system can be responsive without being finely calibrated.","definitionCN":"对事物迅速作出反应的性质。它更宽泛：人、市场或系统都可以有响应性，而不必精密校准。"},{"word":"susceptibility","ipa":"/səˌseptəˈbɪləti/","tag":"vulnerability","definition":"The state of being likely to be harmed or influenced. It stresses weakness to attack, while sensitivity may be a useful precision.","definitionCN":"容易受害或受影响的状况。它强调易受攻击的弱点，而 sensitivity 可能是一种有用的精度。"},{"word":"precision","ipa":"/prɪˈsɪʒn/","tag":"fine resolution","definition":"The ability to distinguish very small differences. Sensitivity is about detecting a faint signal; precision is about resolving close values.","definitionCN":"分辨极小差异的能力。sensitivity 关乎察觉微弱信号，precision 关乎分辨接近的数值。"},{"word":"awareness","ipa":"/əˈweənəs/","tag":"conscious noticing","definition":"Conscious knowledge of a situation. It is cognitive, while sensitivity may be physical or emotional.","definitionCN":"对处境的自觉认识。它属于认知层面，而 sensitivity 可能是生理或情绪层面的。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"sentire 'to feel' + -itas: the noun names the capacity to feel.","cn":"sentire「感觉」+ -itas：这个名词命名的是感受的能力。"},{"en":"The family runs sense, sensation, sensitive, sensitivity, sensitize, sensor, sensory.","cn":"同族词包括 sense、sensation、sensitive、sensitivity、sensitize、sensor、sensory。"},{"en":"Fixed phrases mark the senses: sensitivity analysis, light sensitivity, cultural sensitivity, sensitivity to.","cn":"固定搭配标出义项：敏感性分析、光敏度、文化敏感性、对……敏感。"},{"en":"One word covers nerves, film, feelings and markets because all four convert a faint input into a response.","cn":"同一个词覆盖神经、胶片、情绪与市场，因为这四者都把微弱输入转换为响应。"},{"en":"sensitivity is the property; sensor is the device; sensation is what is felt.","cn":"sensitivity 是属性；sensor 是装置；sensation 是被感觉到的东西。"}],"abstract":[{"en":"Picture a thin membrane that dents under a feather.","cn":"想象一片薄膜，一根羽毛就能让它凹陷。"},{"en":"Picture a needle that trembles before the wind is strong enough to feel.","cn":"想象一根指针，在风还吹不动人时就已颤动。"},{"en":"Picture a person who hears the unsaid sentence in a room.","cn":"想象一个人能听见房间里那句没说出口的话。"}]},"examples":[{"en":"The sensitivity of the balance allows readings to a thousandth of a gram.","cn":"这台天平的灵敏度可以读到千分之一克。"},{"en":"Cultural sensitivity is essential when a clinic serves several communities.","cn":"当一家诊所要服务多个社群时，文化敏感性必不可少。"},{"en":"A sensitivity analysis showed that the conclusion held under every assumption tested.","cn":"敏感性分析显示，在测试过的每种假设下结论都成立。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「sense（感觉）+ itivity（能力）」——能感觉到细微变化的能力 → sensitivity 敏感性、灵敏度","word":"sensitivity"},"root":"拉丁 sentire「感觉」→ sensus「感觉」→ sensitivus「能感觉的」→ 英语 sensitivity。","sensesIntro":{"en":"Eight senses follow one capacity: something faintly touched responds strongly, and that capacity can belong to an instrument, a skin, a heart, a model or a market.","cn":"八个义项沿同一种能力展开：受到轻微触动的东西反应强烈，而这种能力可以属于仪器、皮肤、心、模型或市场。"},"semanticMap":{"core":{"en":"CORE IMAGE: a thin membrane that dents at the lightest touch.","cn":"核心意象：一片薄膜，最轻的触碰就能让它凹陷。"},"chain":["FEEL FAINTLY","REGISTER A CHANGE","SET A THRESHOLD","BE EASILY HURT","NOTICE OTHERS","RESPOND IN A SYSTEM"],"branches":[{"senses":"S1","en":"CAPACITY ITSELF: the abstract property of being readily affected.","cn":"能力本身：容易被影响这一抽象属性。"},{"senses":"S2 · S5","en":"MEASURED THRESHOLD: instruments and clinical tests quantify how faint a stimulus can be.","cn":"可测阈值：仪器与临床检测量化刺激可以多微弱。"},{"senses":"S3 · S4","en":"INWARD AND OUTWARD: the same thin skin that is easily wounded also notices others' wounds.","cn":"向内与向外：同一层薄皮既容易受伤，也能察觉他人的伤。"},{"senses":"S6 · S8","en":"SYSTEM RESPONSE: models and markets are sensitive when small inputs move outputs.","cn":"系统响应：当微小输入推动输出时，模型与市场就是敏感的。"},{"senses":"S7","en":"HANDLING CARE: what is easily damaged must be treated with care.","cn":"处置谨慎：容易受损的东西必须谨慎对待。"}]},"affixes":{"intro":{"en":"Sensitivity is a Latin feeling verb plus a Latin abstract suffix, with no prefix.","cn":"sensitivity 是拉丁「感觉」动词加拉丁抽象后缀，没有前缀。"},"latinIntro":{"en":"Latin sentire 'to feel' gives sensus and sensitivus; -itas turns the adjective into the abstract noun sensitivity.","cn":"拉丁 sentire「感觉」产生 sensus 与 sensitivus；-itas 把形容词转为抽象名词 sensitivity。"},"items":[{"word":"sensitivity","structure":"sensitive + -ity (-itas)","meaning":"the quality of responding or being easily affected","meaningCN":"易于响应或易受影响的性质","example":"Sensitivity varies with temperature.","exampleCN":"灵敏度随温度变化。"},{"word":"sensitive","structure":"sentire + -ivus","meaning":"quick to respond; easily hurt","meaningCN":"响应迅速；易受伤","example":"The skin is sensitive to sunlight.","exampleCN":"这种皮肤对阳光敏感。"},{"word":"sensitively","structure":"sensitive + -ly","meaning":"with careful feeling","meaningCN":"带着细致感受地","example":"The topic was handled sensitively.","exampleCN":"这个话题处理得很得体。"},{"word":"sensitize","structure":"sensitive + -ize (to make)","meaning":"to make responsive","meaningCN":"使变得敏感","example":"The plate was sensitized with silver salts.","exampleCN":"感光板用银盐做了敏化处理。"},{"word":"sensor","structure":"sentire + -or (agent)","meaning":"a device that detects","meaningCN":"探测变化的装置","example":"A sensor logged the humidity.","exampleCN":"传感器记录了湿度。"},{"word":"sensory","structure":"sensus + -orius","meaning":"relating to the senses","meaningCN":"与感官相关的","example":"Sensory nerves carry the signal.","exampleCN":"感觉神经传递信号。"},{"word":"sense","structure":"sensus (feeling, meaning)","meaning":"a faculty of perception; meaning","meaningCN":"感知能力；意义","example":"The word has two senses here.","exampleCN":"这个词在此有两个义项。"},{"word":"insensitive","structure":"in- (not) + sensitive","meaning":"not responsive; tactless","meaningCN":"无反应的；不体贴的","example":"The remark was insensitive to her loss.","exampleCN":"那句话对她的丧亲之痛毫无体察。"}],"latinEntries":[{"word":"sentire","structure":"sentire (verb, fourth conjugation)","meaning":"to feel, perceive","meaningCN":"感觉；察觉"},{"word":"sensus","structure":"sensus, sensus (m., fourth declension)","meaning":"feeling, sense, meaning","meaningCN":"感觉；感官；意义"},{"word":"-itas","structure":"-itas, -itatis (f., abstract noun suffix)","meaning":"the quality of being","meaningCN":"……的性质"}],"derivatives":[{"word":"sensitive","pos":"adj.","zh":"敏感的；灵敏的"},{"word":"sensitively","pos":"adv.","zh":"敏感地；体贴地"},{"word":"sensitize","pos":"v.","zh":"使敏感"},{"word":"sensor","pos":"n.","zh":"传感器"},{"word":"insensitive","pos":"adj.","zh":"不敏感的；不体贴的"}]}},{"word":"sensitive","ipa_uk":"/ˈsensətɪv/","ipa_us":"/ˈsensətɪv/","definition_zh":"敏感的；灵敏的；体贴的；易受伤害的；需谨慎处理的；感光的","definition_en":"quick to notice, respond to or be affected by small changes, feelings or influences","core_image":"一株含羞草的叶片在指尖轻碰后立刻合拢","scene":"The moss is sensitive to sulphur dioxide, so it disappears first when the air turns bad.","sceneCN":"这里 sensitive 指「对某因素反应灵敏的」（第 2 个义项：微小浓度变化即引起可见反应）；苔藓对二氧化硫敏感，空气变差时最先消失。图中可辨识物件：苔藓垫、工业烟囱、监测标牌、叶片。","pos":[{"tag":"adj.","zh":"敏感的；灵敏的；体贴的；易受伤害的；需谨慎处理的；感光的（比较级 more sensitive，最高级 most sensitive）"}],"collocations":[{"phrase":"sensitive to light","zh":"对光敏感"},{"phrase":"sensitive information","zh":"敏感信息"},{"phrase":"sensitive issue","zh":"敏感议题"},{"phrase":"highly sensitive","zh":"高度敏感的；极灵敏的"},{"phrase":"sensitive skin","zh":"敏感肌肤"},{"phrase":"sensitive period","zh":"敏感期"}],"forms":[{"label":"比较级","form":"more sensitive"},{"label":"最高级","form":"most sensitive"},{"label":"副词形式","form":"sensitively（敏感地；体贴地）"},{"label":"名词形式","form":"sensitivity（敏感性；灵敏度）"},{"label":"反义形式","form":"insensitive（不敏感的；不体贴的）"},{"label":"动词形式","form":"sensitize（使敏感）"}],"derivatives":[{"word":"sensitivity","pos":"n.","zh":"敏感性；灵敏度"},{"word":"sensitively","pos":"adv.","zh":"敏感地；体贴地"},{"word":"insensitive","pos":"adj.","zh":"不敏感的；不体贴的"},{"word":"hypersensitive","pos":"adj.","zh":"过度敏感的；过敏的"},{"word":"sensitize","pos":"v.","zh":"使敏感；使感光"}],"senses":[{"no":"01","title":"Quick to feel","titleCN":"感觉敏锐：能察觉细微变化","definition":"able to perceive or respond to very small changes","definitionCN":"能够察觉或回应非常细微的变化","example":"A cat's ears are sensitive to sounds we cannot hear.","exampleCN":"猫的耳朵对我们听不见的声音很敏感。","why":"Latin sensitivus meant 'capable of feeling', built on sentire 'to feel'; the adjective begins as a statement of capacity.","whyCN":"拉丁 sensitivus 意为「能够感觉的」，由 sentire「感觉」构成；这个形容词起初是在陈述一种能力。"},{"no":"02","title":"Responsive in measurement","titleCN":"测量灵敏：微小输入即有读数","definition":"of an instrument, registering very faint signals","definitionCN":"指仪器能记录非常微弱的信号","example":"The film is sensitive enough for night photography.","exampleCN":"这种胶片灵敏度足够用于夜间摄影。","why":"The capacity sense was applied to devices: what can feel faintly is called sensitive, whether nerve or emulsion.","whyCN":"能力义被用到装置上：凡能感知微弱信号者都被称为敏感，无论是神经还是感光乳剂。"},{"no":"03","title":"Easily offended","titleCN":"情绪易受伤：一句话就能刺痛","definition":"easily hurt or annoyed by remarks or events","definitionCN":"容易因言语或事件而受伤或恼怒","example":"He is sensitive about his handwriting.","exampleCN":"他对自己写的字很敏感。","why":"What is easily affected is also easily wounded, so the physical capacity became an emotional vulnerability.","whyCN":"容易被影响的东西也容易受伤，于是物理上的能力变成了情感上的脆弱。"},{"no":"04","title":"Considerate of others","titleCN":"体贴入微：顾及他人感受","definition":"showing careful awareness of other people's feelings","definitionCN":"表现出对他人感受的细心体察","example":"The nurse was sensitive to the patient's fear.","exampleCN":"护士体察到了病人的恐惧。","why":"The same fine feeling turned outward is a virtue: noticing what others feel before they say it.","whyCN":"同样的细腻感受转向他人便成为美德：在他人说出口之前就察觉其所感。"},{"no":"05","title":"Needing careful handling","titleCN":"须谨慎处理：说错或传错就有代价","definition":"of information or topics, requiring discretion because harm could follow","definitionCN":"指信息或话题因可能造成损害而需要谨慎处理","example":"The file contains sensitive personal data.","exampleCN":"该文件含有敏感的个人数据。","why":"The vulnerability sense shifted from people to information: what can be damaged by careless handling is sensitive.","whyCN":"脆弱义从人转到信息：处理不慎就会受损的东西，就是敏感的。"},{"no":"06","title":"Physically tender","titleCN":"身体部位娇嫩：触碰即痛","definition":"of a body part, painful or reacting when touched","definitionCN":"指身体部位被触碰时疼痛或出现反应","example":"The skin around the wound is still sensitive.","exampleCN":"伤口周围的皮肤仍然敏感。","why":"Here the word returns to the body in its plainest form: a surface that reports every touch.","whyCN":"此处这个词以最朴素的方式回到身体：一个会报告每一次触碰的表面。"},{"no":"07","title":"Sensitive to a chemical","titleCN":"对化学物质敏感：低浓度即受害","definition":"showing a marked reaction to a substance at low concentration","definitionCN":"在低浓度下就对某物质表现出显著反应","example":"Lichens are sensitive to air pollution and serve as indicators.","exampleCN":"地衣对空气污染敏感，可用作指示生物。","why":"Ecology uses the word for a low threshold: the organism registers what is nearly invisible to us.","whyCN":"生态学把这个词用于低阈值：生物记录下我们几乎看不见的东西。"},{"no":"08","title":"Price-sensitive demand","titleCN":"价格敏感：小幅变动即改行为","definition":"in economics, responding strongly to a change in price or supply","definitionCN":"经济学中指对价格或供给变化反应强烈","example":"The market for staples is highly price-sensitive.","exampleCN":"主食市场对价格高度敏感。","why":"Economics keeps the measurement frame: a small nudge in price produces a large move in demand.","whyCN":"经济学保留了测量框架：价格轻微推动即引起需求大幅移动。"},{"no":"09","title":"A sensitive period","titleCN":"敏感期：某阶段学习效果最佳","definition":"in development, a window during which a capacity forms most easily","definitionCN":"发育过程中某项能力最易形成的时段","example":"Songbirds learn their song during a sensitive period.","exampleCN":"鸣禽在敏感期内学会自己的鸣唱。","why":"Time itself becomes the stimulus: outside the window the same input produces a weaker response.","whyCN":"时间本身成了刺激：错过这个窗口，同样的输入只能产生更弱的反应。"}],"etymology":{"intro":{"en":"Sensitive comes from Medieval Latin sensitivus 'capable of feeling', from sentire 'to feel'. The dates below are approximate.","cn":"sensitive 出自中世纪拉丁 sensitivus「能够感觉的」，源自 sentire「感觉」。以下年代均为约数。"},"items":[{"era":"LATIN SENTIRE","en":"Latin sentire 'to feel, perceive' is well recorded, and its noun sensus gave English sense. The verb's deeper origin is debated and any Indo-European root is a reconstruction.","cn":"拉丁 sentire「感觉、察觉」记录充分，其名词 sensus 产生英语 sense。该动词更深来源有争议，任何印欧词根均属重构。"},{"era":"MEDIEVAL SENSITIVUS","en":"Scholastic philosophy formed sensitivus for the sensitive faculty, the part of the soul that perceives through the body, as opposed to intellectivus.","cn":"经院哲学构成 sensitivus，指「感觉能力」，即灵魂中通过身体感知的部分，与 intellectivus 相对。"},{"era":"ENGLISH ARRIVAL","en":"English sensitive appears in the sixteenth century, first in medical and philosophical writing. The exact first citation is uncertain.","cn":"英语 sensitive 于 16 世纪出现，先见于医学与哲学写作。最早的确切书证年代存疑。"},{"era":"PHOTOGRAPHY","en":"Nineteenth-century photography gave the word a technical life: sensitive plates and sensitive paper register faint light.","cn":"19 世纪摄影赋予这个词技术生命：感光板与感光纸能记录微弱的光。"},{"era":"EMOTIONAL USE","en":"By the nineteenth century sensitive also described temperament, and by the twentieth it described confidential material and delicate topics.","cn":"到 19 世纪，sensitive 也用于描述性情；到 20 世纪，它又用于描述机密材料与微妙话题。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first attestation date only): the first English date is uncertain; sentire's deeper etymology is unresolved and usually treated as a reconstruction.","cn":"来源不确定（仅首见年代存疑）：英语首见年代存疑；sentire 的更深词源尚无定论，通常按重构处理。"}]},"similar":{"note":{"en":"The first group holds the noun and look-alikes that are easily swapped; the second holds near-synonyms about responsiveness or tenderness.","cn":"第一组是名词及易被误换的形近词；第二组是表示响应或娇嫩的近义词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"sensitivity","ipa":"/ˌsensəˈtɪvəti/","tag":"noun, not adjective","definition":"The noun for the quality; sensitive describes the thing that has it. 'A sensitivity skin' is wrong.","definitionCN":"命名该性质的名词；sensitive 描述拥有该性质的事物。「a sensitivity skin」是错误用法。"},{"word":"sensible","ipa":"/ˈsensəbl/","tag":"same root, different meaning","definition":"Means 'showing good judgment'. It shares sentire through sensibilis 'perceptible', but it judges reason, not responsiveness.","definitionCN":"意为「明智的」。它经由 sensibilis「可感知的」共享 sentire，但评判的是理性，而非响应能力。"},{"word":"sensational","ipa":"/senˈseɪʃənl/","tag":"shocking or excellent","definition":"Means 'causing a sensation' or 'excellent'. It comes from sensation, and has nothing to do with being finely tuned.","definitionCN":"意为「引起轰动的」或「极好的」。它出自 sensation，与精细调校毫无关系。"},{"word":"sensory","ipa":"/ˈsensəri/","tag":"of the senses, technical","definition":"Relating to sensation as a bodily system, as in sensory nerves. It is a neutral anatomical label, not a judgment of responsiveness.","definitionCN":"指作为身体系统的感觉，如 sensory nerves。它是中性的解剖学标签，不评判响应强弱。"}]},{"heading":"NEAR MEANING","entries":[{"word":"responsive","ipa":"/rɪˈspɒnsɪv/","tag":"reacting quickly","definition":"Reacting readily to something. It stresses reaction speed, while sensitive stresses the faintness of the trigger.","definitionCN":"容易对事物作出反应。它强调反应速度，而 sensitive 强调触发条件有多微弱。"},{"word":"vulnerable","ipa":"/ˈvʌlnərəbl/","tag":"open to harm","definition":"Exposed to damage or attack. It names the risk, while sensitive may name a useful precision.","definitionCN":"暴露于损害或攻击之下。它命名风险，而 sensitive 可能命名一种有用的精度。"},{"word":"tender","ipa":"/ˈtendə(r)/","tag":"physically sore","definition":"Painful when touched. It is the bodily sense only, and does not extend to instruments or markets.","definitionCN":"触碰时疼痛。它只覆盖身体义，不延伸到仪器或市场。"},{"word":"delicate","ipa":"/ˈdelɪkət/","tag":"easily damaged","definition":"Fine and easily broken. It stresses fragility of structure; sensitive stresses readiness of response.","definitionCN":"精细而容易损坏。它强调结构的脆弱；sensitive 强调响应的敏捷。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"sentire 'to feel' + -ive: the adjective of capacity, 'able to feel'.","cn":"sentire「感觉」+ -ive：表示能力的形容词，即「能够感觉的」。"},{"en":"The family runs sense, sensation, sensitive, sensitivity, sensitize, sensor, sensory.","cn":"同族词包括 sense、sensation、sensitive、sensitivity、sensitize、sensor、sensory。"},{"en":"Fixed phrases mark the senses: sensitive to light, sensitive information, sensitive issue, sensitive period.","cn":"固定搭配标出义项：对光敏感、敏感信息、敏感议题、敏感期。"},{"en":"sensible is about judgment, sensational about excitement, sensory about anatomy; only sensitive is about responsiveness.","cn":"sensible 关乎判断，sensational 关乎轰动，sensory 关乎解剖；只有 sensitive 关乎响应能力。"},{"en":"The same adjective serves nerves, film, feelings, files and prices because all convert a faint input into a visible response.","cn":"同一个形容词可用于神经、胶片、情绪、文件与价格，因为它们都把微弱输入转换为可见响应。"}],"abstract":[{"en":"Picture a mimosa whose leaflets fold at a fingertip.","cn":"想象一株含羞草，指尖一碰叶片就合拢。"},{"en":"Picture a scale that tips at the weight of a hair.","cn":"想象一台天平，一根头发的重量就能让它倾斜。"},{"en":"Picture a friend who notices your silence before you speak.","cn":"想象一位朋友，在你开口前就注意到你的沉默。"}]},"examples":[{"en":"Children's skin is more sensitive than adults' to strong sunlight.","cn":"儿童的皮肤比成人对强烈阳光更敏感。"},{"en":"The negotiators avoided the most sensitive questions until the end.","cn":"谈判者把最敏感的议题留到了最后。"},{"en":"The instrument is sensitive enough to detect a single photon.","cn":"这台仪器灵敏到可以探测单个光子。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「sense（感觉）+ itive（能……的）」——能感觉到一点点变化的 → sensitive 敏感的、灵敏的","word":"sensitive"},"root":"拉丁 sentire「感觉」→ sensus「感觉」→ 中世纪拉丁 sensitivus「能感觉的」→ 英语 sensitive。","sensesIntro":{"en":"Nine senses follow one thin surface: it reports the faintest touch, and that same readiness can mean precision, pain, tact, risk or a narrow window in time.","cn":"九个义项沿同一层薄表面展开：它报告最轻的触碰，而这种敏捷既可意味着精度、疼痛、体贴、风险，也可意味着时间上的狭窄窗口。"},"semanticMap":{"core":{"en":"CORE IMAGE: a mimosa leaf folding at the lightest touch.","cn":"核心意象：一片含羞草叶，最轻的触碰就合拢。"},"chain":["NOTICE FAINTLY","REGISTER A SIGNAL","BE EASILY HURT","CARE FOR OTHERS","REQUIRE DISCRETION","REACT IN A SYSTEM"],"branches":[{"senses":"S1 · S6","en":"THE FEELING SURFACE: perception and bodily tenderness are the same capacity at two intensities.","cn":"感受表面：感知与身体娇嫩是同一种能力在两个强度上的表现。"},{"senses":"S2","en":"INSTRUMENTS: film and detectors inherit the capacity sense as measurable responsiveness.","cn":"仪器：胶片与探测器把能力义继承为可测量的响应度。"},{"senses":"S3 · S5","en":"VULNERABILITY: feelings and confidential material are both easily damaged by careless contact.","cn":"脆弱：情感与机密材料都会因不当接触而受损。"},{"senses":"S4 · S7","en":"OUTWARD CARE AND ECOLOGY: noticing others' feelings and registering pollutants are both fine detection.","cn":"向外的体察与生态：察觉他人感受与记录污染物，都是精细的探测。"},{"senses":"S8 · S9","en":"SYSTEM AND TIME: prices and developmental windows respond sharply to small changes.","cn":"系统与时间：价格与发育窗口都会对微小变化作出强烈响应。"}]},"affixes":{"intro":{"en":"Sensitive is a Latin feeling verb with the capacity suffix -ive; there is no prefix.","cn":"sensitive 是拉丁「感觉」动词加能力后缀 -ive，没有前缀。"},"latinIntro":{"en":"Latin sentire 'to feel' gives sensus, and Medieval Latin sensitivus adds -ivus to mark capacity.","cn":"拉丁 sentire「感觉」产生 sensus，中世纪拉丁 sensitivus 加上 -ivus 以标记能力。"},"items":[{"word":"sensitive","structure":"sentire + -ivus (capable of)","meaning":"able to feel or respond; easily affected","meaningCN":"能感觉或回应；易受影响","example":"The paper is sensitive to ultraviolet.","exampleCN":"这种纸对紫外线敏感。"},{"word":"sensitivity","structure":"sensitive + -ity","meaning":"the quality of responding","meaningCN":"响应的性质","example":"Sensitivity falls at low temperatures.","exampleCN":"低温下灵敏度下降。"},{"word":"sensitively","structure":"sensitive + -ly","meaning":"with tact or fine feeling","meaningCN":"带着体察或细腻感受地","example":"The news was broken sensitively.","exampleCN":"这个消息被委婉地告知。"},{"word":"insensitive","structure":"in- (not) + sensitive","meaning":"unresponsive; tactless","meaningCN":"无反应的；不体贴的","example":"An insensitive joke ended the meeting early.","exampleCN":"一个不得体的玩笑让会议提前结束。"},{"word":"hypersensitive","structure":"hyper- (over) + sensitive","meaning":"over-reactive","meaningCN":"反应过度的","example":"The patient is hypersensitive to penicillin.","exampleCN":"该病人对青霉素过敏。"},{"word":"sensitize","structure":"sensitive + -ize (to make)","meaning":"to make responsive","meaningCN":"使变得敏感","example":"The film was sensitized with dye.","exampleCN":"胶片用染料做了敏化。"},{"word":"sensation","structure":"sensus + -tio","meaning":"a felt impression","meaningCN":"被感受到的印象","example":"A burning sensation followed the sting.","exampleCN":"被蜇后出现了灼烧感。"},{"word":"consensus","structure":"con- (together) + sensus","meaning":"shared feeling, general agreement","meaningCN":"共同感受；普遍一致","example":"The committee reached a consensus.","exampleCN":"委员会达成了一致。"}],"latinEntries":[{"word":"sentire","structure":"sentire (verb, fourth conjugation)","meaning":"to feel, perceive","meaningCN":"感觉；察觉"},{"word":"sensus","structure":"sensus, sensus (m., fourth declension)","meaning":"feeling, sense","meaningCN":"感觉；感官"},{"word":"-ivus","structure":"-ivus, -a, -um (adjective suffix)","meaning":"capable of, tending to","meaningCN":"能……的；倾向于……的"}],"derivatives":[{"word":"sensitivity","pos":"n.","zh":"敏感性；灵敏度"},{"word":"sensitively","pos":"adv.","zh":"敏感地；体贴地"},{"word":"insensitive","pos":"adj.","zh":"不敏感的；不体贴的"},{"word":"hypersensitive","pos":"adj.","zh":"过度敏感的"},{"word":"sensitize","pos":"v.","zh":"使敏感"}]}},{"word":"significance","ipa_uk":"/sɪɡˈnɪfɪkəns/","ipa_us":"/sɪɡˈnɪfɪkəns/","definition_zh":"重要性；意义；含义；显著性；显著性水平","definition_en":"the importance or meaning of something, or the quality of being statistically unlikely to be chance","core_image":"一枚小砝码压在天平一端，指针明显偏向有重量的一侧","scene":"The find was small, but its significance for dating the site was enormous.","sceneCN":"这里 significance 指「重要性」（第 1 个义项：对整体判断产生重大影响的分量）；这件小发现对断代的意义极大。图中可辨识物件：陶片、年代标尺、天平、记录牌。","pos":[{"tag":"n.","zh":"重要性；意义；含义；显著性；显著性水平（多不可数，指具体含义时可用复数 significances）"}],"collocations":[{"phrase":"statistical significance","zh":"统计显著性"},{"phrase":"of great significance","zh":"意义重大的"},{"phrase":"the significance of","zh":"……的意义"},{"phrase":"historical significance","zh":"历史意义"},{"phrase":"significance level","zh":"显著性水平"},{"phrase":"attach significance to","zh":"赋予……重要意义"}],"forms":[{"label":"复数","form":"significances"},{"label":"形容词形式","form":"significant（重要的；显著的）"},{"label":"副词形式","form":"significantly（显著地；意义重大地）"},{"label":"动词形式","form":"signify（表示；意味着）"},{"label":"名词形式（所指）","form":"signification（含义；词义）"},{"label":"另一形容词","form":"significative（有意义的；指示的）"}],"derivatives":[{"word":"significant","pos":"adj.","zh":"重要的；有意义的；显著的"},{"word":"significantly","pos":"adv.","zh":"显著地；意味深长地"},{"word":"signify","pos":"v.","zh":"表示；意味着；有重要性"},{"word":"signification","pos":"n.","zh":"含义；词义"},{"word":"insignificance","pos":"n.","zh":"无足轻重；微不足道"}],"senses":[{"no":"01","title":"Weight in the balance","titleCN":"分量：对判断有实际影响","definition":"the importance of something in relation to a larger judgment or outcome","definitionCN":"某事物相对于更大判断或结果而言的重要性","example":"The size of the sample gives the result its significance.","exampleCN":"样本的规模赋予这个结果以分量。","why":"Latin significare 'to make a sign' gave significatio, whose first sense was 'a meaning indicated'; English widened it to 'weight or importance'.","whyCN":"拉丁 significare「作出标记」产生 significatio，其初义为「所指示的含义」；英语把它拓宽为「分量或重要性」。"},{"no":"02","title":"Meaning carried","titleCN":"含义：符号或行为所传达的东西","definition":"the meaning expressed by a word, sign, action or event","definitionCN":"词、符号、行为或事件所表达的含义","example":"The significance of the gesture escaped the visiting delegation.","exampleCN":"来访代表团没有领会这个手势的含义。","why":"This is the oldest layer: significatio named the meaning a sign points to, from signum 'sign' plus facere 'to make'.","whyCN":"这是最古老的一层：significatio 命名符号所指的含义，由 signum「符号」加 facere「制造」构成。"},{"no":"03","title":"Consequence for the future","titleCN":"后果分量：将改变后续走向","definition":"the importance of an event because of what it will cause","definitionCN":"某事件因其将引发的结果而具有的重要性","example":"Historians still argue about the significance of the treaty.","exampleCN":"历史学家至今仍在争论这份条约的分量。","why":"Importance was read forward in time: an event matters by what it sets in motion, not by its size.","whyCN":"重要性被投向未来：一件事的分量在于它启动了什么，而不在于它本身的规模。"},{"no":"04","title":"Statistical significance","titleCN":"统计显著性：不太可能出于偶然","definition":"in statistics, the state of a result being unlikely under the null hypothesis","definitionCN":"统计学上指结果在原假设下不太可能出现的状态","example":"The difference reached significance at the five per cent level.","exampleCN":"这一差异在百分之五水平上达到显著。","why":"Statistics narrowed the word to a threshold: significance became a computed measure of improbability, not a matter of importance.","whyCN":"统计学把这个词收窄为一个阈值：significance 变成可计算的「不可能程度」，而非重要性问题。"},{"no":"05","title":"Significance level","titleCN":"显著性水平：预先设定的判据","definition":"the probability threshold chosen in advance for rejecting a hypothesis","definitionCN":"为拒绝假设而预先选定的概率阈值","example":"The study set its significance level before collecting data.","exampleCN":"该研究在收集数据之前就设定了显著性水平。","why":"A level is the word made into a number: the researcher fixes how improbable a result must be to count.","whyCN":"「水平」把这个词变成了数字：研究者预先规定结果要多不可能才算数。"},{"no":"06","title":"Meaning read into a detail","titleCN":"意味深长：细节被读出额外信息","definition":"the implied meaning that a small detail carries","definitionCN":"细微之处所承载的隐含意味","example":"There was significance in the fact that he arrived alone.","exampleCN":"他独自到场这件事颇有意味。","why":"Here the word returns to signs: a detail functions as a sign, and its significance is what it points to.","whyCN":"此处这个词回到符号：一个细节充当符号，其 significance 就是它所指向的东西。"},{"no":"07","title":"Importance of a place","titleCN":"地位分量：地点或建筑的重要性","definition":"the importance of a place, building or object in cultural or historical terms","definitionCN":"地点、建筑或物件在文化或历史层面的重要性","example":"The site was listed for its national significance.","exampleCN":"该遗址因其全国性意义而被列入名录。","why":"Heritage practice uses the word as an official measure: significance is what justifies protection.","whyCN":"遗产实务把这个词当作官方衡量尺度：significance 正是保护的理由。"},{"no":"08","title":"Mattering to a person","titleCN":"对个人的意义：与自身相关","definition":"the personal importance something has for an individual","definitionCN":"某事物对个人而言的重要性","example":"The letter had no public significance, but great significance for her.","exampleCN":"这封信没有公共意义，但对她意义重大。","why":"The scale of judgment shrinks to one life: what matters is measured against a single person's history.","whyCN":"判断的尺度缩小到一条生命：重要性以一个人的经历为参照来衡量。"}],"etymology":{"intro":{"en":"Significance comes from Latin significantia, from significare 'to make a sign, to mean', built on signum 'sign' and facere 'to make'. The dates below are approximate.","cn":"significance 出自拉丁 significantia，源自 significare「作出标记、表示」，由 signum「符号」与 facere「制造」构成。以下年代均为约数。"},"items":[{"era":"LATIN SIGNUM","en":"Latin signum meant 'mark, token, military standard'. It is well recorded, and its deeper origin is disputed; any older root would be a reconstruction.","cn":"拉丁 signum 意为「标记、凭证、军旗」。记录充分，但更深来源有争议；任何更早的词根都属重构。"},{"era":"SIGNIFICARE","en":"Significare 'to make signs, to indicate, to mean' combined signum with the facere family. The verb is common in classical Latin for both showing and meaning.","cn":"significare「作标记、指示、表示」把 signum 与 facere 词族组合起来。该动词在古典拉丁中既表示「显示」，也表示「意味着」，用法常见。"},{"era":"SIGNIFICANTIA","en":"The noun significantia named the quality of being a sign, that is, of pointing to something. In later Latin it also carried the sense of importance.","cn":"名词 significantia 命名的是「作为符号」的性质，即指向某物。后世拉丁也带上「重要性」之义。"},{"era":"ENGLISH ARRIVAL","en":"English significance appears in the seventeenth century, carrying both 'meaning' and 'importance'. The exact first citation is uncertain.","cn":"英语 significance 于 17 世纪出现，同时携带「含义」与「重要性」两义。最早确切书证年代存疑。"},{"era":"STATISTICS","en":"Twentieth-century statistics gave the word a technical meaning: a result is significant when chance alone would rarely produce it. The everyday and technical senses now coexist.","cn":"20 世纪统计学赋予该词技术含义：当仅凭偶然很少能产生某结果时，该结果就是显著的。日常义与技术义如今并行。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first attestation date only): the first English date is uncertain; the origin of signum before its 'mark' sense is debated and remains a reconstruction.","cn":"来源不确定（仅首见年代存疑）：英语首见年代存疑；signum 在「标记」义之前的来源有争议，仍属重构。"}]},"similar":{"note":{"en":"The first group holds same-family words that differ in part of speech; the second holds near-synonyms for importance or meaning.","cn":"第一组是同族词，区别在词性；第二组是表示重要性或含义的近义词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"significant","ipa":"/sɪɡˈnɪfɪkənt/","tag":"adjective, not noun","definition":"Describes something important or statistically unlikely by chance. Significance is the noun for that quality.","definitionCN":"描述某事物重要或统计上非偶然。significance 是命名该性质的名词。"},{"word":"signification","ipa":"/ˌsɪɡnɪfɪˈkeɪʃn/","tag":"meaning only, technical","definition":"Means 'the meaning of a word or sign' and never 'importance'. The two nouns split the old sense range.","definitionCN":"意为「词或符号的含义」，绝不表示「重要性」。两个名词分担了旧有的义域。"},{"word":"signify","ipa":"/ˈsɪɡnɪfaɪ/","tag":"verb","definition":"To mean or indicate something. It names the act of pointing; significance is what gets pointed to.","definitionCN":"意为表示或指示。它命名指向的动作；significance 是被指向的东西。"},{"word":"insignificance","ipa":"/ˌɪnsɪɡˈnɪfɪkəns/","tag":"direct negative","definition":"The state of being unimportant. It negates importance only, and is not used for statistical significance.","definitionCN":"无足轻重的状态。它只否定重要性义，不用于统计显著性。"}]},{"heading":"NEAR MEANING","entries":[{"word":"importance","ipa":"/ɪmˈpɔːtns/","tag":"plain weight","definition":"The state of mattering a great deal. It is broader and carries no sense of meaning or of statistics.","definitionCN":"关系重大的状态。它更宽泛，不含「含义」义，也不涉及统计。"},{"word":"meaning","ipa":"/ˈmiːnɪŋ/","tag":"what is expressed","definition":"What a word or action expresses. It matches the 'meaning' sense but not 'importance'.","definitionCN":"词或行为所表达的内容。它对应「含义」义，但不覆盖「重要性」。"},{"word":"implication","ipa":"/ˌɪmplɪˈkeɪʃn/","tag":"what follows indirectly","definition":"Something suggested without being stated. Significance may be the weight of a fact; an implication is what that fact entails.","definitionCN":"未明说而暗示的内容。significance 可以是一个事实的分量；implication 则是该事实所连带的东西。"},{"word":"relevance","ipa":"/ˈreləvəns/","tag":"bearing on the question","definition":"The quality of being connected to the matter at hand. Significance asks how much something matters; relevance asks whether it belongs in the discussion.","definitionCN":"与当前问题相关的性质。significance 问的是分量多重，relevance 问的是该不该进入讨论。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"signum 'sign' + facere 'make' + -antia: the quality of making a sign, hence of meaning something.","cn":"signum「符号」+ facere「制造」+ -antia：制造符号的性质，因而也就是「有意义」。"},{"en":"The family runs signify, sign, signal, significant, significance, significantly, signification.","cn":"同族词包括 signify、sign、signal、significant、significance、significantly、signification。"},{"en":"Fixed phrases mark the senses: statistical significance, of great significance, significance level.","cn":"固定搭配标出义项：统计显著性、意义重大、显著性水平。"},{"en":"significance and signification split the work: importance versus word meaning.","cn":"significance 与 signification 分工明确：前者是重要性，后者是词义。"},{"en":"In statistics the word means 'unlikely by chance', not 'important in real life'.","cn":"在统计学中，这个词意为「不大可能出于偶然」，而非「现实中很重要」。"}],"abstract":[{"en":"Picture a tiny weight that still tips the whole scale.","cn":"想象一枚很小的砝码，却让整台天平倾斜。"},{"en":"Picture a comma in a contract that changes what the sentence obliges.","cn":"想象合同里的一个逗号，改变了这句话所规定的义务。"},{"en":"Picture a single footprint that tells the reader who walked and when.","cn":"想象一个脚印，让读者知道谁走过、何时走过。"}]},"examples":[{"en":"The significance of the discovery was recognized only decades later.","cn":"这一发现的重要性要到几十年后才被认识到。"},{"en":"The difference was not statistically significant, so the hypothesis stood.","cn":"这一差异在统计上不显著，因此假设仍然成立。"},{"en":"She attached great significance to the timing of the letter.","cn":"她非常看重这封信的发出时机。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「sign（标记）+ ific（做出）+ ance（性质）」——能做出标记、指向某物的性质 → significance 意义、重要性","word":"significance"},"root":"拉丁 signum「符号」+ facere「制造」→ significare「表示」→ significantia「有所指的性质」→ 英语 significance。","sensesIntro":{"en":"Eight senses follow one pointer: something stands as a sign, and the word asks either what it points to or how much weight it carries.","cn":"八个义项沿同一个指向展开：某物充当符号，而这个词要么问它指向什么，要么问它有多重。"},"semanticMap":{"core":{"en":"CORE IMAGE: a small weight that nevertheless tips the whole scale.","cn":"核心意象：一枚小砝码，却让整台天平倾斜。"},"chain":["MAKE A SIGN","POINT TO A MEANING","CARRY WEIGHT","CHANGE WHAT FOLLOWS","BECOME A THRESHOLD","MATTER TO ONE PERSON"],"branches":[{"senses":"S2 · S6","en":"MEANING: the sign layer, where a word, gesture or small detail points beyond itself.","cn":"含义：符号层，词、手势或细节指向自身之外。"},{"senses":"S1 · S3","en":"WEIGHT: importance, whether judged by present impact or by future consequence.","cn":"分量：重要性，或按当下影响衡量，或按未来后果衡量。"},{"senses":"S4 · S5","en":"STATISTICAL THRESHOLD: significance becomes a computed improbability and a fixed level.","cn":"统计阈值：significance 变成可计算的不可能性与一个固定水平。"},{"senses":"S7","en":"OFFICIAL VALUE: heritage lists turn significance into a reason for protection.","cn":"官方价值：遗产名录把 significance 变成保护理由。"},{"senses":"S8","en":"PERSONAL SCALE: the same word measures what matters to a single life.","cn":"个人尺度：同一个词也衡量对一条生命而言重要的东西。"}]},"affixes":{"intro":{"en":"Significance is a Latin compound: a sign noun, a making verb, and an abstract noun suffix.","cn":"significance 是拉丁复合词：一个「符号」名词、一个「制造」动词，以及抽象名词后缀。"},"latinIntro":{"en":"Latin signum 'sign' plus facere 'to make' yields significare; -antia turns its participle into the abstract noun.","cn":"拉丁 signum「符号」加 facere「制造」产生 significare；-antia 把其分词转为抽象名词。"},"items":[{"word":"significance","structure":"significare + -antia (abstract noun)","meaning":"the quality of meaning something; importance","meaningCN":"有所指的性质；重要性","example":"The significance of the control group is easy to miss.","exampleCN":"对照组的意义容易被忽略。"},{"word":"significant","structure":"significare + -ant (present participle)","meaning":"meaning something; important","meaningCN":"有所指的；重要的","example":"A significant drop followed the policy.","exampleCN":"政策之后出现了显著下降。"},{"word":"signify","structure":"signum + facere","meaning":"to mean, indicate","meaningCN":"表示；意味着","example":"A red flag signifies danger.","exampleCN":"红旗表示危险。"},{"word":"signification","structure":"significare + -tio","meaning":"the meaning of a sign","meaningCN":"符号的含义","example":"The signification of the term shifted over time.","exampleCN":"这个术语的含义随时间变化。"},{"word":"sign","structure":"signum (mark)","meaning":"a mark that stands for something","meaningCN":"代表某物的标记","example":"A stop sign marks the junction.","exampleCN":"停车标志标出了这个路口。"},{"word":"signal","structure":"signum + -alis","meaning":"a sign sent to convey information","meaningCN":"传递信息的信号","example":"The signal faded behind the hill.","exampleCN":"信号在山后变弱了。"},{"word":"insignificance","structure":"in- (not) + significance","meaning":"lack of importance","meaningCN":"无足轻重","example":"The error was of complete insignificance.","exampleCN":"这个错误完全无关紧要。"},{"word":"design","structure":"de- (out) + signum (mark)","meaning":"to mark out a plan","meaningCN":"标画出计划；设计","example":"They designed the bridge in one winter.","exampleCN":"他们在一个冬天里设计出了这座桥。"}],"latinEntries":[{"word":"signum","structure":"signum, signi (n., second declension)","meaning":"mark, token, standard","meaningCN":"标记；凭证；军旗"},{"word":"significare","structure":"signum + facere","meaning":"to make signs, to mean","meaningCN":"作出标记；表示"},{"word":"significantia","structure":"significans + -ia (abstract noun)","meaning":"meaningfulness, significance","meaningCN":"有意义；重要性"}],"derivatives":[{"word":"significant","pos":"adj.","zh":"重要的；显著的"},{"word":"significantly","pos":"adv.","zh":"显著地"},{"word":"signify","pos":"v.","zh":"表示；意味着"},{"word":"signification","pos":"n.","zh":"含义；词义"},{"word":"insignificance","pos":"n.","zh":"无足轻重"}]}},{"word":"significantly","ipa_uk":"/sɪɡˈnɪfɪkəntli/","ipa_us":"/sɪɡˈnɪfɪkəntli/","definition_zh":"显著地；大幅度地；意味深长地；在统计意义上显著地","definition_en":"to a degree large enough to matter, or in a way that carries meaning","core_image":"两条曲线在图上分开，中间标着一段明显可见的落差","scene":"Yields rose significantly after the new irrigation channel was opened.","sceneCN":"这里 significantly 指「幅度明显、不可忽视地」（第 1 个义项：变化量达到值得注意的程度）；新水渠开通后产量明显上升。图中可辨识物件：产量折线、落差标注、水渠、量杯。","pos":[{"tag":"adv.","zh":"显著地；大幅度地；意味深长地；在统计意义上显著地"}],"collocations":[{"phrase":"significantly higher","zh":"明显更高"},{"phrase":"significantly lower","zh":"明显更低"},{"phrase":"significantly improve","zh":"显著改善"},{"phrase":"significantly increase","zh":"显著增加"},{"phrase":"differ significantly","zh":"存在显著差异"},{"phrase":"significantly more than","zh":"明显多于"}],"forms":[{"label":"形容词形式","form":"significant（重要的；显著的）"},{"label":"名词形式","form":"significance（重要性；显著性）"},{"label":"动词形式","form":"signify（表示；意味着）"},{"label":"比较级","form":"more significantly（更显著地）"},{"label":"最高级","form":"most significantly（最显著地）"},{"label":"反义副词","form":"insignificantly（微不足道地；不显著地）"}],"derivatives":[{"word":"significant","pos":"adj.","zh":"重要的；显著的"},{"word":"significance","pos":"n.","zh":"重要性；显著性"},{"word":"signify","pos":"v.","zh":"表示；意味着"},{"word":"insignificantly","pos":"adv.","zh":"不显著地；微不足道地"},{"word":"significantly","pos":"adv.","zh":"显著地"}],"senses":[{"no":"01","title":"By a noticeable amount","titleCN":"幅度明显：变化量足以被注意到","definition":"by an amount large enough to be noticed and to matter","definitionCN":"达到足以被注意到并产生影响的幅度","example":"Costs fell significantly once the old furnace was replaced.","exampleCN":"更换旧炉之后成本明显下降。","why":"The adverb adds -ly to significant, so it inherits the 'carrying weight' sense and applies it to a degree of change.","whyCN":"副词由 significant 加 -ly 构成，因此继承「有分量」之义，并把它用于变化的幅度。"},{"no":"02","title":"In a statistically significant way","titleCN":"统计上显著：偶然难以解释","definition":"in a way that reaches the threshold of statistical significance","definitionCN":"以达到统计显著性阈值的方式","example":"The two groups differed significantly on the pre-test.","exampleCN":"两组在前测中差异显著。","why":"Statistics reuses the everyday degree word for a computed threshold: the gap is large enough that chance rarely explains it.","whyCN":"统计学把这个日常程度词用于计算出的阈值：差距大到偶然难以解释。"},{"no":"03","title":"Meaningfully, in speech","titleCN":"意味深长：话里有额外信息","definition":"in a way that carries an implied meaning","definitionCN":"以带有隐含意味的方式","example":"She looked at him significantly and said nothing.","exampleCN":"她意味深长地看了他一眼，什么也没说。","why":"The 'meaning' layer of significance survives in this use: the manner itself becomes a sign.","whyCN":"significance 的「含义」层在此保留：方式本身成了符号。"},{"no":"04","title":"As an important point","titleCN":"更值得注意的是：引出重要一点","definition":"used to introduce a point the speaker considers most important","definitionCN":"用于引出说话者认为最重要的一点","example":"Significantly, none of the critics had read the report.","exampleCN":"值得注意的是，批评者中没有一个人读过这份报告。","why":"Sentence-initial use turns the adverb into a pointer: what follows is marked as carrying weight.","whyCN":"置于句首时，副词变成指示器：后文被标记为有分量。"},{"no":"05","title":"Comparatively, in data","titleCN":"在数据比较中：明显高于或低于","definition":"used with comparatives to mark a clear gap between two values","definitionCN":"与比较级连用，标出两个数值之间的明显落差","example":"The treated field yielded significantly more grain.","exampleCN":"处理过的田块产量明显更高。","why":"The adverb attaches to comparatives because the sense is relative: a gap is significant only against another value.","whyCN":"副词常附着于比较级，因为此义是相对的：落差只有相对于另一个数值才显著。"},{"no":"06","title":"In a way worth noting","titleCN":"足以构成差别：不是细枝末节","definition":"in a manner that makes a real difference rather than a trivial one","definitionCN":"以造成真实差别而非细枝末节的方式","example":"The policy significantly changed how permits are issued.","exampleCN":"这项政策显著改变了许可的发放方式。","why":"Importance applied to effect: the adverb asserts that the difference is not cosmetic.","whyCN":"重要性被用于效果：副词断言这一差别不是表面文章。"},{"no":"07","title":"To a considerable degree","titleCN":"相当程度上：修饰程度形容词","definition":"used as an intensifier with adjectives of difference or quality","definitionCN":"作为程度加强语，与表示差异或质量的形容词连用","example":"The new model is significantly more efficient.","exampleCN":"新型号效率高得多。","why":"As an intensifier the adverb has drifted toward 'considerably', a common path for degree words.","whyCN":"作为加强语，这个副词已向「相当大地」漂移，这是程度词的常见路径。"},{"no":"08","title":"In an official assessment","titleCN":"在正式评估中：具有重要地位","definition":"in evaluation language, to a degree that affects a formal judgment","definitionCN":"在评估语言中，达到影响正式判断的程度","example":"The survey significantly influenced the heritage listing.","exampleCN":"这次调查对遗产列入产生了显著影响。","why":"Institutional assessment uses the word for weight that changes a decision, not merely for size.","whyCN":"机构评估用这个词表示能改变决定的分量，而不仅是规模。"}],"etymology":{"intro":{"en":"Significantly is an English adverb from significant plus -ly; significant itself comes from Latin significans, the participle of significare 'to mean'. The dates below are approximate.","cn":"significantly 是英语副词，由 significant 加 -ly 构成；significant 本身出自拉丁 significans，即 significare「表示」的分词。以下年代均为约数。"},"items":[{"era":"LATIN PARTICIPLE","en":"Significans, the present participle of significare, meant 'making a sign, meaning'. English took the participle stem as the adjective significant.","cn":"significare 的现在分词 significans 意为「作出标记的、表示着的」。英语取该分词词干作为形容词 significant。"},{"era":"ENGLISH -LY","en":"Old English -lice formed manner adverbs, and its descendant -ly attached to the borrowed adjective. The result names the manner in which something is significant.","cn":"古英语 -lice 构成方式副词，其后代 -ly 附着于这个借来的形容词。结果命名的是「以何种方式显著」。"},{"era":"COINAGE","en":"The adverb is formed inside English rather than borrowed from Latin; no classical Latin adverb corresponds to it. Its early uses belong to the seventeenth and eighteenth centuries.","cn":"这个副词是在英语内部构成的，并非从拉丁借入；古典拉丁中没有对应副词。其早期用法属于 17、18 世纪。"},{"era":"SCIENCE","en":"Nineteenth- and twentieth-century science made the adverb a standard marker of measured difference: results differ significantly, yields rise significantly.","cn":"19、20 世纪的科学把这个副词变成衡量差异的标准标记：结果差异显著、产量显著上升。"},{"era":"MODERN USE","en":"Today the word works chiefly as a degree adverb and as a sentence-initial pointer to an important point, a use that grew in journalistic writing.","cn":"今天它主要作程度副词，也作句首指示语引出要点，后一用法在新闻写作中壮大起来。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first attestation date only): the first English citation of significantly is uncertain and usually placed in the seventeenth century.","cn":"来源不确定（仅首见年代存疑）：significantly 的英语首见书证存疑，通常定在 17 世纪。"}]},"similar":{"note":{"en":"The first group holds same-family forms that differ in part of speech; the second holds degree adverbs that are often interchangeable but not identical.","cn":"第一组是同族形式，区别在词性；第二组是程度副词，常可互换但并不等同。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"significant","ipa":"/sɪɡˈnɪfɪkənt/","tag":"adjective","definition":"Modifies a noun: a significant change. The adverb modifies a verb or adjective: changed significantly.","definitionCN":"修饰名词：a significant change。副词则修饰动词或形容词：changed significantly。"},{"word":"significance","ipa":"/sɪɡˈnɪfɪkəns/","tag":"noun","definition":"The quality itself. It cannot stand where the adverb stands: one does not say 'rose significance'.","definitionCN":"指该性质本身。它不能出现在副词的位置：不能说 rose significance。"},{"word":"significatively","ipa":"/sɪɡˈnɪfɪkətɪvli/","tag":"rare, meaning-focused","definition":"A rare adverb meaning 'in a way that indicates something'. Standard usage prefers significantly for both senses.","definitionCN":"罕用副词，意为「以指示某物的方式」。标准用法在两个义项上都更倾向 significantly。"},{"word":"insignificantly","ipa":"/ˌɪnsɪɡˈnɪfɪkəntli/","tag":"negated adverb","definition":"The direct negative: by an amount too small to matter. In statistics it means the threshold was not reached.","definitionCN":"直接的否定副词：幅度小到无关紧要。统计学中表示未达到阈值。"}]},{"heading":"NEAR MEANING","entries":[{"word":"substantially","ipa":"/səbˈstænʃəli/","tag":"large in amount","definition":"To a large degree. It stresses size, while significantly also implies that the size matters for a judgment.","definitionCN":"在很大程度上。它强调规模，而 significantly 还暗含这个规模对判断有意义。"},{"word":"considerably","ipa":"/kənˈsɪdərəbli/","tag":"degree intensifier","definition":"By a good deal. It is a plain degree word, with none of the statistical or 'meaning' associations.","definitionCN":"相当多地。它是纯粹的程度词，不带统计联想或「含义」联想。"},{"word":"markedly","ipa":"/ˈmɑːkɪdli/","tag":"easy to see","definition":"In a way that is clearly visible. It stresses perceptibility, while significantly stresses weight or statistical proof.","definitionCN":"以清晰可见的方式。它强调可察觉性，而 significantly 强调分量或统计证明。"},{"word":"notably","ipa":"/ˈnəʊtəbli/","tag":"worth attention","definition":"In a way deserving notice, often introducing an example. It points at salience rather than measured size.","definitionCN":"以值得注意的方式，常引出例证。它指向醒目程度，而非测得的规模。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"significant + -ly: the adverb form of 'carrying weight'.","cn":"significant + -ly：表示「有分量」的副词形式。"},{"en":"The family runs signify, significant, significance, significantly, insignificantly.","cn":"同族词包括 signify、significant、significance、significantly、insignificantly。"},{"en":"Fixed frames mark the senses: significantly higher, significantly improve, differ significantly.","cn":"固定框架标出义项：明显更高、显著改善、存在显著差异。"},{"en":"It loves comparatives: significantly more, significantly less, significantly better.","cn":"它常与比较级同现：明显更多、明显更少、明显更好。"},{"en":"Sentence-initial 'Significantly, ...' means 'note this point', not 'by a large amount'.","cn":"句首的 Significantly, ... 意为「注意这一点」，而非「大幅度地」。"}],"abstract":[{"en":"Picture two lines on a chart that visibly pull apart.","cn":"想象图表上两条线明显分开。"},{"en":"Picture a raised eyebrow that says more than the sentence spoken.","cn":"想象一次挑眉，比说出的句子传达更多。"},{"en":"Picture a marker pen underlining one line on a long page.","cn":"想象一支荧光笔在长页上划出其中一行。"}]},"examples":[{"en":"Rainfall in the region has declined significantly since 1980.","cn":"自 1980 年以来，该地区降雨量显著下降。"},{"en":"Significantly, the two independent teams reported the same figure.","cn":"值得注意的是，两个独立团队报告了相同的数字。"},{"en":"The drug significantly reduced recovery time in the trial.","cn":"在试验中，这种药显著缩短了康复时间。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「significant（有分量的）+ ly」——以有分量的方式 → significantly 显著地、明显地","word":"significantly"},"root":"拉丁 signum「符号」+ facere「制造」→ significare → significans → 英语 significant + -ly → significantly。","sensesIntro":{"en":"Eight senses follow one adverb through its uses: a gap big enough to matter, a gap proven by statistics, a look that means more, and a point flagged as worth attention.","cn":"八个义项让同一个副词走过它的各种用法：大到有分量的落差、统计上被证明的落差、意味深长的一瞥，以及被标为值得注意的要点。"},"semanticMap":{"core":{"en":"CORE IMAGE: two curves visibly separating, with the gap labelled.","cn":"核心意象：两条曲线明显分开，落差被标注出来。"},"chain":["CARRY WEIGHT","SHOW A VISIBLE GAP","PASS A THRESHOLD","MEAN MORE THAN SAID","FLAG A POINT","CHANGE A JUDGMENT"],"branches":[{"senses":"S1 · S7","en":"SIZE: the plain degree sense, from a noticeable change to a considerable one.","cn":"规模：纯粹的程度义，从可注意的变化到相当程度的变化。"},{"senses":"S2 · S5","en":"MEASURED GAP: statistics and comparisons give the gap a computed meaning.","cn":"可测落差：统计学与比较赋予落差以可计算的含义。"},{"senses":"S3","en":"SIGN: manner itself becomes a message, the oldest layer of significance.","cn":"符号：方式本身成为信息，这是 significance 最古老的一层。"},{"senses":"S4","en":"POINTER: sentence-initial use marks what follows as weighty.","cn":"指示：句首用法把后文标记为有分量。"},{"senses":"S6 · S8","en":"REAL DIFFERENCE: the change is not cosmetic, and institutions treat it as decision-shaping.","cn":"真实差别：变化不是表面文章，机构也把它视为能塑造决定的因素。"}]},"affixes":{"intro":{"en":"Significantly stacks the Latin sign-and-make compound with the participle suffix -ant and the English adverb ending -ly.","cn":"significantly 在拉丁「符号+制造」复合词上叠了分词后缀 -ant 与英语副词词尾 -ly。"},"latinIntro":{"en":"Latin signum and facere build significare, whose participle significans supplies the English adjective that -ly turns into an adverb.","cn":"拉丁 signum 与 facere 构成 significare，其分词 significans 提供英语形容词，再由 -ly 转为副词。"},"items":[{"word":"significantly","structure":"significant + -ly","meaning":"by a notable degree; meaningfully","meaningCN":"以显著的程度；意味深长地","example":"The rate dropped significantly.","exampleCN":"比率显著下降。"},{"word":"significant","structure":"significare + -ant","meaning":"important; statistically unlikely by chance","meaningCN":"重要的；统计上非偶然的","example":"The effect was significant.","exampleCN":"效应是显著的。"},{"word":"significance","structure":"significant + -ce","meaning":"importance; meaning","meaningCN":"重要性；含义","example":"The significance escaped no one.","exampleCN":"其意义无人不察。"},{"word":"signify","structure":"signum + facere","meaning":"to mean or indicate","meaningCN":"表示；指示","example":"A nod signified agreement.","exampleCN":"点头表示同意。"},{"word":"sign","structure":"signum","meaning":"a mark standing for something","meaningCN":"代表某物的标记","example":"The sign pointed left.","exampleCN":"标志指向左边。"},{"word":"signal","structure":"signum + -alis","meaning":"a transmitted sign","meaningCN":"传递出去的信号","example":"The signal reached the coast.","exampleCN":"信号传到了海岸。"},{"word":"insignificantly","structure":"in- (not) + significantly","meaning":"by too small a degree to matter","meaningCN":"幅度小到无关紧要地","example":"The two means differed insignificantly.","exampleCN":"两个均值差异不显著。"},{"word":"designate","structure":"de- + signum + -are","meaning":"to mark out, name officially","meaningCN":"标出；正式指定","example":"The area was designated a reserve.","exampleCN":"该区域被指定为保护区。"}],"latinEntries":[{"word":"signum","structure":"signum, signi (n., second declension)","meaning":"mark, sign","meaningCN":"标记；符号"},{"word":"significare","structure":"signum + facere","meaning":"to make signs, to mean","meaningCN":"作出标记；表示"},{"word":"-anter","structure":"-anter (adverbial ending from -ans participle)","meaning":"in the manner of (the participle)","meaningCN":"以（分词）的方式"}],"derivatives":[{"word":"significant","pos":"adj.","zh":"重要的；显著的"},{"word":"significance","pos":"n.","zh":"重要性；显著性"},{"word":"signify","pos":"v.","zh":"表示；意味着"},{"word":"insignificantly","pos":"adv.","zh":"不显著地"},{"word":"significantly","pos":"adv.","zh":"显著地"}]}},{"word":"simulation","ipa_uk":"/ˌsɪmjuˈleɪʃn/","ipa_us":"/ˌsɪmjuˈleɪʃn/","definition_zh":"模拟；仿真；模拟实验；假装；模拟装置","definition_en":"the imitation of a real process or situation, often by a model or computer, for study or training","core_image":"一间飞行训练舱里，屏幕上是云层，座椅随气流轻轻抖动","scene":"Pilots train in a simulation before they ever fly the real aircraft.","sceneCN":"这里 simulation 指「仿真训练装置」（第 3 个义项：用模型复现真实操作环境以供练习）；飞行员先在模拟舱训练，再上真机。图中可辨识物件：驾驶舱、投影云层、操纵杆、教员台。","pos":[{"tag":"n.","zh":"模拟；仿真；模拟实验；假装；模拟装置（可数或不可数，指装置或一次实验时用复数 simulations）"}],"collocations":[{"phrase":"computer simulation","zh":"计算机模拟"},{"phrase":"simulation model","zh":"仿真模型"},{"phrase":"flight simulation","zh":"飞行模拟"},{"phrase":"run a simulation","zh":"运行一次模拟"},{"phrase":"simulation of","zh":"对……的模拟"},{"phrase":"numerical simulation","zh":"数值模拟"}],"forms":[{"label":"复数","form":"simulations"},{"label":"动词形式","form":"simulate（模拟；假装）"},{"label":"形容词形式","form":"simulated（模拟的；仿制的）"},{"label":"施动者名词","form":"simulator（模拟器；仿真装置）"},{"label":"名词形式（相似性）","form":"similarity（相似性）"},{"label":"形容词形式（相似的）","form":"similar（相似的）"}],"derivatives":[{"word":"simulate","pos":"v.","zh":"模拟；仿真；假装"},{"word":"simulated","pos":"adj.","zh":"模拟的；仿制的"},{"word":"simulator","pos":"n.","zh":"模拟器；仿真装置"},{"word":"similar","pos":"adj.","zh":"相似的"},{"word":"dissimulate","pos":"v.","zh":"掩饰；假装"}],"senses":[{"no":"01","title":"Imitating a process","titleCN":"模拟过程：用模型复现真实运行","definition":"the imitation of the behaviour of a real system by a model, often a computer program","definitionCN":"用模型（常为计算机程序）再现真实系统的行为","example":"The simulation reproduced twenty years of erosion in four hours.","exampleCN":"这次模拟用四小时再现了二十年的侵蚀。","why":"Latin simulatio meant 'a copying or feigning', from simulare 'to make like', built on similis 'similar'; the noun begins as 'making something like'.","whyCN":"拉丁 simulatio 意为「模仿或假装」，出自 simulare「使相似」，而后者基于 similis「相似的」；这个名词的起点是「使某物相像」。"},{"no":"02","title":"A model's run","titleCN":"一次仿真运算：模型跑出的一组结果","definition":"one complete run of a model producing a set of predicted outcomes","definitionCN":"模型完整运行一次所产出的一组预测结果","example":"We ran a thousand simulations to estimate the range of sea level rise.","exampleCN":"我们跑了一千次模拟来估计海平面上升的区间。","why":"Countability arrived with computing: each run is a separate event, so the abstract noun became countable.","whyCN":"可数性随计算而来：每次运行都是独立事件，于是抽象名词变得可数。"},{"no":"03","title":"A training device","titleCN":"训练用仿真装置：可反复练习的假环境","definition":"an apparatus that reproduces conditions for practice or testing","definitionCN":"复现某种条件以供练习或测试的装置","example":"The hospital bought a simulation for practising emergency births.","exampleCN":"医院购置了一套用于演练紧急分娩的模拟装置。","why":"The abstract act turned into a concrete object: the thing that performs the imitation is called a simulation.","whyCN":"抽象动作转为具体物件：执行这种模仿的东西就被称为 simulation。"},{"no":"04","title":"Pretending an emotion","titleCN":"假装：做出并非真心的表现","definition":"the act of feigning a feeling or condition one does not have","definitionCN":"装作拥有某种并不真正具备的情感或状态","example":"His grief was simulation, and everyone at the table knew it.","exampleCN":"他的悲痛是假装的，桌上每个人都知道。","why":"This is the oldest sense: simulatio in Latin covered feigning, and English kept it alongside the technical use.","whyCN":"这是最古老的一层：拉丁 simulatio 本就涵盖假装，英语把这个义项与技术义一并保留。"},{"no":"05","title":"Simulation in statistics","titleCN":"统计模拟：用随机抽样近似结果","definition":"in statistics, generating random samples to approximate a distribution or probability","definitionCN":"统计学上指生成随机样本来近似某一分布或概率","example":"Monte Carlo simulation estimates the integral without solving it.","exampleCN":"蒙特卡洛模拟无需解出积分即可估计其值。","why":"Statistics uses imitation as a computational strategy: when the answer cannot be derived, it is acted out many times.","whyCN":"统计学把「模仿」当作计算策略：当答案无法推导时，就把它反复演出来。"},{"no":"06","title":"Simulation of a physical system","titleCN":"物理系统仿真：在方程中预演现实","definition":"in engineering and physics, solving a system's equations to predict its behaviour","definitionCN":"工程与物理中通过求解系统方程来预测其行为","example":"The bridge design was tested by simulation before any steel was cut.","exampleCN":"桥的设计在切任何钢材之前先经过仿真测试。","why":"Engineering extended the word to numerical prediction: a cheap copy of the structure runs before the costly real one exists.","whyCN":"工程把这个词延伸到数值预测：在昂贵的实物存在之前，先让一个廉价的复制品跑起来。"},{"no":"07","title":"Simulation of behaviour","titleCN":"行为模拟：让智能体模仿真实行为","definition":"in social science and computing, modelling the actions of people or agents","definitionCN":"社会科学与计算中，对人或智能体行为的建模","example":"The crowd simulation showed where bottlenecks would form.","exampleCN":"人群模拟显示出瓶颈会在哪里形成。","why":"The object imitated shifted from nature to people: agents are given rules and their behaviour is acted out.","whyCN":"被模仿的对象从自然转向人：给智能体设定规则，再演出的行为。"},{"no":"08","title":"Simulation as deception","titleCN":"伪装：以假象蒙混","definition":"a false appearance deliberately kept up to mislead","definitionCN":"为误导而刻意维持的虚假外表","example":"The ceasefire was a simulation of peace that lasted three weeks.","exampleCN":"那次停火是一场维持了三周的和平假象。","why":"Feigning enlarged to public events: what is put on for show, without substance, is called simulation.","whyCN":"假装扩大到公共事件：为展示而摆出、并无实质的东西，被称为 simulation。"}],"etymology":{"intro":{"en":"Simulation comes from Latin simulatio, from simulare 'to make like, to imitate', built on similis 'similar'. The dates below are approximate.","cn":"simulation 出自拉丁 simulatio，源自 simulare「使相似、模仿」，基于 similis「相似的」。以下年代均为约数。"},"items":[{"era":"LATIN SIMILIS","en":"Latin similis meant 'like, similar'. It is well recorded, and it also underlies similis-based words such as resemble and similar; its deeper origin is disputed.","cn":"拉丁 similis 意为「相像的、相似的」。记录充分，也支撑 resemble、similar 等词；其更深来源有争议。"},{"era":"SIMULARE","en":"The verb simulare meant 'to make like, to copy, and also to feign'. The feigning sense was present from early on, which is why the noun carries both imitation and pretence.","cn":"动词 simulare 意为「使相像、复制」，也表示「假装」。假装义很早就存在，因此这个名词同时承载「模仿」与「作假」。"},{"era":"SIMULATIO","en":"The noun simulatio covered 'a likeness, an imitation, a feigning'. Classical usage leans toward the negative, pretence.","cn":"名词 simulatio 涵盖「相似、模仿、假装」。古典用法偏向负面，即「作假」。"},{"era":"ENGLISH ARRIVAL","en":"English simulation appears in the Middle Ages through French, first meaning 'pretence'. The exact first citation is uncertain.","cn":"英语 simulation 经法语于中世纪出现，初义为「假装」。最早确切书证年代存疑。"},{"era":"COMPUTING","en":"From the mid-twentieth century simulation became primarily technical: a model imitating a system, and later a device reproducing conditions for training.","cn":"自 20 世纪中叶起，simulation 主要成为技术词：模型模仿系统，后又指复现条件以供训练的装置。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first attestation date only): the first English date is uncertain; the origin of similis before its 'like' sense is debated and any Indo-European root is a reconstruction.","cn":"来源不确定（仅首见年代存疑）：英语首见年代存疑；similis 在「相像」义之前的来源有争议，任何印欧词根均属重构。"}]},"similar":{"note":{"en":"The first group holds same-family words that differ in part of speech; the second holds near-synonyms for imitation or for a model.","cn":"第一组是同族词，区别在词性；第二组是表示模仿或模型的近义词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"simulate","ipa":"/ˈsɪmjuleɪt/","tag":"verb","definition":"To imitate or feign. It names the act; simulation is the act as a thing or the device that performs it.","definitionCN":"模拟或假装。它命名动作；simulation 则是作为事物的动作，或执行该动作的装置。"},{"word":"simulated","ipa":"/ˈsɪmjuleɪtɪd/","tag":"adjective","definition":"Describes something artificial made to resemble the real thing, as in simulated leather. It is a property, not a procedure.","definitionCN":"描述为仿照真品而造的人造物，如 simulated leather。它是属性，而非程序。"},{"word":"simulator","ipa":"/ˈsɪmjuleɪtə(r)/","tag":"the machine","definition":"The device that runs the imitation. Simulation can also mean the device, but simulator is the precise term.","definitionCN":"执行模仿的装置。simulation 也可指装置，但 simulator 是更精确的说法。"},{"word":"similar","ipa":"/ˈsɪmələ(r)/","tag":"same root, plain likeness","definition":"Means 'alike'. It shares similis but makes no claim about imitation or modelling.","definitionCN":"意为「相似的」。它同出 similis，但与模仿或建模无关。"}]},{"heading":"NEAR MEANING","entries":[{"word":"model","ipa":"/ˈmɒdl/","tag":"the representation","definition":"A simplified representation of a system. A model is the thing used; a simulation is the running of it.","definitionCN":"对系统的简化表示。模型是被使用的对象；模拟则是让它运行起来。"},{"word":"imitation","ipa":"/ˌɪmɪˈteɪʃn/","tag":"copying, often derogatory","definition":"The act of copying something, often with the implication of inferiority. Simulation is neutral in technical use.","definitionCN":"复制某物的行为，常含「次一等」的意味。simulation 在技术语境中是中性的。"},{"word":"emulation","ipa":"/ˌemjuˈleɪʃn/","tag":"matching a rival","definition":"Copying in order to equal or surpass. It carries rivalry, while simulation need not compete.","definitionCN":"为追平或超越而仿效。它带有竞争意味，而 simulation 不必涉及竞争。"},{"word":"replication","ipa":"/ˌreplɪˈkeɪʃn/","tag":"exact repeat","definition":"An exact copy or a repeated experiment. It stresses fidelity, while simulation stresses a working imitation.","definitionCN":"精确复制或重复实验。它强调忠实度，而 simulation 强调可运行的模仿。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"similis 'similar' + -atio: making something like the real thing.","cn":"similis「相似的」+ -atio：把某物做得像真的。"},{"en":"The family runs similar, simulate, simulated, simulation, simulator, dissimulate.","cn":"同族词包括 similar、simulate、simulated、simulation、simulator、dissimulate。"},{"en":"Fixed phrases mark the senses: computer simulation, simulation model, flight simulation, run a simulation.","cn":"固定搭配标出义项：计算机模拟、仿真模型、飞行模拟、运行一次模拟。"},{"en":"The same noun covers the act, one run, and the machine that does it.","cn":"同一个名词既覆盖动作、一次运行，也覆盖执行它的机器。"},{"en":"The Latin noun already meant 'pretence', which is why the word can still accuse someone of faking.","cn":"拉丁名词本就含「假装」，因此这个词至今仍可用来指责作假。"}],"abstract":[{"en":"Picture a cockpit on the ground, with clouds painted on a screen.","cn":"想象一间留在地面的驾驶舱，云层画在屏幕上。"},{"en":"Picture a scale model of a bridge bending under tiny weights.","cn":"想象一座桥梁的缩尺模型在小砝码下弯曲。"},{"en":"Picture an actor crying on cue, with no grief behind it.","cn":"想象一名演员按提示落泪，背后并无悲伤。"}]},"examples":[{"en":"The climate simulation predicted a wetter winter for the region.","cn":"这次气候模拟预测该地区冬季将更湿润。"},{"en":"Medical students practise on a simulation before touching a patient.","cn":"医学生在接触病人之前先在模拟装置上练习。"},{"en":"Her calm was a simulation that lasted until the door closed.","cn":"她的镇定是装出来的，一直撑到门关上。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「simil（相似）+ ation（行为）」——做出相似的东西 → simulation 模拟、仿真","word":"simulation"},"root":"拉丁 similis「相似的」→ simulare「使相似、模仿、假装」→ simulatio「模仿；假装」→ 英语 simulation。","sensesIntro":{"en":"Eight senses follow one imitation: something is made to behave like the real thing, and that copy can be a run of a model, a training machine, a statistical trick or a lie.","cn":"八个义项沿同一次模仿展开：某物被做得像真的，而这个复制品可以是一次模型运算、一台训练机器、一种统计手段，也可以是一句谎言。"},"semanticMap":{"core":{"en":"CORE IMAGE: a cockpit on the ground with painted clouds and a shaking seat.","cn":"核心意象：一间留在地面的驾驶舱，云层是画上去的，座椅在抖。"},"chain":["MAKE ALIKE","RUN THE MODEL","REPEAT THE RUN","BUILD THE MACHINE","TEST BEFORE BUILDING","FEIGN WHAT IS ABSENT"],"branches":[{"senses":"S1 · S6","en":"TECHNICAL IMITATION: a model reproduces a real process, whether natural or engineered.","cn":"技术模仿：模型再现真实过程，无论自然的还是工程的。"},{"senses":"S2 · S5","en":"COUNTED RUNS: each execution is a simulation, and random runs approximate an answer.","cn":"可数的运行：每次执行都是一次模拟，随机运行可逼近答案。"},{"senses":"S3 · S7","en":"OBJECTS AND AGENTS: the device imitates conditions, and agents imitate behaviour.","cn":"装置与智能体：装置模仿条件，智能体模仿行为。"},{"senses":"S4","en":"FEIGNING: the oldest Latin layer, where the copy is worn as a mask.","cn":"假装：最古老的拉丁层，复制品被当作面具戴上。"},{"senses":"S8","en":"PUBLIC PRETENCE: feigning scaled up to events presented as real.","cn":"公共假象：假装被放大为被呈现为真实的事件。"}]},"affixes":{"intro":{"en":"Simulation is a Latin likeness stem with a verb-forming suffix and an action-noun ending.","cn":"simulation 是拉丁「相似」词干加动词化后缀与动作名词词尾。"},"latinIntro":{"en":"Latin similis 'like' gives simulare 'to make like'; -atio turns the verb into the action noun simulatio.","cn":"拉丁 similis「相像」产生 simulare「使相像」；-atio 把动词转为动作名词 simulatio。"},"items":[{"word":"simulation","structure":"simulare + -atio (action noun)","meaning":"an imitation or a feigning","meaningCN":"模仿；假装","example":"The simulation took six hours to run.","exampleCN":"这次模拟运行了六小时。"},{"word":"simulate","structure":"similis + -are (verb)","meaning":"to imitate or feign","meaningCN":"模拟；假装","example":"The program simulates ocean currents.","exampleCN":"该程序模拟洋流。"},{"word":"simulated","structure":"simulate + -ed","meaning":"artificially made to resemble","meaningCN":"人工制成以仿真的","example":"The coat has simulated fur.","exampleCN":"这件外套用的是仿毛。"},{"word":"simulator","structure":"simulate + -or (agent)","meaning":"a device that reproduces conditions","meaningCN":"复现条件的装置","example":"The simulator logged every control input.","exampleCN":"模拟器记录了每一次操纵输入。"},{"word":"similar","structure":"similis + -aris","meaning":"alike","meaningCN":"相似的","example":"The two dialects are similar.","exampleCN":"这两种方言很相似。"},{"word":"similarity","structure":"similar + -ity","meaning":"the quality of being alike","meaningCN":"相似的性质","example":"Similarity between the species is striking.","exampleCN":"这两个物种的相似性很惊人。"},{"word":"dissimulate","structure":"dis- (apart) + simulare","meaning":"to hide one's feelings by pretence","meaningCN":"以假装掩饰情感","example":"He dissimulated his anger with a smile.","exampleCN":"他用微笑掩饰愤怒。"},{"word":"assimilate","structure":"ad- (to) + similis","meaning":"to make alike, absorb","meaningCN":"使相似；吸收同化","example":"The body assimilates the nutrients.","exampleCN":"身体吸收这些养分。"}],"latinEntries":[{"word":"similis","structure":"similis, simile (adjective, third declension)","meaning":"like, similar","meaningCN":"相像的；相似的"},{"word":"simulare","structure":"simulare (verb, first conjugation)","meaning":"to make like, imitate, feign","meaningCN":"使相像；模仿；假装"},{"word":"simulatio","structure":"simulatio, simulationis (f., third declension)","meaning":"imitation, pretence","meaningCN":"模仿；假装"}],"derivatives":[{"word":"simulate","pos":"v.","zh":"模拟；假装"},{"word":"simulated","pos":"adj.","zh":"模拟的；仿制的"},{"word":"simulator","pos":"n.","zh":"模拟器"},{"word":"similar","pos":"adj.","zh":"相似的"},{"word":"dissimulate","pos":"v.","zh":"掩饰；假装"}]}},{"word":"simultaneous","ipa_uk":"/ˌsɪmlˈteɪniəs/","ipa_us":"/ˌsaɪmlˈteɪniəs/","definition_zh":"同时发生的；同时进行的；同时存在的；联立的","definition_en":"happening or existing at exactly the same time","core_image":"两只秒表在同一刻同时按下，指针分毫不差","scene":"The two eruptions were simultaneous, though the volcanoes lie a thousand kilometres apart.","sceneCN":"这里 simultaneous 指「在同一时刻发生的」（第 1 个义项：时间上完全重合）；两座火山相距千里却同时喷发。图中可辨识物件：两座火山、同一时刻的钟面、震波记录、距离标尺。","pos":[{"tag":"adj.","zh":"同时发生的；同时进行的；同时存在的；（方程）联立的（无比较级，需用 more simultaneous 表示程度）"}],"collocations":[{"phrase":"simultaneous interpretation","zh":"同声传译"},{"phrase":"simultaneous equations","zh":"联立方程"},{"phrase":"simultaneous with","zh":"与……同时"},{"phrase":"simultaneous events","zh":"同时发生的事件"},{"phrase":"simultaneous release","zh":"同步发行"},{"phrase":"simultaneous translation","zh":"同声翻译"}],"forms":[{"label":"副词形式","form":"simultaneously（同时地）"},{"label":"名词形式","form":"simultaneity（同时性）"},{"label":"另一名词","form":"simultaneousness（同时性，较少用）"},{"label":"比较级","form":"more simultaneous（更接近同时的）"},{"label":"最高级","form":"most simultaneous（最接近同时的）"},{"label":"反义形式","form":"successive（相继的，反义对照）"}],"derivatives":[{"word":"simultaneously","pos":"adv.","zh":"同时地"},{"word":"simultaneity","pos":"n.","zh":"同时性"},{"word":"simultaneousness","pos":"n.","zh":"同时性"},{"word":"simulcast","pos":"n./v.","zh":"同步播出"},{"word":"simultaneous","pos":"adj.","zh":"同时的"}],"senses":[{"no":"01","title":"At the same moment","titleCN":"同一时刻：两个事件时间重合","definition":"happening at exactly the same moment","definitionCN":"在完全相同的时刻发生","example":"The two shots were simultaneous, and the race was called a tie.","exampleCN":"两声枪响同时发生，比赛被判为平局。","why":"Latin simul 'at the same time' plus -aneus formed simultaneus, an adjective that simply states co-occurrence in time.","whyCN":"拉丁 simul「同时」加 -aneus 构成 simultaneus，这个形容词只是陈述时间上的共现。"},{"no":"02","title":"Running in parallel","titleCN":"同时进行：两项活动并行推进","definition":"carried out at the same time rather than one after another","definitionCN":"同时开展，而非一项接一项","example":"The two laboratories ran simultaneous trials on the same vaccine.","exampleCN":"两个实验室对同一疫苗同时开展了试验。","why":"The same time relation applies to activities: parallel work is simultaneous work, and the contrast is with successive.","whyCN":"同样的时间关系适用于活动：并行的工作就是同时的工作，其对照词是 successive（相继的）。"},{"no":"03","title":"Existing together","titleCN":"同时存在：两种状态共处一时","definition":"existing at the same period, without one causing the other","definitionCN":"在同一时期存在，彼此并无因果关系","example":"The two styles were simultaneous in the same city.","exampleCN":"这两种风格在同一座城市同时存在。","why":"Coexistence extends the word from events to states: things need not start together to be simultaneous.","whyCN":"共在把词义从事件延伸到状态：事物不必同时开始，也可以说是同时的。"},{"no":"04","title":"Simultaneous interpretation","titleCN":"同声传译：说着听着一并进行","definition":"translation performed while the speaker is still talking","definitionCN":"在说话人仍在讲话时进行的翻译","example":"He worked as a simultaneous interpreter at the conference.","exampleCN":"他在会议上担任同声传译。","why":"Conference technology made the word a fixed term: the interpreter's speech overlaps the speaker's, hence 'simultaneous'.","whyCN":"会议技术让这个词成为固定术语：译员的说话与讲者重叠，故称「同时」。"},{"no":"05","title":"Simultaneous equations","titleCN":"联立方程：必须一并求解的方程组","definition":"in mathematics, equations that must be satisfied by the same set of values","definitionCN":"数学中必须由同一组数值同时满足的方程","example":"The pair of simultaneous equations has one solution.","exampleCN":"这对联立方程只有一组解。","why":"Mathematics borrowed the word for conditions that must hold at once, in the same solution.","whyCN":"数学借这个词表示必须同时成立的条件，即在同一组解中。"},{"no":"06","title":"Simultaneous in physics","titleCN":"物理上的同时性：依参照系而定","definition":"in relativity, the property of two events occurring at the same time in a given frame of reference","definitionCN":"相对论中，两事件在某一参照系下发生于同一时刻的性质","example":"Simultaneity is relative: two events simultaneous in one frame need not be in another.","exampleCN":"同时性是相对的：在一个参照系中同时的两事件，在另一个参照系中未必同时。","why":"Relativity turned the everyday word into a frame-dependent quantity, one of the sharpest changes in its history.","whyCN":"相对论把这个日常词变成依赖参照系的量，这是其历史上最剧烈的语义变化之一。"},{"no":"07","title":"Released at once","titleCN":"同步发行：多地同一时间推出","definition":"of a product or broadcast, made available everywhere at the same time","definitionCN":"指产品或节目在所有地方同一时间推出","example":"The film had a simultaneous release in forty countries.","exampleCN":"这部影片在四十个国家同步上映。","why":"Distribution uses the word to guarantee no market is ahead: the same clock governs every release.","whyCN":"发行用这个词来保证没有市场抢先：同一个时钟支配每一次发布。"},{"no":"08","title":"Happening at once in a body","titleCN":"体内同时发生：多个过程并存","definition":"in physiology, of processes occurring in the body at the same time","definitionCN":"生理学中指体内多个过程在同一时间发生","example":"Digestion and absorption are partly simultaneous in the small intestine.","exampleCN":"在小肠中，消化与吸收部分是同时进行的。","why":"Biology applies the word to overlapping internal processes, where sequence is partial rather than strict.","whyCN":"生物学把这个词用于体内重叠的过程，其间顺序只是部分的，而非严格的。"}],"etymology":{"intro":{"en":"Simultaneous is a Latin adjective built from simul 'at the same time' with the ending -aneus, probably through a later form simultaneus. The dates below are approximate.","cn":"simultaneous 是拉丁形容词，由 simul「同时」加词尾 -aneus 构成，可能经由后世形式 simultaneus。以下年代均为约数。"},"items":[{"era":"LATIN SIMUL","en":"Latin simul is an adverb meaning 'at the same time, together'. It is common in classical prose and is related to similis 'like' in the sense of 'together, alike'.","cn":"拉丁 simul 是副词，意为「同时、一起」。古典散文中常见，与 similis「相像」在「一起、类似」的意味上相关。"},{"era":"SIMULTANEUS","en":"Late Latin formed simultaneus 'existing at the same time'. The adjective is not classical, and its exact formation is uncertain: it may rest on a lost intermediate form.","cn":"后世拉丁构成 simultaneus「同时存在的」。这个形容词不属于古典拉丁，其确切构词存疑：可能建立在一个已失传的中间形式之上。"},{"era":"ENGLISH ARRIVAL","en":"English simultaneous appears in the seventeenth century, in learned writing about time and motion. The exact first citation is uncertain.","cn":"英语 simultaneous 于 17 世纪出现，见于关于时间与运动的学术写作。最早确切书证年代存疑。"},{"era":"TECHNOLOGY","en":"Nineteenth- and twentieth-century technology gave the word fixed uses: simultaneous telegraphy, simultaneous interpreting, simultaneous release.","cn":"19、20 世纪的技术赋予该词固定用法：同时电报、同声传译、同步发行。"},{"era":"RELATIVITY","en":"Einstein's 1905 paper on relativity made simultaneity a frame-dependent relation, and the word became a technical term in physics.","cn":"爱因斯坦 1905 年的相对论论文把同时性变成依赖参照系的关系，这个词由此成为物理学术语。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (root disputed): the formation of simultaneus is not securely explained and may involve a lost intermediate. Source uncertain (first attestation date only): the first English date is uncertain.","cn":"来源不确定（词根存疑）：simultaneus 的构词方式尚无确凿解释，可能涉及已失传的中间形式；来源不确定（仅首见年代存疑）：英语首见年代存疑。"}]},"similar":{"note":{"en":"The first group holds words that look close but state a different time relation; the second holds near-synonyms of co-occurrence.","cn":"第一组是形近但表达不同时间关系的词；第二组是表示共现的近义词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"simultaneously","ipa":"/ˌsɪmlˈteɪniəsli/","tag":"adverb","definition":"The adverb form, used of verbs: the two events happened simultaneously. The adjective modifies nouns.","definitionCN":"副词形式，用于动词：两件事同时发生。形容词则修饰名词。"},{"word":"spontaneous","ipa":"/spɒnˈteɪniəs/","tag":"look-alike, NOT related","definition":"Means 'unplanned, arising from inner impulse'. It comes from Latin sponte 'of one's own accord' and has nothing to do with time.","definitionCN":"意为「自发的、出于内在冲动的」。它出自拉丁 sponte「自愿」，与时间无关。"},{"word":"instantaneous","ipa":"/ˌɪnstənˈteɪniəs/","tag":"zero duration, not co-occurrence","definition":"Means 'occurring in an instant, with no duration'. Two instantaneous events may still be at different times.","definitionCN":"意为「瞬间发生、没有持续时间的」。两个瞬时事件仍可能处于不同时刻。"},{"word":"successive","ipa":"/səkˈsesɪv/","tag":"one after another","definition":"Following in sequence. It is the direct contrast: simultaneous events overlap, successive ones do not.","definitionCN":"按顺序相继。它是直接的反义对照：同时的事件重叠，相继的事件不重叠。"}]},{"heading":"NEAR MEANING","entries":[{"word":"concurrent","ipa":"/kənˈkʌrənt/","tag":"overlapping periods","definition":"Happening over the same period, not necessarily at the same instant. It is the usual word for long processes running in parallel.","definitionCN":"在同一时期发生，不必在同一瞬间。它是描述长期过程并行的常用词。"},{"word":"synchronous","ipa":"/ˈsɪŋkrənəs/","tag":"matched in timing","definition":"Happening at the same rate and in step. It stresses coordination of timing, while simultaneous stresses the same moment.","definitionCN":"以相同速率并保持同步地发生。它强调时间上的协调，而 simultaneous 强调同一时刻。"},{"word":"coincident","ipa":"/kəʊˈɪnsɪdənt/","tag":"falling together","definition":"Occurring at the same time, often by chance. It suggests coincidence, while simultaneous is neutral.","definitionCN":"同一时间发生，常含偶然之意。它暗示巧合，而 simultaneous 是中性的。"},{"word":"parallel","ipa":"/ˈpærəlel/","tag":"side by side","definition":"Developing side by side without meeting. It stresses independence of two tracks, not exact timing.","definitionCN":"并排发展而不相交。它强调两条路径的独立性，而非精确的时点。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"Latin simul 'at the same time' + -aneus: the adjective of co-occurrence.","cn":"拉丁 simul「同时」+ -aneus：表示共现的形容词。"},{"en":"The family runs simultaneous, simultaneously, simultaneity, simulcast.","cn":"同族词包括 simultaneous、simultaneously、simultaneity、simulcast。"},{"en":"Fixed phrases mark the senses: simultaneous interpretation, simultaneous equations, simultaneous release.","cn":"固定搭配标出义项：同声传译、联立方程、同步发行。"},{"en":"The key contrast is successive: simultaneous overlaps, successive queues up.","cn":"关键对照是 successive：同时的重叠，相继的排队。"},{"en":"In relativity, simultaneity is relative to the observer's frame, which is why the noun is simultaneity, not 'same time'.","cn":"在相对论中，同时性相对于观察者的参照系，这正是名词取 simultaneity 而非「同一时间」的原因。"}],"abstract":[{"en":"Picture two stopwatches clicked by the same thumb.","cn":"想象两只秒表被同一根拇指按下。"},{"en":"Picture two trains entering a station from opposite ends at the same second.","cn":"想象两列火车在同一秒从车站两端驶入。"},{"en":"Picture an interpreter speaking while the original voice is still in the room.","cn":"想象译员开口时，原声仍在房间里回荡。"}]},"examples":[{"en":"The two experiments were simultaneous, so the results could be compared directly.","cn":"两项实验同时进行，因此结果可以直接比较。"},{"en":"Simultaneous translation let the visiting scientists follow the lecture.","cn":"同声传译让来访的科学家能跟上讲座。"},{"en":"In one frame the flashes are simultaneous; in another they are not.","cn":"在某个参照系中两道闪光是同时的，在另一个参照系中则不是。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「simul（同时）+ taneous（……的）」——同一时间发生的 → simultaneous 同时的","word":"simultaneous"},"root":"拉丁 simul「同时」→ 后世拉丁 simultaneus「同时存在的」→ 英语 simultaneous。","sensesIntro":{"en":"Eight senses follow one clock reading: two things occupy the same moment, and the word can describe events, activities, styles, equations, releases or a frame-dependent physical relation.","cn":"八个义项沿同一次读时展开：两样东西占据同一时刻，这个词既可描述事件、活动、风格、方程、发行，也可描述依赖参照系的物理关系。"},"semanticMap":{"core":{"en":"CORE IMAGE: two stopwatches clicked by the same thumb.","cn":"核心意象：两只秒表被同一根拇指按下。"},"chain":["SAME MOMENT","RUN IN PARALLEL","COEXIST IN TIME","OVERLAP IN SPEECH","HOLD IN ONE SOLUTION","DEPEND ON THE FRAME"],"branches":[{"senses":"S1","en":"SAME INSTANT: the plainest sense, two events at one moment.","cn":"同一瞬间：最朴素的义项，两事件在一个时刻。"},{"senses":"S2 · S3","en":"OVERLAP: activities and states share a stretch of time without one causing the other.","cn":"重叠：活动与状态共享一段时间，彼此并无因果。"},{"senses":"S4 · S7","en":"TECHNICAL OVERLAP: interpreting and release scheduling both require exact co-timing.","cn":"技术性重叠：同传与发行排期都要求精确的同刻。"},{"senses":"S5","en":"MATHEMATICAL: conditions that must hold in one and the same solution.","cn":"数学：必须在同一组解中成立的条件。"},{"senses":"S6 · S8","en":"PHYSICS AND BODY: simultaneity becomes frame-dependent, or describes overlapping internal processes.","cn":"物理与身体：同时性变为依赖参照系，或描述体内重叠的过程。"}]},"affixes":{"intro":{"en":"Simultaneous is a Latin adverb of time turned into an adjective by the ending -aneus; it has no prefix and no productive suffix of its own.","cn":"simultaneous 是拉丁时间副词经 -aneus 词尾转为形容词；它没有前缀，也没有自身能产的独立后缀。"},"latinIntro":{"en":"Latin simul 'at the same time' supplies the stem; -aneus is a Latin adjective ending seen in words such as extraneus and spontaneus.","cn":"拉丁 simul「同时」提供词干；-aneus 是拉丁形容词词尾，见于 extraneus、spontaneus 等词。"},"items":[{"word":"simultaneous","structure":"simul + -aneus (adjective ending)","meaning":"occurring at the same time","meaningCN":"同时发生的","example":"The two signals were simultaneous.","exampleCN":"两个信号是同时的。"},{"word":"simultaneously","structure":"simultaneous + -ly","meaning":"at the same time","meaningCN":"同时地","example":"She read and took notes simultaneously.","exampleCN":"她一边读一边做笔记。"},{"word":"simultaneity","structure":"simultaneous + -ity","meaning":"the state of being at the same time","meaningCN":"同时的状态","example":"Relativity treats simultaneity as relative.","exampleCN":"相对论把同时性视为相对的。"},{"word":"simulcast","structure":"simul- + broadcast (blend)","meaning":"a broadcast sent on several channels at once","meaningCN":"同时通过多个频道播出的节目","example":"The concert was a simulcast on radio and television.","exampleCN":"这场音乐会通过广播与电视同步播出。"},{"word":"simul","structure":"simul (adverb, Latin)","meaning":"at the same time","meaningCN":"同时","example":"The Latin adverb survives only in compounds.","exampleCN":"这个拉丁副词只保留在复合词中。"},{"word":"spontaneous","structure":"sponte + -aneus","meaning":"arising of its own accord","meaningCN":"自发产生的","example":"The reaction was spontaneous.","exampleCN":"这个反应是自发的。"},{"word":"extraneous","structure":"extra + -aneus","meaning":"coming from outside, irrelevant","meaningCN":"来自外部的；无关的","example":"Remove extraneous detail from the report.","exampleCN":"删去报告中无关的细节。"},{"word":"concurrent","structure":"con- (together) + currere","meaning":"running together in time","meaningCN":"在时间上并行","example":"Two concurrent studies reached the same result.","exampleCN":"两项并行研究得出了相同结果。"}],"latinEntries":[{"word":"simul","structure":"simul (adverb)","meaning":"at the same time, together","meaningCN":"同时；一起"},{"word":"simultaneus","structure":"simul + -aneus (later Latin adjective)","meaning":"existing at the same time","meaningCN":"同时存在的"},{"word":"-aneus","structure":"-aneus, -a, -um (adjective ending)","meaning":"belonging to, of the nature of","meaningCN":"属于……的；具有……性质的"}],"derivatives":[{"word":"simultaneously","pos":"adv.","zh":"同时地"},{"word":"simultaneity","pos":"n.","zh":"同时性"},{"word":"simultaneousness","pos":"n.","zh":"同时性"},{"word":"simulcast","pos":"n.","zh":"同步播出"},{"word":"simultaneous","pos":"adj.","zh":"同时的"}]}},{"word":"simultaneously","ipa_uk":"/ˌsɪmlˈteɪniəsli/","ipa_us":"/ˌsaɪmlˈteɪniəsli/","definition_zh":"同时地；同步地；一并地","definition_en":"at the same time, with two or more things happening together","core_image":"两只手在同一秒按下两个不同的开关","scene":"The system updates the two databases simultaneously, so neither can lag behind.","sceneCN":"这里 simultaneously 指「在同一时刻一并地」（第 1 个义项：多个动作时间完全重合）；系统同时更新两个数据库，两者都不会落后。图中可辨识物件：两个数据库图标、同步指示、时钟、连线。","pos":[{"tag":"adv.","zh":"同时地；同步地；一并地"}],"collocations":[{"phrase":"occur simultaneously","zh":"同时发生"},{"phrase":"work simultaneously","zh":"同时工作"},{"phrase":"simultaneously with","zh":"与……同时"},{"phrase":"launched simultaneously","zh":"同步推出"},{"phrase":"simultaneously translate","zh":"同声翻译"},{"phrase":"act simultaneously","zh":"同时采取行动"}],"forms":[{"label":"形容词形式","form":"simultaneous（同时的）"},{"label":"名词形式","form":"simultaneity（同时性）"},{"label":"另一名词","form":"simultaneousness（同时性，较少用）"},{"label":"比较级","form":"more simultaneously（更接近同时地）"},{"label":"最高级","form":"most simultaneously（最接近同时地）"},{"label":"反义副词","form":"successively（相继地）"}],"derivatives":[{"word":"simultaneous","pos":"adj.","zh":"同时的"},{"word":"simultaneity","pos":"n.","zh":"同时性"},{"word":"simultaneousness","pos":"n.","zh":"同时性"},{"word":"simulcast","pos":"n.","zh":"同步播出"},{"word":"simultaneously","pos":"adv.","zh":"同时地"}],"senses":[{"no":"01","title":"At one and the same moment","titleCN":"同一时刻：两个动作时间重合","definition":"in such a way that two or more actions happen at the same moment","definitionCN":"使两个或更多动作在同一时刻发生的方式","example":"The lights dimmed and the music started simultaneously.","exampleCN":"灯光暗下与音乐响起是同时的。","why":"The adverb adds -ly to simultaneous, so it states co-occurrence as the manner of an action.","whyCN":"副词由 simultaneous 加 -ly 构成，因此它把共现陈述为动作的方式。"},{"no":"02","title":"In parallel processes","titleCN":"并行推进：多项工作同时开展","definition":"in a manner in which several processes run side by side","definitionCN":"多个过程并排推进的方式","example":"The team worked simultaneously on the design and the budget.","exampleCN":"团队同时推进设计与预算两项工作。","why":"The adverb moves from a single instant to a stretch of time, describing parallel rather than point-like coincidence.","whyCN":"副词从单一瞬间扩展到一段时间，描述并行而非点状的共现。"},{"no":"03","title":"Interpreting while speaking","titleCN":"同声进行：说着译着","definition":"of translation, performed while the original speech continues","definitionCN":"指翻译在原话仍在进行时完成","example":"She translated simultaneously for three hours without a break.","exampleCN":"她连续同声翻译了三个小时没有休息。","why":"The fixed technical phrase simultaneous interpretation produced this adverbial use, where the overlap is of voices.","whyCN":"同声传译这一固定术语产生了这个副词用法，此处重叠的是两个声音。"},{"no":"04","title":"At once, on several fronts","titleCN":"多线同时：一次动作覆盖多处","definition":"of an action applied to several places or targets at the same time","definitionCN":"同一动作在同一时间作用于多个地点或对象","example":"The campaign was launched simultaneously in five cities.","exampleCN":"这场活动在五个城市同时启动。","why":"Distribution and planning use the adverb to guarantee that no site starts first.","whyCN":"发行与规划用这个副词来保证没有任何一处先开始。"},{"no":"05","title":"Coexisting at one time","titleCN":"共处一时：两种状态同时成立","definition":"of states, holding at the same period","definitionCN":"指两种状态在同一时期成立","example":"The species lived simultaneously in the north and the south.","exampleCN":"该物种在南北两地同时生存。","why":"The adverb can describe coexistence as well as co-action: the same clock covers both.","whyCN":"副词既可描述共在，也可描述共动：同一个时钟覆盖两者。"},{"no":"06","title":"Satisfied at once in equations","titleCN":"联立成立：同组数值一并满足","definition":"of mathematical conditions, satisfied by the same values","definitionCN":"指数学条件被同一组数值一并满足","example":"The two constraints must hold simultaneously.","exampleCN":"这两个约束必须同时成立。","why":"Mathematics uses the adverb for conditions that cannot be met one after another, only together.","whyCN":"数学用这个副词表示不能逐一满足、只能一并成立的条件。"},{"no":"07","title":"At the same reading in physics","titleCN":"物理上的同刻：同一参照系内","definition":"in relativity, occurring at the same coordinate time within one frame","definitionCN":"相对论中指在同一参照系内发生于同一坐标时间","example":"The clocks struck simultaneously in the station frame.","exampleCN":"在车站参照系中，这些钟是同时敲响的。","why":"The adverb inherits the frame dependence of the noun: 'simultaneously' always needs an implicit observer.","whyCN":"副词继承了名词的参照系依赖性：「同时地」总需要一个隐含的观察者。"},{"no":"08","title":"Doing two things at once","titleCN":"一心二用：一个人同时做两事","definition":"of a person, doing two things at the same time","definitionCN":"指一个人同时做两件事","example":"He listened to the lecture and sketched the equipment simultaneously.","exampleCN":"他一边听讲座一边速写设备。","why":"The everyday sense applies the word to divided attention, the most familiar use for learners.","whyCN":"日常义把这个词用于分散的注意力，这是学习者最熟悉的用法。"}],"etymology":{"intro":{"en":"Simultaneously is the English adverb of simultaneous, from Latin simul 'at the same time'. The dates below are approximate.","cn":"simultaneously 是 simultaneous 的英语副词，源自拉丁 simul「同时」。以下年代均为约数。"},"items":[{"era":"LATIN SIMUL","en":"The Latin adverb simul meant 'at the same time, together'. It supplied the stem but never formed a classical adverb in -e that English could borrow.","cn":"拉丁副词 simul 意为「同时、一起」。它提供了词干，但古典拉丁并未形成可被英语借用的 -e 副词。"},{"era":"ENGLISH -LY","en":"The English adverb is formed inside the language by adding -ly to simultaneous. No direct Latin model exists, so the word is an English coinage.","cn":"这个英语副词是在语言内部由 simultaneous 加 -ly 构成的。并无直接拉丁范本，因此该词属英语自造。"},{"era":"EARLY USE","en":"The adverb appears in learned prose after the adjective, in the eighteenth century, chiefly in discussions of motion and time. The exact first citation is uncertain.","cn":"副词在形容词之后出现于 18 世纪的学术散文，主要用于讨论运动与时间。最早确切书证年代存疑。"},{"era":"INDUSTRY AND MEDIA","en":"Nineteenth-century telegraphy and twentieth-century broadcasting made the adverb routine: messages arrive simultaneously, programmes go out simultaneously.","cn":"19 世纪电报与 20 世纪广播让这个副词成为日常：消息同时抵达，节目同时播出。"},{"era":"COMPUTING","en":"In computing the adverb describes parallel execution, and it now appears in ordinary instructions: the two files update simultaneously.","cn":"在计算领域，该副词描述并行执行，如今也出现在普通说明中：两个文件同时更新。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (root disputed): the Latin adjective simultaneus behind the adverb is not securely explained. Source uncertain (first attestation date only): the first English date of the adverb is uncertain.","cn":"来源不确定（词根存疑）：副词背后的拉丁形容词 simultaneus 构词尚无确凿解释；来源不确定（仅首见年代存疑）：副词的英语首见年代存疑。"}]},"similar":{"note":{"en":"The first group holds the adjective and look-alike adverbs; the second holds near-synonyms of timing.","cn":"第一组是形容词与形近副词；第二组是表示时间关系的近义词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"simultaneous","ipa":"/ˌsɪmlˈteɪniəs/","tag":"adjective","definition":"Modifies a noun: a simultaneous launch. The adverb modifies a verb: launched simultaneously.","definitionCN":"修饰名词：a simultaneous launch。副词修饰动词：launched simultaneously。"},{"word":"spontaneously","ipa":"/spɒnˈteɪniəsli/","tag":"look-alike, NOT related","definition":"Means 'without planning, of its own accord'. It comes from Latin sponte and says nothing about timing.","definitionCN":"意为「未经计划、自发地」。它出自拉丁 sponte，与时间无关。"},{"word":"instantaneously","ipa":"/ˌɪnstənˈteɪniəsli/","tag":"zero duration","definition":"Means 'in an instant'. Two events can be instantaneous and still occur at different times.","definitionCN":"意为「在瞬间」。两个瞬时事件仍可在不同时间发生。"},{"word":"successively","ipa":"/səkˈsesɪvli/","tag":"direct opposite","definition":"One after another. It is the clear contrast: simultaneously overlaps, successively queues.","definitionCN":"一个接一个。它是明确的对照：同时的重叠，相继的排队。"}]},{"heading":"NEAR MEANING","entries":[{"word":"concurrently","ipa":"/kənˈkʌrəntli/","tag":"same period","definition":"Over the same stretch of time, not necessarily at one instant. It suits long processes better than the adverb of an instant.","definitionCN":"在同一段时间内，不必在同一瞬间。它比「瞬间」副词更适合长期过程。"},{"word":"in unison","ipa":"/ɪn ˈjuːnɪsn/","tag":"together as one","definition":"Acting together in exact agreement. It stresses coordination of action, while simultaneously only stresses timing.","definitionCN":"完全一致地共同行动。它强调行动的协调，而 simultaneously 只强调时间。"},{"word":"at once","ipa":"/ət wʌns/","tag":"informal, also 'immediately'","definition":"Means both 'simultaneously' and 'immediately', so it is ambiguous where precision matters.","definitionCN":"既表示「同时」，也表示「立刻」，因此在需要精确处会有歧义。"},{"word":"in parallel","ipa":"/ɪn ˈpærəlel/","tag":"side by side","definition":"Of processes, running independently side by side. It is common in technical writing for systems, not for moments.","definitionCN":"指过程并排独立运行。它在技术写作中用于系统，而不用于时刻。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"simultaneous + -ly: the adverb of one shared moment.","cn":"simultaneous + -ly：表示共享同一时刻的副词。"},{"en":"The family runs simultaneous, simultaneously, simultaneity, simulcast.","cn":"同族词包括 simultaneous、simultaneously、simultaneity、simulcast。"},{"en":"Fixed frames mark the senses: occur simultaneously, work simultaneously, launched simultaneously.","cn":"固定框架标出义项：同时发生、同时工作、同步推出。"},{"en":"The opposite adverb is successively: one after another rather than side by side.","cn":"反义副词是 successively：一个接一个，而非并排。"},{"en":"Watch the spelling: one m after the i, and -aneously, not -aniously.","cn":"注意拼写：i 之后只有一个 m，词尾是 -aneously 而非 -aniously。"}],"abstract":[{"en":"Picture two hands pressing two switches in the same second.","cn":"想象两只手在同一秒按下两个开关。"},{"en":"Picture two clocks on one wall, their pendulums swinging in step.","cn":"想象同一面墙上的两只钟，摆锤同步摆动。"},{"en":"Picture a voice and its echo arriving together instead of one after the other.","cn":"想象一个声音与它的回声同时抵达，而不是先后到达。"}]},"examples":[{"en":"The two valves open simultaneously, so pressure never builds up.","cn":"两个阀门同时打开，因此压力不会积聚。"},{"en":"She was taking notes and listening simultaneously throughout the lecture.","cn":"整场讲座她都在一边记笔记一边听。"},{"en":"The new edition appeared simultaneously in print and online.","cn":"新版纸质版与网络版同步推出。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「simul（同时）+ taneously（地）」——在同一时间地 → simultaneously 同时地","word":"simultaneously"},"root":"拉丁 simul「同时」→ simultaneus → 英语 simultaneous + -ly → simultaneously。","sensesIntro":{"en":"Eight senses follow one shared second: two actions land on the same instant, and the word stretches from a single moment to parallel work, overlapping voices, joint conditions and a frame-bound physical reading.","cn":"八个义项沿同一个共享的秒展开：两个动作落在同一瞬间，而这个词从单一时刻延伸到并行工作、重叠的声音、联立的条件与受参照系约束的物理读法。"},"semanticMap":{"core":{"en":"CORE IMAGE: two hands pressing two switches in the same second.","cn":"核心意象：两只手在同一秒按下两个开关。"},"chain":["SAME SECOND","RUN SIDE BY SIDE","OVERLAP IN VOICE","COVER MANY PLACES","HOLD TOGETHER","READ WITHIN A FRAME"],"branches":[{"senses":"S1","en":"THE INSTANT: the plainest adverbial sense, co-action at one moment.","cn":"瞬间：最朴素的副词义，一个时刻的共同行动。"},{"senses":"S2 · S5","en":"THE STRETCH: parallel processes and coexisting states share a period, not a point.","cn":"时段：并行过程与共在状态共享一段时间，而非一个点。"},{"senses":"S3 · S4","en":"OVERLAP AT SCALE: voices overlap in interpreting, and releases cover many cities at once.","cn":"规模性重叠：同传中声音重叠，发行同时覆盖多座城市。"},{"senses":"S6","en":"JOINT CONDITIONS: equations must be satisfied together, never in turn.","cn":"联立条件：方程必须一并满足，绝不能轮流满足。"},{"senses":"S7 · S8","en":"FRAME AND PERSON: simultaneity depends on an observer, and one person can do two things at once.","cn":"参照系与人：同时性依赖观察者，而一个人也可以同时做两件事。"}]},"affixes":{"intro":{"en":"Simultaneously is a Latin time adverb plus a Latin adjective ending, closed by the English adverb suffix -ly.","cn":"simultaneously 是拉丁时间副词加拉丁形容词词尾，最后以英语副词后缀 -ly 收尾。"},"latinIntro":{"en":"Latin simul 'at the same time' with -aneus gives simultaneus, and English -ly turns it into an adverb.","cn":"拉丁 simul「同时」加 -aneus 得 simultaneus，英语 -ly 再把它转为副词。"},"items":[{"word":"simultaneously","structure":"simultaneous + -ly","meaning":"at the same time","meaningCN":"同时地","example":"The two alarms sounded simultaneously.","exampleCN":"两个警报同时响起。"},{"word":"simultaneous","structure":"simul + -aneus","meaning":"occurring at the same time","meaningCN":"同时发生的","example":"Their arrival was simultaneous.","exampleCN":"他们同时到达。"},{"word":"simultaneity","structure":"simultaneous + -ity","meaning":"the state of being simultaneous","meaningCN":"同时的状态","example":"Simultaneity depends on the frame.","exampleCN":"同时性取决于参照系。"},{"word":"simulcast","structure":"simul- + broadcast","meaning":"simultaneous broadcast","meaningCN":"同步播出","example":"The match was a simulcast.","exampleCN":"这场比赛是同步直播的。"},{"word":"simul","structure":"simul (adverb)","meaning":"at the same time","meaningCN":"同时","example":"Simul survives in English compounds.","exampleCN":"simul 只保留在英语复合词中。"},{"word":"concurrently","structure":"con- + currere + -ly","meaning":"over the same period","meaningCN":"在同一时期地","example":"Two projects ran concurrently.","exampleCN":"两个项目同时进行。"},{"word":"successively","structure":"successive + -ly","meaning":"one after another","meaningCN":"相继地","example":"The samples were tested successively.","exampleCN":"样本被逐个测试。"},{"word":"spontaneously","structure":"sponte + -aneus + -ly","meaning":"of its own accord","meaningCN":"自发地","example":"The crowd applauded spontaneously.","exampleCN":"人群自发鼓掌。"}],"latinEntries":[{"word":"simul","structure":"simul (adverb)","meaning":"at the same time","meaningCN":"同时"},{"word":"simultaneus","structure":"simul + -aneus","meaning":"existing at the same time","meaningCN":"同时存在的"},{"word":"-aneus","structure":"-aneus, -a, -um (adjective ending)","meaning":"of the nature of","meaningCN":"具有……性质的"}],"derivatives":[{"word":"simultaneous","pos":"adj.","zh":"同时的"},{"word":"simultaneity","pos":"n.","zh":"同时性"},{"word":"simultaneousness","pos":"n.","zh":"同时性"},{"word":"simulcast","pos":"n.","zh":"同步播出"},{"word":"simultaneously","pos":"adv.","zh":"同时地"}]}},{"word":"specialization","ipa_uk":"/ˌspesɪəlaɪˈzeɪʃn/","ipa_us":"/ˌspesɪəlaɪˈzeɪʃn/","definition_zh":"专业化；专门化；专业领域；专化；（生物的）特化","definition_en":"the process of concentrating on one narrow field, or a narrow field someone concentrates on","core_image":"一棵树从主干分出许多细枝，每根枝只朝一个方向生长","scene":"The division of labour depends on specialization: each workshop makes only one part.","sceneCN":"这里 specialization 指「专业化分工」（第 1 个义项：把工作集中于某一环节）；分工依赖专业化，每个车间只做一个零件。图中可辨识物件：车间、单一零件、分工流程图、工具箱。","pos":[{"tag":"n.","zh":"专业化；专门化；专业领域；专化；（生物）特化（可数或不可数，指具体专业方向时用复数 specializations）"}],"collocations":[{"phrase":"specialization in","zh":"在……方面的专长"},{"phrase":"division of labour and specialization","zh":"分工与专业化"},{"phrase":"economic specialization","zh":"经济专业化"},{"phrase":"niche specialization","zh":"生态位特化"},{"phrase":"a specialization in","zh":"……专业方向"},{"phrase":"specialization of function","zh":"功能专门化"}],"forms":[{"label":"复数","form":"specializations"},{"label":"英式拼写","form":"specialisation"},{"label":"动词形式","form":"specialize（专门从事；特化）"},{"label":"形容词形式","form":"specialized（专门的；特化的）"},{"label":"形容词形式","form":"special（特殊的；专门的）"},{"label":"反义名词","form":"generalization（概括；一般化）"}],"derivatives":[{"word":"specialize","pos":"v.","zh":"专门从事；专攻；特化"},{"word":"specialized","pos":"adj.","zh":"专门的；专用的；特化的"},{"word":"special","pos":"adj.","zh":"特殊的；专门的"},{"word":"specialist","pos":"n.","zh":"专家；专科医生"},{"word":"specialty","pos":"n.","zh":"专业；特长；特产"}],"senses":[{"no":"01","title":"Concentrating on one part","titleCN":"专业化：把精力集中到某一环节","definition":"the process of concentrating effort on one narrow activity or field","definitionCN":"把精力集中于某一狭窄活动或领域的过程","example":"Specialization raised output because each worker repeated one task.","exampleCN":"专业化提高了产量，因为每个工人只重复一项任务。","why":"Latin specialis meant 'belonging to a particular kind', from species 'kind'; the -ization suffix names the process of becoming of one kind.","whyCN":"拉丁 specialis 意为「属于某一类的」，出自 species「种类」；-ization 后缀命名「变得只属一类」的过程。"},{"no":"02","title":"A chosen field of expertise","titleCN":"专业方向：个人或机构所专攻的领域","definition":"a particular field in which a person or institution has concentrated its work","definitionCN":"个人或机构集中投入的某一特定领域","example":"Her specialization is the chemistry of soils.","exampleCN":"她的专业方向是土壤化学。","why":"The process noun turned concrete: the result of concentrating is a field one can name and claim.","whyCN":"过程名词具体化了：集中投入的结果变成一个可以命名并宣称的领域。"},{"no":"03","title":"Division of labour","titleCN":"分工专业化：社会把任务拆给不同人","definition":"in economics, the arrangement in which different people or regions produce different goods","definitionCN":"经济学中指不同人或地区生产不同商品的安排","example":"Trade grows when regional specialization is allowed to develop.","exampleCN":"当地区专业化得以发展时，贸易就会增长。","why":"Economics generalized the workshop image: the unit that concentrates may be a region or a whole country.","whyCN":"经济学推广了车间的意象：集中投入的单位可以是地区，甚至整个国家。"},{"no":"04","title":"Biological specialization","titleCN":"生物特化：适应某一特定生态位","definition":"in biology, adaptation to a narrow ecological niche or function","definitionCN":"生物学中指对狭窄生态位或功能的适应","example":"The beak shows extreme specialization for cracking one kind of seed.","exampleCN":"这种喙极度特化，只适合咬开一种种子。","why":"Evolution reuses the 'one kind' sense: an organism narrowed to one resource is specialized, and the process is specialization.","whyCN":"进化论沿用「只属一类」之义：被收窄到一种资源的生物就是特化的，这一过程即 specialization。"},{"no":"05","title":"Cellular differentiation","titleCN":"细胞分化：一类细胞只承担一种功能","definition":"in developmental biology, the narrowing of a cell's role to one function","definitionCN":"发育生物学中指细胞角色收窄为单一功能","example":"Specialization of cells makes a liver cell unable to become a nerve cell.","exampleCN":"细胞的特化使肝细胞无法变成神经细胞。","why":"Here the word names loss as well as gain: gaining a function costs the ability to do others.","whyCN":"此处这个词既指获得也指丧失：获得一种功能，代价是失去做其他事的能力。"},{"no":"06","title":"Medical specialty training","titleCN":"医学专科化：由专科医生诊治","definition":"in medicine, the concentration of practice in one branch of care","definitionCN":"医学中把诊疗集中于某一分支","example":"Specialization in surgery shortened recovery times.","exampleCN":"外科的专科化缩短了康复时间。","why":"Professional training made the word an institutional label: a specialty is certified, and the process is specialization.","whyCN":"专业训练把这个词变成建制标签：专科是被认证的，而这一过程就是 specialization。"},{"no":"07","title":"Specialization of function","titleCN":"功能专门化：器官只做一件事","definition":"in anatomy and engineering, the assignment of one function to one part","definitionCN":"解剖学与工程中指让一个部件只承担一种功能","example":"The heart's specialization for pumping left little tissue for anything else.","exampleCN":"心脏对泵血功能的专门化，使它几乎没有余力做别的事。","why":"Function replaces field: the narrowing happens to an organ or a part, not to a person.","whyCN":"功能取代了领域：收窄发生在器官或部件上，而非人身上。"},{"no":"08","title":"Narrowing of word meaning","titleCN":"词义狭窄化：词只保留一个用法","definition":"in linguistics, the restriction of a word's meaning to a narrower sense","definitionCN":"语言学中词义被限制到更窄的义项","example":"Specialization turned the general word for drink into the word for one beverage.","exampleCN":"词义狭窄化把泛指饮料的词变成了专指某一种饮品的词。","why":"Linguistics borrowed the process word for semantic narrowing: a word too becomes specialized to one kind.","whyCN":"语言学借这个表示过程的名词指语义收窄：一个词也会特化为只指一类。"},{"no":"09","title":"Narrow audience publishing","titleCN":"窄众出版：面向特定读者","definition":"in media, the targeting of content at a small defined audience","definitionCN":"媒体中把内容对准一小群明确受众","example":"Magazine specialization meant fewer readers but higher subscription prices.","exampleCN":"杂志的窄众化意味着读者更少，但订阅价格更高。","why":"Media markets apply the same narrowing: a title aims at one kind of reader and survives on depth.","whyCN":"媒体市场应用同样的收窄逻辑：一份刊物瞄准一类读者，靠深度生存。"}],"etymology":{"intro":{"en":"Specialization joins Latin specialis 'of a particular kind' with the English process suffix -ization. The dates below are approximate.","cn":"specialization 把拉丁 specialis「属于某一类的」与英语过程后缀 -ization 结合起来。以下年代均为约数。"},"items":[{"era":"LATIN SPECIES","en":"Latin species meant 'appearance, kind, sort'. It gave English species and special, and the deeper origin of the noun is debated.","cn":"拉丁 species 意为「外观、种类、类别」。它产生英语 species 与 special，其更深来源有争议。"},{"era":"SPECIALIS","en":"Specialis 'belonging to a particular kind' was used in later Latin for what is peculiar to one thing rather than common to all.","cn":"specialis「属于某一类的」在后世拉丁中用于表示某物独有的、而非共有的性质。"},{"era":"ENGLISH -IZE","en":"English formed verbs in -ize from adjectives, and the noun -ization followed. Specialize and specialization are English developments, not Latin words.","cn":"英语由形容词构成 -ize 动词，随后产生 -ization 名词。specialize 与 specialization 都是英语的发展，并非拉丁词。"},{"era":"NINETEENTH CENTURY","en":"The word spread with industrial division of labour and with the growth of professional disciplines, both of which rewarded narrow expertise.","cn":"这个词随工业分工与专业学科的成长而流行，这两者都奖励狭窄的专长。"},{"era":"BIOLOGY","en":"Nineteenth-century biology applied the same word to organisms and cells, where narrowing to a niche is both an advantage and a constraint.","cn":"19 世纪生物学把同一个词用于生物体与细胞，在那里收窄到某一生态位既是优势也是限制。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first attestation date only): the first English citation of specialization is uncertain and usually placed in the nineteenth century; the deeper origin of species is a reconstruction.","cn":"来源不确定（仅首见年代存疑）：specialization 的英语首见书证存疑，通常定在 19 世纪；species 的更深来源属重构。"}]},"similar":{"note":{"en":"The first group holds words from the same species family that are easily confused; the second holds near-synonyms about narrowing.","cn":"第一组是同出 species 词族、容易混淆的词；第二组是表示收窄的近义词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"specialist","ipa":"/ˈspesɪəlɪst/","tag":"the person","definition":"A person who concentrates on one field. Specialization is the process or the field itself.","definitionCN":"指集中钻研某一领域的人。specialization 是过程或领域本身。"},{"word":"special","ipa":"/ˈspeʃl/","tag":"adjective of distinction","definition":"Means 'distinctive or for a particular purpose'. It shares the root but does not name a process of narrowing.","definitionCN":"意为「特别的或专用的」。它共享词根，但不命名收窄的过程。"},{"word":"specification","ipa":"/ˌspesɪfɪˈkeɪʃn/","tag":"different compound","definition":"A detailed statement of requirements. It comes from species plus facere 'to make', so it shares the species root but adds the making verb.","definitionCN":"指详细的要求说明。它由 species 加 facere「制造」构成，因此共享 species 词根，但多了「制造」动词。"},{"word":"species","ipa":"/ˈspiːʃiːz/","tag":"the biological kind","definition":"A group of organisms able to interbreed. It is the source noun, while specialization names a process.","definitionCN":"指能够互相繁殖的一群生物。它是源名词，而 specialization 命名一个过程。"}]},{"heading":"NEAR MEANING","entries":[{"word":"narrowing","ipa":"/ˈnærəʊɪŋ/","tag":"general restriction","definition":"The act of making something narrower. It is broader than specialization, which implies a field or function.","definitionCN":"使某物变窄的行为。它比 specialization 更宽泛，后者暗含领域或功能。"},{"word":"concentration","ipa":"/ˌkɒnsnˈtreɪʃn/","tag":"gathering effort","definition":"The focusing of attention or resources. It stresses effort gathered, while specialization stresses scope reduced.","definitionCN":"注意力或资源的集中。它强调努力聚拢，而 specialization 强调范围缩小。"},{"word":"expertise","ipa":"/ˈekspɜːtiːz/","tag":"skill possessed","definition":"Deep skill in a field. It is what specialization produces, not the process of producing it.","definitionCN":"在某一领域的深厚技能。它是 specialization 的产物，而非该过程本身。"},{"word":"differentiation","ipa":"/ˌdɪfəˈrenʃieɪʃn/","tag":"becoming distinct","definition":"The process of becoming different. In biology it overlaps with cell specialization, but it stresses distinction rather than narrowing.","definitionCN":"变得不同的过程。在生物学中与细胞特化重叠，但它强调区别而非收窄。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"specialis 'of one kind' + -ization: the process of becoming one-kind.","cn":"specialis「属于一类的」+ -ization：变得只属一类的过程。"},{"en":"The family runs special, specialize, specialized, specialization, specialist, specialty, species.","cn":"同族词包括 special、specialize、specialized、specialization、specialist、specialty、species。"},{"en":"Fixed phrases mark the senses: specialization in, economic specialization, specialization of function.","cn":"固定搭配标出义项：在……方面的专长、经济专业化、功能专门化。"},{"en":"specialization is the process or the field; specialist is the person; special is the adjective.","cn":"specialization 是过程或领域；specialist 是人；special 是形容词。"},{"en":"In biology the word cuts both ways: a specialist gains a niche and loses flexibility.","cn":"在生物学中这个词有两面：专化者获得一个生态位，也失去灵活性。"}],"abstract":[{"en":"Picture a tree whose branches each lean toward a different light.","cn":"想象一棵树，每根枝条都朝不同的光倾斜。"},{"en":"Picture a workshop where one worker only fits one kind of bolt.","cn":"想象一间车间，一名工人只装一种螺栓。"},{"en":"Picture a key cut to open exactly one door.","cn":"想象一把只能开一扇门的钥匙。"}]},"examples":[{"en":"Specialization in one crop made the region wealthy but vulnerable.","cn":"单一作物的专业化让该地区富裕，却也脆弱。"},{"en":"The wasp shows specialization for hunting one species of spider.","cn":"这种黄蜂特化为只捕食一种蜘蛛。"},{"en":"Her specialization is seventeenth-century Dutch painting.","cn":"她的专业方向是十七世纪荷兰绘画。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「special（专门的）+ ization（化）」——变得专门 → specialization 专业化、专业方向","word":"specialization"},"root":"拉丁 species「种类」→ specialis「属于某一类的」→ 英语 special + -ize + -ation → specialization。","sensesIntro":{"en":"Nine senses follow one narrowing: effort, a word, a cell or a market becomes confined to one kind, and the word can name the process or the resulting field.","cn":"九个义项沿同一次收窄展开：精力、词义、细胞或市场被限制到一类，而这个词既可命名过程，也可命名由此形成的领域。"},"semanticMap":{"core":{"en":"CORE IMAGE: a trunk splitting into branches, each leaning one way.","cn":"核心意象：主干分出许多枝条，每枝只朝一个方向。"},"chain":["BECOME ONE-KIND","CONCENTRATE EFFORT","NAME THE FIELD","SPLIT THE LABOUR","NARROW THE NICHE","LOSE THE REST"],"branches":[{"senses":"S1 · S3","en":"WORK: concentration of effort, whether in one workshop or across a region.","cn":"工作：精力的集中，或在车间，或在地区。"},{"senses":"S2 · S6","en":"FIELD: the result is a named expertise, certified in professions like medicine.","cn":"领域：结果是可命名的专长，在医学等职业中被认证。"},{"senses":"S4 · S5 · S7","en":"BIOLOGY: organisms, cells and organs narrow to one niche or function.","cn":"生物学：生物体、细胞与器官收窄到一个生态位或功能。"},{"senses":"S8","en":"LANGUAGE: a word's meaning narrows to one sense.","cn":"语言：词义收窄到一个义项。"},{"senses":"S9","en":"MEDIA: content aims at one kind of reader.","cn":"媒体：内容瞄准一类读者。"}]},"affixes":{"intro":{"en":"Specialization is a Latin kind-word with an English verb suffix and an English process-noun suffix; there is no prefix.","cn":"specialization 是拉丁「种类」词加英语动词后缀与英语过程名词后缀，没有前缀。"},"latinIntro":{"en":"Latin species 'kind' gives specialis; English adds -ize and then -ization to name the process.","cn":"拉丁 species「种类」产生 specialis；英语先加 -ize，再加 -ization 以命名过程。"},"items":[{"word":"specialization","structure":"special + -ize + -ation","meaning":"the process of becoming specialized","meaningCN":"变得专门化的过程","example":"Specialization followed the growth of the market.","exampleCN":"专业化随市场成长而出现。"},{"word":"specialize","structure":"special + -ize (to make)","meaning":"to concentrate on one field","meaningCN":"专注于某一领域","example":"The clinic specializes in eye surgery.","exampleCN":"这家诊所专攻眼科手术。"},{"word":"specialized","structure":"specialize + -ed","meaning":"designed or adapted for one purpose","meaningCN":"为某一目的设计或适应的","example":"The bee has specialized mouthparts.","exampleCN":"这种蜂有特化的口器。"},{"word":"special","structure":"specialis (of a kind)","meaning":"distinctive, for a particular purpose","meaningCN":"独特的；专用","example":"They built a special tool for the job.","exampleCN":"他们为这项工作造了专用工具。"},{"word":"specialist","structure":"special + -ist (person)","meaning":"one who concentrates on a field","meaningCN":"专注于某一领域的人","example":"The specialist confirmed the diagnosis.","exampleCN":"专科医生确认了诊断。"},{"word":"species","structure":"species (appearance, kind)","meaning":"a biological kind","meaningCN":"生物学上的物种","example":"Three species nest on the cliff.","exampleCN":"有三种鸟在崖上筑巢。"},{"word":"specify","structure":"species + facere","meaning":"to name or state precisely","meaningCN":"明确指出；具体说明","example":"Specify the units in the report.","exampleCN":"在报告中注明单位。"},{"word":"generalization","structure":"general + -ize + -ation","meaning":"the process of widening to a whole class","meaningCN":"扩展到整类事物的过程","example":"The generalization hides local exceptions.","exampleCN":"这种概括掩盖了地方性例外。"}],"latinEntries":[{"word":"species","structure":"species, speciei (f., fifth declension)","meaning":"appearance, kind, sort","meaningCN":"外观；种类；类别"},{"word":"specialis","structure":"species + -alis","meaning":"of a particular kind","meaningCN":"属于某一类的"},{"word":"-izare","structure":"-izare (verb suffix, via Greek -izein)","meaning":"to make or become","meaningCN":"使……化"}],"derivatives":[{"word":"specialize","pos":"v.","zh":"专门从事；特化"},{"word":"specialized","pos":"adj.","zh":"专门的；特化的"},{"word":"specialist","pos":"n.","zh":"专家；专科医生"},{"word":"special","pos":"adj.","zh":"特殊的；专门的"},{"word":"specialty","pos":"n.","zh":"专业；特产"}]}},{"word":"specialized","ipa_uk":"/ˈspesɪəlaɪzd/","ipa_us":"/ˈspesɪəlaɪzd/","definition_zh":"专门的；专用的；专业化的；特化的；专攻的","definition_en":"designed, trained or adapted for one particular purpose or field","core_image":"一把只为一种螺丝设计的扳手，旁边放着它唯一能拧的螺母","scene":"The lab uses specialized equipment that no other department can operate.","sceneCN":"这里 specialized 指「专用的」（第 1 个义项：为特定用途设计，别处无法通用）；实验室的设备只能做一类工作。图中可辨识物件：专用仪器、单一规格接口、警示标签、操作手册。","pos":[{"tag":"adj.","zh":"专门的；专用的；专业化的；特化的；专攻的（比较级 more specialized，最高级 most specialized）"}],"collocations":[{"phrase":"specialized equipment","zh":"专用设备"},{"phrase":"specialized knowledge","zh":"专门知识"},{"phrase":"highly specialized","zh":"高度专业化的"},{"phrase":"specialized training","zh":"专门训练"},{"phrase":"specialized cells","zh":"特化细胞"},{"phrase":"specialized agency","zh":"专门机构"}],"forms":[{"label":"比较级","form":"more specialized"},{"label":"最高级","form":"most specialized"},{"label":"英式拼写","form":"specialised"},{"label":"动词形式","form":"specialize（专攻；特化）"},{"label":"名词形式","form":"specialization（专业化；专业方向）"},{"label":"名词形式（人）","form":"specialist（专家）"}],"derivatives":[{"word":"specialize","pos":"v.","zh":"专攻；专门从事；特化"},{"word":"specialization","pos":"n.","zh":"专业化；专业方向"},{"word":"specialist","pos":"n.","zh":"专家；专科医生"},{"word":"special","pos":"adj.","zh":"特殊的；专门的"},{"word":"specialty","pos":"n.","zh":"专业；特产"}],"senses":[{"no":"01","title":"Built for one job","titleCN":"专用：为特定用途而造","definition":"made or designed for one particular purpose rather than general use","definitionCN":"为某一特定用途而非通用而制造或设计","example":"The surgeon uses a specialized knife with a guarded edge.","exampleCN":"外科医生使用一种带护刃的专用刀。","why":"The -ed participle turns the process into a state: something that has been specialized is now fitted to one job.","whyCN":"-ed 分词把过程转为状态：已经专门化的东西，如今被适配于一项工作。"},{"no":"02","title":"Expert and narrow","titleCN":"专业精深：知识限于某一领域","definition":"of knowledge or language, deep but confined to one field","definitionCN":"指知识或语言深而窄，限于某一领域","example":"The paper is too specialized for a general audience.","exampleCN":"这篇论文过于专门，普通读者难以理解。","why":"The same narrowing applies to knowledge: depth is gained by giving up breadth.","whyCN":"同样的收窄适用于知识：深度是以放弃广度换来的。"},{"no":"03","title":"Trained for one field","titleCN":"受过专门训练：只做一类工作","definition":"of a person or group, trained for one branch of work","definitionCN":"指个人或团体只受过某一分支工作的训练","example":"Specialized staff were hired to run the new scanner.","exampleCN":"为操作新扫描仪聘用了受过专门训练的员工。","why":"People as well as tools can carry the participle: training narrows what they are able to do.","whyCN":"人和工具一样可以带这个分词：训练收窄了他们能做的事。"},{"no":"04","title":"Adapted to a niche","titleCN":"特化：生物适应狭窄生态位","definition":"in biology, adapted to a narrow habitat or food source","definitionCN":"生物学中指适应狭窄栖息地或食物来源","example":"The specialized feeder cannot survive if its one plant disappears.","exampleCN":"这种特化取食者若失去唯一寄主植物便无法生存。","why":"Evolution uses the adjective for adaptation that is precise and therefore fragile.","whyCN":"进化论用这个形容词描述精确因而脆弱的适应。"},{"no":"05","title":"Differentiated cells","titleCN":"分化细胞：只承担一种功能","definition":"of cells, having developed one function and lost other potentials","definitionCN":"指细胞已发展出一种功能并失去其他潜能","example":"Specialized cells in the root absorb water.","exampleCN":"根部的特化细胞负责吸收水分。","why":"Developmental biology names the end state of differentiation, where a cell has committed to one role.","whyCN":"发育生物学命名分化的终态，此时细胞已承诺承担一个角色。"},{"no":"06","title":"A specialized service","titleCN":"专门服务机构：只处理一类事务","definition":"of an organization, devoted to one type of service","definitionCN":"指机构只从事某一类服务","example":"A specialized agency handles radiation safety.","exampleCN":"一个专门机构负责辐射安全。","why":"Institutions acquired the adjective as a label of jurisdiction: narrow remit, deeper competence.","whyCN":"机构把这个形容词当作职权标签：职责窄，能力深。"},{"no":"07","title":"Specialized vocabulary","titleCN":"专业词汇：行内人使用的术语","definition":"of terms, belonging to a technical field and unfamiliar outside it","definitionCN":"指术语属于某技术领域，领域外的人不熟悉","example":"The manual is full of specialized vocabulary.","exampleCN":"手册里满是专业词汇。","why":"Language narrows with knowledge: each field builds terms that only its members use.","whyCN":"语言随知识收窄：每个领域都造出只有圈内人使用的术语。"},{"no":"08","title":"Specialized equipment","titleCN":"专用设备：不具通用性","definition":"of machinery, unable to perform general tasks","definitionCN":"指机械不具备通用能力","example":"The harvester is specialized and cannot be used on steep slopes.","exampleCN":"这台收割机是专用的，无法在陡坡上使用。","why":"Engineering uses the participle to warn of a trade-off: high performance in one task, uselessness in others.","whyCN":"工程用这个分词提醒一种取舍：在一项任务上高效，在别的任务上无用。"},{"no":"09","title":"Specialized publication","titleCN":"专业出版物：面向窄众","definition":"of media, addressed to a small expert readership","definitionCN":"指媒体面向一小群专业读者","example":"The journal is specialized but widely cited.","exampleCN":"这份期刊面向窄众，却被广泛引用。","why":"Media repeats the pattern: narrow audience, deeper treatment, less general appeal.","whyCN":"媒体重复同一模式：受众窄、处理深、大众吸引力低。"}],"etymology":{"intro":{"en":"Specialized is the past participle of specialize, formed in English from special plus -ize, with Latin specialis 'of a particular kind' behind it. The dates below are approximate.","cn":"specialized 是 specialize 的过去分词，在英语中由 special 加 -ize 构成，背后是拉丁 specialis「属于某一类的」。以下年代均为约数。"},"items":[{"era":"LATIN SPECIALIS","en":"Specialis came from species 'kind, appearance' and meant 'belonging to one kind'. It is not a classical adjective of frequent use but appears in later Latin.","cn":"specialis 出自 species「种类、外观」，意为「属于某一类的」。它不是古典拉丁中高频使用的形容词，但见于后世拉丁。"},{"era":"ENGLISH SPECIAL","en":"English special arrived through French in the Middle Ages, meaning 'distinctive, exceptional'. The 'devoted to one purpose' sense developed later.","cn":"英语 special 经法语于中世纪进入，意为「独特的、例外的」。「专用于某一目的」之义后来才发展出来。"},{"era":"SPECIALIZE","en":"The verb specialize is an English formation of the nineteenth century, built on the model of other -ize verbs from adjectives.","cn":"动词 specialize 是 19 世纪的英语构词，仿照其他由形容词派生的 -ize 动词而成。"},{"era":"SPECIALIZED","en":"The participle specialized spread with industry, science and professional training, naming anything fitted to one narrow task.","cn":"分词 specialized 随工业、科学与专业训练而流行，命名任何被适配于一项狭窄任务的事物。"},{"era":"MODERN USE","en":"Today the adjective is usually neutral but often warns of a trade-off: a specialized tool or reader is strong in one place and helpless elsewhere.","cn":"今天这个形容词通常中性，但常暗含取舍：专用工具或专业读者在一处强，在别处无能。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first attestation date only): the first English citations of specialize and specialized are uncertain and usually placed in the nineteenth century.","cn":"来源不确定（仅首见年代存疑）：specialize 与 specialized 的英语首见书证存疑，通常定在 19 世纪。"}]},"similar":{"note":{"en":"The first group holds forms of the same verb that differ in part of speech; the second holds adjectives of narrow purpose.","cn":"第一组是同一动词的不同形式，区别在词性；第二组是表示用途狭窄的形容词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"specialize","ipa":"/ˈspesɪəlaɪz/","tag":"verb","definition":"To concentrate on one field. It names the act, while specialized describes the result.","definitionCN":"指专注于某一领域。它命名动作，而 specialized 描述结果。"},{"word":"specialization","ipa":"/ˌspesɪəlaɪˈzeɪʃn/","tag":"noun","definition":"The process or the field. It cannot modify a noun: 'specialization equipment' is wrong.","definitionCN":"指过程或领域。它不能修饰名词：specialization equipment 是错误搭配。"},{"word":"special","ipa":"/ˈspeʃl/","tag":"broader adjective","definition":"Means 'distinctive or exceptional'. It can describe a single occasion, while specialized always implies a narrow use.","definitionCN":"意为「特别的、例外的」。它可以描述一次性场合，而 specialized 总暗含狭窄用途。"},{"word":"specialist","ipa":"/ˈspesɪəlɪst/","tag":"person noun","definition":"A person devoted to one field. It refers to humans, not to tools or cells.","definitionCN":"指专注于某一领域的人。它指人，不指工具或细胞。"}]},{"heading":"NEAR MEANING","entries":[{"word":"dedicated","ipa":"/ˈdedɪkeɪtɪd/","tag":"devoted to one use","definition":"Set apart for one purpose. It matches tools and services, but not the biological sense.","definitionCN":"为某一用途专门留出。它对应工具与服务，但不覆盖生物学义。"},{"word":"technical","ipa":"/ˈteknɪkl/","tag":"of a craft","definition":"Relating to the practical methods of a field. It describes the kind of detail, not the narrowness of purpose.","definitionCN":"与某领域的实际方法相关。它描述细节的种类，而非用途的狭窄。"},{"word":"niche","ipa":"/niːʃ/","tag":"narrow market or role","definition":"Suited to a small specialized market or ecological role. It stresses smallness of audience or habitat.","definitionCN":"适合狭小的专业市场或生态角色。它强调受众或生境之小。"},{"word":"differentiated","ipa":"/ˌdɪfəˈrenʃieɪtɪd/","tag":"made distinct","definition":"Made different from others. In biology it overlaps with specialized, but it stresses distinction rather than narrow use.","definitionCN":"被做得与他人不同。在生物学中与特化重叠，但它强调区别而非狭窄用途。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"special + -ize + -ed: the state of having been narrowed to one use.","cn":"special + -ize + -ed：已被收窄到一种用途的状态。"},{"en":"The family runs special, specialize, specialized, specialization, specialist, specialty.","cn":"同族词包括 special、specialize、specialized、specialization、specialist、specialty。"},{"en":"Fixed phrases mark the senses: specialized equipment, specialized knowledge, specialized cells.","cn":"固定搭配标出义项：专用设备、专门知识、特化细胞。"},{"en":"The adjective often implies a trade-off: excellent at one task, useless at others.","cn":"这个形容词常暗含取舍：在一项任务上出色，在别的任务上无用。"},{"en":"Spelling note: American specialized with z, British specialised with s.","cn":"拼写提示：美式 specialized 用 z，英式 specialised 用 s。"}],"abstract":[{"en":"Picture a wrench that fits exactly one nut.","cn":"想象一把只适配一种螺母的扳手。"},{"en":"Picture a key shaped for a single lock in a large building.","cn":"想象一把只对应大楼里一把锁的钥匙。"},{"en":"Picture a cell that has forgotten every trade except one.","cn":"想象一个细胞，除了本行之外忘掉了所有手艺。"}]},"examples":[{"en":"The hospital bought specialized equipment for neonatal surgery.","cn":"医院为新生儿外科购置了专用设备。"},{"en":"Highly specialized workers are the first to lose their jobs in a downturn.","cn":"高度专业化的工人往往是经济下行时最先失业的。"},{"en":"The plant has specialized roots that survive in salty soil.","cn":"这种植物有能在盐碱土中存活的特化根系。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「special（专门的）+ ized（已……的）」——已经变得专门的 → specialized 专用的、特化的","word":"specialized"},"root":"拉丁 species「种类」→ specialis → 英语 special + -ize + -ed → specialized。","sensesIntro":{"en":"Nine senses follow one fitted shape: something is narrowed until it serves one purpose well, and the same shape can belong to a tool, a mind, a cell, an agency or a journal.","cn":"九个义项沿同一个被适配的形状展开：某物被收窄到能很好地服务一个用途，而这个形状可以属于工具、头脑、细胞、机构或刊物。"},"semanticMap":{"core":{"en":"CORE IMAGE: a wrench that fits exactly one nut.","cn":"核心意象：一把只适配一种螺母的扳手。"},"chain":["FIT ONE PURPOSE","NARROW THE USE","TRAIN FOR ONE FIELD","ADAPT TO A NICHE","LOSE FLEXIBILITY","SERVE A SMALL GROUP"],"branches":[{"senses":"S1 · S8","en":"TOOLS: designed for one job, which makes them excellent there and useless elsewhere.","cn":"工具：为一项工作设计，因而在此出色、在别处无用。"},{"senses":"S2 · S7","en":"KNOWLEDGE: deep but narrow, including the technical vocabulary that marks a field.","cn":"知识：深而窄，包括标志某领域的专业词汇。"},{"senses":"S3 · S6","en":"PEOPLE AND BODIES: trained staff and dedicated agencies concentrate on one branch.","cn":"人与机构：受训人员与专门机构集中于一个分支。"},{"senses":"S4 · S5","en":"BIOLOGY: organisms and cells adapt to one niche or function and lose other options.","cn":"生物学：生物体与细胞适应一个生态位或功能，并失去其他选择。"},{"senses":"S9","en":"AUDIENCE: a journal serves a small expert readership.","cn":"受众：刊物服务一小群专业读者。"}]},"affixes":{"intro":{"en":"Specialized is a Latin kind-word plus the English verb suffix -ize and the participle ending -ed.","cn":"specialized 是拉丁「种类」词加英语动词后缀 -ize 与分词词尾 -ed。"},"latinIntro":{"en":"Latin species 'kind' gives specialis, English adds -ize to make a verb, and -ed turns it into a state.","cn":"拉丁 species「种类」产生 specialis，英语加 -ize 构成动词，再加 -ed 转为状态。"},"items":[{"word":"specialized","structure":"specialize + -ed (past participle)","meaning":"narrowed to one purpose","meaningCN":"被收窄到一种用途的","example":"Specialized tools fill one shelf.","exampleCN":"专用工具占满了一个架子。"},{"word":"specialize","structure":"special + -ize","meaning":"to concentrate on one field","meaningCN":"专注于某一领域","example":"The firm specializes in bridges.","exampleCN":"这家公司专攻桥梁。"},{"word":"specialization","structure":"specialize + -ation","meaning":"the process or the field","meaningCN":"过程或领域","example":"Specialization brought both wealth and risk.","exampleCN":"专业化既带来财富也带来风险。"},{"word":"special","structure":"specialis (of a kind)","meaning":"distinctive, exceptional","meaningCN":"独特的；例外的","example":"This is a special case.","exampleCN":"这是一个特例。"},{"word":"specialist","structure":"special + -ist","meaning":"a person of one field","meaningCN":"某一领域的人","example":"The specialist read the scan.","exampleCN":"专科医生看了扫描图。"},{"word":"specialty","structure":"special + -ty","meaning":"a field of expertise","meaningCN":"专业领域","example":"Her specialty is rare minerals.","exampleCN":"她的专业是稀有矿物。"},{"word":"species","structure":"species (kind)","meaning":"a biological kind","meaningCN":"生物物种","example":"The species is found only here.","exampleCN":"该物种仅在此地发现。"},{"word":"specify","structure":"species + facere","meaning":"to state precisely","meaningCN":"精确说明","example":"Specify the tolerance in the drawing.","exampleCN":"在图纸上注明公差。"}],"latinEntries":[{"word":"species","structure":"species, speciei (f., fifth declension)","meaning":"kind, appearance","meaningCN":"种类；外观"},{"word":"specialis","structure":"species + -alis","meaning":"of a particular kind","meaningCN":"属于某一类的"},{"word":"-izare","structure":"-izare (verb suffix)","meaning":"to make or become","meaningCN":"使……化"}],"derivatives":[{"word":"specialize","pos":"v.","zh":"专攻；特化"},{"word":"specialization","pos":"n.","zh":"专业化；专业方向"},{"word":"specialist","pos":"n.","zh":"专家"},{"word":"special","pos":"adj.","zh":"特殊的；专门的"},{"word":"specialty","pos":"n.","zh":"专业；特产"}]}},{"word":"specification","ipa_uk":"/ˌspesɪfɪˈkeɪʃn/","ipa_us":"/ˌspesɪfɪˈkeɪʃn/","definition_zh":"规格；规格说明；详细要求；具体指明；专利说明书","definition_en":"a detailed statement of what is required, or the act of stating requirements precisely","core_image":"一张图纸边缘写满尺寸、公差与材料标号，每一行都可被检验","scene":"The supplier built the part to the specification, down to the stated tolerance.","sceneCN":"这里 specification 指「技术规格」（第 1 个义项：对尺寸、材料与公差的明确要求）；供应商严格按规格制造零件。图中可辨识物件：工程图、公差标注、材料清单、检验卡尺。","pos":[{"tag":"n.","zh":"规格；规格说明；详细要求；具体指明；专利说明书（可数，常用复数 specifications）"}],"collocations":[{"phrase":"technical specification","zh":"技术规格"},{"phrase":"meet the specification","zh":"符合规格"},{"phrase":"design specification","zh":"设计规格"},{"phrase":"product specification","zh":"产品规格"},{"phrase":"specification sheet","zh":"规格表"},{"phrase":"to specification","zh":"按规格"}],"forms":[{"label":"复数","form":"specifications"},{"label":"动词形式","form":"specify（明确规定；具体说明）"},{"label":"形容词形式","form":"specific（具体的；特定的）"},{"label":"副词形式","form":"specifically（具体地；明确地）"},{"label":"形容词形式","form":"specified（规定的；指定的）"},{"label":"另一名词","form":"specificity（特异性；专一性）"}],"derivatives":[{"word":"specify","pos":"v.","zh":"明确规定；具体说明"},{"word":"specific","pos":"adj.","zh":"具体的；特定的"},{"word":"specifically","pos":"adv.","zh":"具体地；明确地"},{"word":"specified","pos":"adj.","zh":"规定的；指定的"},{"word":"specificity","pos":"n.","zh":"特异性；专一性"}],"senses":[{"no":"01","title":"A statement of requirements","titleCN":"规格说明：把要求逐条写清","definition":"a detailed written statement of the requirements for a product or process","definitionCN":"对产品或工艺要求的详细书面说明","example":"The specification lists every alloy and every tolerance.","exampleCN":"规格说明列出了每种合金与每项公差。","why":"Late Latin specificatio came from specificare 'to specify', built on specificus 'making a kind', from species plus facere; the noun is a making-explicit.","whyCN":"晚期拉丁 specificatio 出自 specificare「具体指明」，后者基于 specificus「使成某类」，由 species 加 facere 构成；这个名词就是「把话说清楚」的产物。"},{"no":"02","title":"The act of specifying","titleCN":"具体指明的动作：把模糊变明确","definition":"the act of stating something precisely rather than leaving it vague","definitionCN":"把某事精确说明而非留作模糊的行为","example":"The specification of the boundary took three meetings.","exampleCN":"边界的明确划定开了三次会。","why":"The action sense survives from Latin: specificatio named the act of making a thing specific.","whyCN":"动作义承自拉丁：specificatio 命名的是「使某物变得具体」的行为。"},{"no":"03","title":"Engineering specification","titleCN":"工程规格：可检验的技术参数","definition":"in engineering, the measured parameters a product must meet","definitionCN":"工程中产品必须满足的可测量参数","example":"The beam failed because it was made below specification.","exampleCN":"这根梁不合格，因为制造低于规格。","why":"Industry turned the document into measurable limits: a specification is what an inspector can check.","whyCN":"工业把文件变成可测的限值：规格就是检验员可以核对的东西。"},{"no":"04","title":"A contract annex","titleCN":"合同附件：作为验收依据","definition":"in construction and procurement, the document that defines acceptable work","definitionCN":"建筑与采购中界定合格工作的文件","example":"The contractor must deliver to the specification in Annex B.","exampleCN":"承包商必须按附件 B 的规格交付。","why":"Legally the document becomes binding: the specification is what a dispute is argued against.","whyCN":"在法律上文件具有约束力：规格就是争议所依据的准绳。"},{"no":"05","title":"Patent specification","titleCN":"专利说明书：充分公开技术要求","definition":"in patent law, the written description that must disclose the invention fully","definitionCN":"专利法中必须充分公开发明的书面说明","example":"The patent specification must teach others how to build the device.","exampleCN":"专利说明书必须教会儿他人如何制造该装置。","why":"Patent law uses the oldest sense: the applicant must specify the invention in enough detail to be reproduced.","whyCN":"专利法使用最古老的义项：申请人必须把发明说明到足以被复现的程度。"},{"no":"06","title":"Software interface specification","titleCN":"接口规范：约定数据如何交换","definition":"in computing, a document defining how systems exchange data","definitionCN":"计算中界定系统如何交换数据的文件","example":"Two teams coded to the same specification and their modules linked.","exampleCN":"两个团队按同一份规范编码，模块得以对接。","why":"Computing applies the contract sense to machines: an interface specification is a treaty between programs.","whyCN":"计算把契约义用于机器：接口规范是程序之间的条约。"},{"no":"07","title":"Specification in linguistics","titleCN":"语言学中的特征规定：对属性的明确标注","definition":"in linguistics, the explicit marking of a feature or property","definitionCN":"语言学中对某一特征或属性的明确标注","example":"The specification of tense is obligatory in this language.","exampleCN":"在这种语言中，时态的明确标注是强制的。","why":"Theoretical linguistics borrowed the word for explicit feature marking, the same 'making precise' move.","whyCN":"理论语言学借这个词表示显性特征标注，仍是同一个「使之精确」的动作。"},{"no":"08","title":"Stating a condition","titleCN":"载明条件：把前提写明","definition":"the explicit statement of a condition under which something holds","definitionCN":"对某事物成立所依条件的明确陈述","example":"The specification of the test conditions matters more than the result.","exampleCN":"试验条件的载明比结果本身更要紧。","why":"The word generalizes beyond products: any condition that must be stated precisely is specified.","whyCN":"这个词超越产品而泛化：任何必须精确陈述的条件都被「载明」。"}],"etymology":{"intro":{"en":"Specification comes from Late Latin specificatio, from specificare 'to make specific', built on species 'kind' and facere 'to make'. The dates below are approximate.","cn":"specification 出自晚期拉丁 specificatio，源自 specificare「使具体」，由 species「种类」与 facere「制造」构成。以下年代均为约数。"},"items":[{"era":"LATIN SPECIES","en":"Species meant 'appearance, kind'. The compound specificus described what makes a thing of its own kind; its deeper origin is debated.","cn":"species 意为「外观、种类」。复合词 specificus 描述「使某物成为其自身那一类」的东西；其更深来源有争议。"},{"era":"SPECIFICARE","en":"Later Latin specificare meant 'to make specific, to name precisely'. The verb joined species with the facere family, so precision is pictured as making.","cn":"后世拉丁 specificare 意为「使具体、精确命名」。该动词把 species 与 facere 词族结合，因此「精确」被想象为一种制作。"},{"era":"SPECIFICATIO","en":"The action noun specificatio named the act of specifying. It is a later Latin formation, not a classical word of wide use.","cn":"动作名词 specificatio 命名「具体说明」的行为。它属后世拉丁构词，并非古典中广泛使用的词。"},{"era":"ENGLISH ARRIVAL","en":"English specification appears in the seventeenth century, first as the act of specifying and soon as a written statement. The exact first citation is uncertain.","cn":"英语 specification 于 17 世纪出现，先是「具体说明」的动作，随后很快指书面说明。最早确切书证年代存疑。"},{"era":"INDUSTRY AND LAW","en":"Nineteenth-century engineering and patent law made the document central: a specification became the measurable or legally binding statement of requirements.","cn":"19 世纪的工程与专利法让这份文件变得关键：specification 成为可测量或在法律上有约束力的要求陈述。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first attestation date only): the first English date is uncertain; the origin of species before its 'kind' sense is a reconstruction.","cn":"来源不确定（仅首见年代存疑）：英语首见年代存疑；species 在「种类」义之前的来源属重构。"}]},"similar":{"note":{"en":"The first group holds species-family words that are easily confused; the second holds near-synonyms for a statement of requirements.","cn":"第一组是同出 species 词族、易混淆的词；第二组是表示要求说明的近义词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"specialization","ipa":"/ˌspesɪəlaɪˈzeɪʃn/","tag":"different suffix, different meaning","definition":"Means concentration on one field. Specification comes from species plus facere, so it names the making-explicit of requirements instead.","definitionCN":"意为专注于某一领域。specification 由 species 加 facere 构成，命名的是把要求讲清楚。"},{"word":"specific","ipa":"/spəˈsɪfɪk/","tag":"adjective","definition":"Means 'precise or particular'. A specification is the document or act that makes something specific.","definitionCN":"意为「具体的或特定的」。specification 是使某物变具体的那份文件或那个动作。"},{"word":"specify","ipa":"/ˈspesɪfaɪ/","tag":"verb","definition":"To state precisely. It names the act; specification is the act as a thing or the resulting document.","definitionCN":"指精确说明。它命名动作；specification 是作为事物的动作或由此产生的文件。"},{"word":"species","ipa":"/ˈspiːʃiːz/","tag":"source noun","definition":"A biological kind. It is the root noun but has no sense of requirement or precision.","definitionCN":"指生物物种。它是词根名词，但不含要求或精确之义。"}]},{"heading":"NEAR MEANING","entries":[{"word":"requirement","ipa":"/rɪˈkwaɪəmənt/","tag":"what is needed","definition":"Something needed or demanded. A specification is the document that records requirements in detail.","definitionCN":"指需要或要求的东西。specification 是把这些要求详细记录下来的文件。"},{"word":"standard","ipa":"/ˈstændəd/","tag":"agreed rule","definition":"An agreed rule or level. A standard is shared by a body; a specification may be written for one product.","definitionCN":"共同商定的规则或水平。标准由团体共享；规格可以只针对一件产品。"},{"word":"blueprint","ipa":"/ˈbluːprɪnt/","tag":"plan drawing","definition":"A detailed plan or drawing. It shows the design, while a specification states the required properties.","definitionCN":"详细的计划或图纸。它展示设计，而规格说明规定所需性能。"},{"word":"description","ipa":"/dɪˈskrɪpʃn/","tag":"general account","definition":"An account of what something is like. It need not be binding or measurable, as a specification usually is.","definitionCN":"对某物样貌的叙述。它不必具有约束力或可测量性，而规格通常如此。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"species 'kind' + facere 'make' + -ation: making a thing specific.","cn":"species「种类」+ facere「制造」+ -ation：把事物做得具体明确。"},{"en":"The family runs specify, specific, specifically, specified, specification, specificity.","cn":"同族词包括 specify、specific、specifically、specified、specification、specificity。"},{"en":"Fixed phrases mark the senses: technical specification, meet the specification, specification sheet.","cn":"固定搭配标出义项：技术规格、符合规格、规格表。"},{"en":"specialization and specification share species but split the work: one narrows effort, one states requirements.","cn":"specialization 与 specification 共享 species 但分工不同：一个收窄精力，一个写明要求。"},{"en":"In patent law the specification must teach the invention, not merely claim it.","cn":"在专利法中，说明书必须教会他人如何实现发明，而不仅是主张权利。"}],"abstract":[{"en":"Picture a drawing whose margins are filled with numbers an inspector can check.","cn":"想象一张图纸，页边写满检验员可以核对的数字。"},{"en":"Picture a contract clause that turns 'good quality' into a measurable limit.","cn":"想象一条合同条款，把「质量好」变成可测的限值。"},{"en":"Picture a recipe that lists grams instead of 'some' and 'a little'.","cn":"想象一份食谱写的是克数，而不是「少许」「适量」。"}]},"examples":[{"en":"The bridge was built to a specification that allowed for high winds.","cn":"这座桥按能承受强风的规格建造。"},{"en":"Reviewers found that the specification omitted the operating temperature.","cn":"评审者发现规格说明漏掉了工作温度。"},{"en":"The patent specification described the pump in enough detail to rebuild it.","cn":"专利说明书把泵描述得足以被重新制造出来。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「specific（具体的）+ ation（化）」——把要求变具体 → specification 规格说明","word":"specification"},"root":"拉丁 species「种类」+ facere「制造」→ specificare「使具体」→ specificatio「具体说明」→ 英语 specification。","sensesIntro":{"en":"Eight senses follow one act of making precise: vague requirements are turned into written, measurable or legally binding statements, whether for a part, a contract, a patent or a program.","cn":"八个义项沿同一次「使之精确」的动作展开：模糊的要求被转成书面、可测或有法律约束力的陈述，无论对象是零件、合同、专利还是程序。"},"semanticMap":{"core":{"en":"CORE IMAGE: a drawing whose margins carry every dimension and tolerance.","cn":"核心意象：一张图纸，页边写满尺寸与公差。"},"chain":["MAKE IT SPECIFIC","WRITE THE REQUIREMENTS","SET MEASURABLE LIMITS","BIND BY CONTRACT","DISCLOSE AN INVENTION","DEFINE AN INTERFACE"],"branches":[{"senses":"S1 · S2","en":"THE DOCUMENT AND THE ACT: requirements are stated, and the stating is itself named.","cn":"文件与动作：要求被陈述，而陈述本身也被命名。"},{"senses":"S3 · S4","en":"ENGINEERING AND LAW: the statement becomes measurable limits and a binding annex.","cn":"工程与法律：陈述变成可测限值与有约束力的附件。"},{"senses":"S5","en":"PATENT: the oldest disclosure sense, where the description must teach the invention.","cn":"专利：最古老的公开义，描述必须教会他人实现发明。"},{"senses":"S6","en":"COMPUTING: a specification is a treaty between programs.","cn":"计算：规范是程序之间的条约。"},{"senses":"S7 · S8","en":"GENERAL PRECISION: features and test conditions must be marked explicitly.","cn":"一般精确：特征与试验条件必须被显性标注。"}]},"affixes":{"intro":{"en":"Specification is a Latin kind-word plus the making verb, closed by an action-noun suffix.","cn":"specification 是拉丁「种类」词加「制造」动词，再以动作名词后缀收尾。"},"latinIntro":{"en":"Latin species 'kind' and facere 'to make' build specificare; -tio gives the action noun specificatio.","cn":"拉丁 species「种类」与 facere「制造」构成 specificare；-tio 产生动作名词 specificatio。"},"items":[{"word":"specification","structure":"specificare + -tio","meaning":"a making specific; a statement of requirements","meaningCN":"使具体；要求说明","example":"The specification fills forty pages.","exampleCN":"这份规格说明有四十页。"},{"word":"specify","structure":"species + facere","meaning":"to state precisely","meaningCN":"精确说明","example":"Specify the grade of steel.","exampleCN":"注明钢材等级。"},{"word":"specific","structure":"specificus (making a kind)","meaning":"precise; of a particular kind","meaningCN":"具体的；特定种类的","example":"A specific antibody was used.","exampleCN":"使用了特异性抗体。"},{"word":"specifically","structure":"specific + -ally","meaning":"precisely, in particular","meaningCN":"具体地；特别地","example":"The rule applies specifically to ports.","exampleCN":"该规则特别适用于港口。"},{"word":"specified","structure":"specify + -ed","meaning":"stated in advance","meaningCN":"预先规定的","example":"Use the specified lubricant only.","exampleCN":"只能使用规定的润滑剂。"},{"word":"specificity","structure":"specific + -ity","meaning":"the quality of being precise or selective","meaningCN":"精确性或专一性","example":"The test lacks specificity.","exampleCN":"这项检测缺乏特异性。"},{"word":"species","structure":"species (kind)","meaning":"a biological kind","meaningCN":"生物物种","example":"One species dominates the reef.","exampleCN":"一个物种主导了这片礁区。"},{"word":"special","structure":"specialis (of a kind)","meaning":"distinctive","meaningCN":"独特的","example":"The part needs a special alloy.","exampleCN":"这个零件需要特殊合金。"}],"latinEntries":[{"word":"species","structure":"species, speciei (f., fifth declension)","meaning":"kind, appearance","meaningCN":"种类；外观"},{"word":"specificare","structure":"species + facere (later Latin)","meaning":"to make specific, name precisely","meaningCN":"使具体；精确命名"},{"word":"specificatio","structure":"specificare + -tio","meaning":"a specifying","meaningCN":"具体说明"}],"derivatives":[{"word":"specify","pos":"v.","zh":"明确规定；具体说明"},{"word":"specific","pos":"adj.","zh":"具体的；特定的"},{"word":"specifically","pos":"adv.","zh":"具体地"},{"word":"specified","pos":"adj.","zh":"规定的"},{"word":"specificity","pos":"n.","zh":"特异性"}]}},{"word":"stability","ipa_uk":"/stəˈbɪləti/","ipa_us":"/stəˈbɪləti/","definition_zh":"稳定；稳定性；稳固；安定；（化学）稳定性","definition_en":"the quality of remaining firm, steady and unlikely to change or collapse","core_image":"一座宽基座的高塔在风中仍然直立，塔尖几乎不动","scene":"The bridge's stability was tested by loading it with trucks far heavier than expected.","sceneCN":"这里 stability 指「结构稳定性」（第 1 个义项：在外力下保持不倒的能力）；桥被远超预期的卡车载重检验。图中可辨识物件：桥梁、成排卡车、位移标尺、支座。","pos":[{"tag":"n.","zh":"稳定；稳定性；稳固；安定；化学稳定性（多不可数，指多种稳定性质时用复数 stabilities）"}],"collocations":[{"phrase":"political stability","zh":"政治稳定"},{"phrase":"price stability","zh":"价格稳定"},{"phrase":"structural stability","zh":"结构稳定性"},{"phrase":"stability of","zh":"……的稳定性"},{"phrase":"ensure stability","zh":"确保稳定"},{"phrase":"thermal stability","zh":"热稳定性"}],"forms":[{"label":"复数（多种稳定性）","form":"stabilities"},{"label":"形容词形式","form":"stable（稳定的）"},{"label":"副词形式","form":"stably（稳定地，较少用）"},{"label":"动词形式","form":"stabilize（使稳定）"},{"label":"名词形式","form":"stabilization（稳定化）"},{"label":"施动者名词","form":"stabilizer（稳定器；稳定剂）"}],"derivatives":[{"word":"stable","pos":"adj.","zh":"稳定的；稳固的"},{"word":"stabilize","pos":"v.","zh":"使稳定；稳定下来"},{"word":"stabilization","pos":"n.","zh":"稳定化；稳定措施"},{"word":"stabilizer","pos":"n.","zh":"稳定器；稳定剂"},{"word":"instability","pos":"n.","zh":"不稳定；动荡"}],"senses":[{"no":"01","title":"Firmness of structure","titleCN":"结构稳固：外力下不倾覆","definition":"the ability of a structure to stay upright and resist collapse","definitionCN":"结构保持直立、抵抗坍塌的能力","example":"The tower's stability comes from its wide base.","exampleCN":"这座塔的稳固来自它宽阔的基座。","why":"Latin stabilitas meant 'firmness', from stabilis 'standing firm', built on stare 'to stand'; the noun names the capacity to keep standing.","whyCN":"拉丁 stabilitas 意为「坚固」，出自 stabilis「站得稳的」，而后者基于 stare「站立」；这个名词命名的是「保持站住」的能力。"},{"no":"02","title":"Steadiness of character","titleCN":"性情稳定：情绪不起大落","definition":"emotional steadiness, the quality of not being easily thrown off","definitionCN":"情绪上的平稳，不易被扰动","example":"Her stability helped the team through the crisis.","exampleCN":"她的沉稳帮助团队度过了危机。","why":"The standing image moves inward: a person who stands firm is emotionally stable.","whyCN":"站立的意象向内移动：站得稳的人，在情绪上就是稳定的。"},{"no":"03","title":"Economic stability","titleCN":"经济稳定：价格与产出少波动","definition":"in economics, the condition in which prices and output change slowly and predictably","definitionCN":"经济学中价格与产出变化缓慢而可预期的状态","example":"Central banks aim at price stability rather than zero inflation.","exampleCN":"央行追求价格稳定，而非零通胀。","why":"Economics borrows 'standing firm' for a system: stability is the absence of sharp swings.","whyCN":"经济学借「站得稳」来描述系统：稳定就是没有剧烈摆动。"},{"no":"04","title":"Political stability","titleCN":"政治稳定：秩序持续不被打破","definition":"the condition in which a government and its institutions endure without upheaval","definitionCN":"政府及其制度持续存续、不发生剧变的状态","example":"Foreign investment depends on political stability.","exampleCN":"外国投资取决于政治稳定。","why":"The word widened from objects to institutions: what stands firm can also be a state.","whyCN":"这个词从物体拓宽到制度：站得稳的也可以是一个国家。"},{"no":"05","title":"Mechanical equilibrium","titleCN":"力学平衡：受扰后能回到原位","definition":"in physics, the tendency of a system to return to equilibrium after a small disturbance","definitionCN":"物理中系统受到小扰动后回到平衡的趋势","example":"The ball at the bottom of the bowl has stability; at the top it does not.","exampleCN":"碗底的球是稳定的，碗顶的球则不稳定。","why":"Physics made the notion testable: stability is defined by what happens after a nudge.","whyCN":"物理学让这一概念可被检验：稳定性由「被轻推之后会怎样」来定义。"},{"no":"06","title":"Chemical stability","titleCN":"化学稳定性：不易分解或反应","definition":"in chemistry, the resistance of a substance to decomposition or unwanted reaction","definitionCN":"化学中物质抵抗分解或非期望反应的能力","example":"The compound's thermal stability limits its use at high temperatures.","exampleCN":"该化合物的热稳定性限制了它在高温下的使用。","why":"Chemists measure how long a substance holds together, which is the standing image at molecular scale.","whyCN":"化学家测量物质能保持完整多久，这就是分子尺度上的「站住」意象。"},{"no":"07","title":"Ecological stability","titleCN":"生态稳定：扰动后仍能维持结构","definition":"in ecology, the capacity of an ecosystem to maintain its structure after disturbance","definitionCN":"生态系统中受扰动后维持其结构的能力","example":"Species diversity contributes to the stability of the grassland.","exampleCN":"物种多样性有助于草地的稳定。","why":"Ecology applies the same test: a system is stable if it returns after a shock, not if it never changes.","whyCN":"生态学应用同样的检验：系统若在冲击后恢复才算稳定，而非从不变化。"},{"no":"08","title":"Medical stability","titleCN":"病情稳定：指标不再恶化","definition":"in medicine, the condition of a patient whose vital signs are not worsening","definitionCN":"医学中病人生命体征不再恶化的状态","example":"The patient is now in stable condition and can be moved.","exampleCN":"病人现在病情稳定，可以转运。","why":"Clinical usage compresses the idea into a status word: stable means no longer moving in the wrong direction.","whyCN":"临床用法把这一观念压缩为状态词：stable 意为不再朝错误方向变化。"}],"etymology":{"intro":{"en":"Stability comes from Latin stabilitas 'firmness', from stabilis 'standing firm', built on stare 'to stand'. The dates below are approximate.","cn":"stability 出自拉丁 stabilitas「坚固」，源自 stabilis「站得稳的」，基于 stare「站立」。以下年代均为约数。"},"items":[{"era":"LATIN STARE","en":"Latin stare meant 'to stand, to remain'. It is well recorded and underlies state, status, station, statue and constant; its deeper origin is debated.","cn":"拉丁 stare 意为「站立、停留」。记录充分，支撑 state、status、station、statue、constant；其更深来源有争议。"},{"era":"STABILIS","en":"Stabilis 'standing firm, steadfast' described what does not give way. The adjective served both physical and moral firmness.","cn":"stabilis「站得稳的、坚定的」描述不屈服的东西。这个形容词既用于物理的稳固，也用于道德上的坚定。"},{"era":"STABILITAS","en":"The noun stabilitas named firmness as a quality. It is classical, used of buildings, of character and of political order.","cn":"名词 stabilitas 命名作为性质的坚固。它属古典用法，可用于建筑、性格与政治秩序。"},{"era":"ENGLISH ARRIVAL","en":"English stability arrives through French in the Middle Ages, first in the sense of firmness of mind or of realm. The exact first citation is uncertain.","cn":"英语 stability 经法语于中世纪进入，初义为心志或国度的稳固。最早确切书证年代存疑。"},{"era":"SCIENCE","en":"From the seventeenth century the word entered mechanics and chemistry, where stability became a measurable response to disturbance.","cn":"自 17 世纪起，这个词进入力学与化学，稳定性在那里成为对扰动的可测响应。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first attestation date only): the first English date is uncertain; the origin of stare before its 'stand' sense is debated and any Indo-European root is a reconstruction.","cn":"来源不确定（仅首见年代存疑）：英语首见年代存疑；stare 在「站立」义之前的来源有争议，任何印欧词根均属重构。"}]},"similar":{"note":{"en":"The first group holds same-family words that differ in part of speech; the second holds near-synonyms for steadiness.","cn":"第一组是同族词，区别在词性；第二组是表示平稳的近义词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"stable","ipa":"/ˈsteɪbl/","tag":"adjective or noun","definition":"As an adjective it means 'firm'; as a noun it means a building for horses. Stability is only the abstract noun.","definitionCN":"作形容词意为「稳固的」；作名词指马厩。stability 只是抽象名词。"},{"word":"stabilize","ipa":"/ˈsteɪbəlaɪz/","tag":"verb","definition":"To make something steady. It names the action; stability is the state achieved.","definitionCN":"指使某物稳定。它命名动作；stability 是达到的状态。"},{"word":"instability","ipa":"/ˌɪnstəˈbɪləti/","tag":"direct negative","definition":"The lack of stability, often suggesting tendency to change suddenly. It is not the same as mere change.","definitionCN":"缺乏稳定，常暗示易于突变。它与单纯的「变化」并不相同。"},{"word":"stabilization","ipa":"/ˌsteɪbəlaɪˈzeɪʃn/","tag":"the process","definition":"The process of making something stable, as in economic stabilization. Stability is the resulting condition.","definitionCN":"使某物变稳的过程，如经济稳定化。stability 是结果状态。"}]},{"heading":"NEAR MEANING","entries":[{"word":"steadiness","ipa":"/ˈstedinəs/","tag":"even motion","definition":"Freedom from shaking or sudden change. It stresses evenness, while stability stresses resistance to being moved.","definitionCN":"不摇晃、不突变。它强调均匀，而 stability 强调抵抗被推动。"},{"word":"firmness","ipa":"/ˈfɜːmnəs/","tag":"solid resistance","definition":"Solidity of material or of purpose. It is more physical and more about texture than stability.","definitionCN":"材料或意志的坚实。它更偏物理，更关乎质地。"},{"word":"equilibrium","ipa":"/ˌiːkwɪˈlɪbriəm/","tag":"balanced forces","definition":"A state in which opposing forces balance. It can be unstable equilibrium, so it does not guarantee stability.","definitionCN":"对立力量相互平衡的状态。它可以是「不稳定平衡」，因此并不保证稳定。"},{"word":"constancy","ipa":"/ˈkɒnstənsi/","tag":"unchanging","definition":"The quality of staying the same. It stresses lack of change, while stability allows change that returns to a level.","definitionCN":"保持不变的性质。它强调不变，而 stability 允许回到某一水平的变化。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"stare 'to stand' + -bilis 'able' + -itas: the ability to keep standing.","cn":"stare「站立」+ -bilis「能够」+ -itas：保持站住的能力。"},{"en":"The family runs stable, stability, stabilize, stabilization, stabilizer, instability, establish.","cn":"同族词包括 stable、stability、stabilize、stabilization、stabilizer、instability、establish。"},{"en":"Fixed phrases mark the senses: political stability, price stability, structural stability, thermal stability.","cn":"固定搭配标出义项：政治稳定、价格稳定、结构稳定性、热稳定性。"},{"en":"The family shares the stare root with state, status, station, statue and constant.","cn":"这个词族与 state、status、station、statue、constant 共享 stare 词根。"},{"en":"In physics, stability is tested by a nudge, not by stillness.","cn":"在物理学中，稳定性靠一次轻推来检验，而不是靠静止不动。"}],"abstract":[{"en":"Picture a tall tower whose base is wider than its top.","cn":"想象一座高塔，基座比塔顶更宽。"},{"en":"Picture a bowl with a ball resting at the bottom, returning after every push.","cn":"想象一只碗，球停在碗底，每次被推都会回来。"},{"en":"Picture a table with four legs on uneven ground, still not rocking.","cn":"想象一张四条腿的桌子放在不平的地上，却并不摇晃。"}]},"examples":[{"en":"Engineers added cross-bracing to improve the stability of the frame.","cn":"工程师增加了交叉支撑，以提高框架的稳定性。"},{"en":"Price stability encouraged firms to invest in new equipment.","cn":"价格稳定鼓励企业投资新设备。"},{"en":"The patient's condition reached stability after two days in intensive care.","cn":"在重症监护两天后，病人的病情趋于稳定。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「sta（站住）+ bility（能力）」——能站得住的能力 → stability 稳定、稳定性","word":"stability"},"root":"拉丁 stare「站立」→ stabilis「站得稳的」→ stabilitas「坚固」→ 英语 stability。","sensesIntro":{"en":"Eight senses follow one upright posture: something keeps standing when pushed, and that capacity can belong to a tower, a temper, a currency, a government, an ecosystem or a patient.","cn":"八个义项沿同一种直立姿态展开：某物在被推动时仍能站住，而这种能力可以属于塔、脾气、货币、政府、生态系统或病人。"},"semanticMap":{"core":{"en":"CORE IMAGE: a tall tower on a wide base that does not lean in the wind.","cn":"核心意象：一座宽基座的高塔，在风中并不倾斜。"},"chain":["KEEP STANDING","RESIST THE PUSH","RETURN TO PLACE","HOLD A LEVEL","KEEP ORDER","STOP WORSENING"],"branches":[{"senses":"S1 · S5","en":"PHYSICAL STANDING: structures and mechanical systems stay up or return after a nudge.","cn":"物理站立：结构与力学系统不倒，或在被推后回到原位。"},{"senses":"S2","en":"CHARACTER: the same upright image applied to a person's temper.","cn":"性格：同一幅直立意象用于人的性情。"},{"senses":"S3 · S4","en":"SYSTEMS: prices and governments are stable when they do not swing violently.","cn":"系统：价格与政府在不剧烈摆动时就是稳定的。"},{"senses":"S6 · S7","en":"MATTER AND LIFE: compounds resist decomposition, ecosystems recover after shock.","cn":"物质与生命：化合物抵抗分解，生态系统在冲击后恢复。"},{"senses":"S8","en":"CLINICAL STATUS: a patient stops moving in the wrong direction.","cn":"临床状态：病人不再朝恶化方向变化。"}]},"affixes":{"intro":{"en":"Stability is a Latin standing verb with an ability suffix and an abstract noun ending; there is no prefix.","cn":"stability 是拉丁「站立」动词加能力后缀与抽象名词词尾，没有前缀。"},"latinIntro":{"en":"Latin stare 'to stand' gives stabilis 'able to stand', and -itas turns it into the abstract noun stabilitas.","cn":"拉丁 stare「站立」产生 stabilis「能站住的」，-itas 再把它转为抽象名词 stabilitas。"},"items":[{"word":"stability","structure":"stabilis + -itas (abstract noun)","meaning":"firmness, steadiness","meaningCN":"坚固；稳定","example":"The wall's stability depends on drainage.","exampleCN":"这堵墙的稳固取决于排水。"},{"word":"stable","structure":"stare + -bilis (able to)","meaning":"firm, not likely to change","meaningCN":"稳固的；不易变的","example":"The patient is stable.","exampleCN":"病人情况稳定。"},{"word":"stabilize","structure":"stable + -ize (to make)","meaning":"to make steady","meaningCN":"使稳定","example":"They stabilized the slope with nets.","exampleCN":"他们用网加固了坡面。"},{"word":"stabilization","structure":"stabilize + -ation","meaning":"the process of making steady","meaningCN":"使稳定的过程","example":"Stabilization of the currency took a year.","exampleCN":"货币稳定化用了一年。"},{"word":"stabilizer","structure":"stabilize + -or (agent)","meaning":"a device or substance that steadies","meaningCN":"起稳定作用的装置或物质","example":"The ship's stabilizer limits roll.","exampleCN":"船上的减摇装置限制了横摇。"},{"word":"instability","structure":"in- (not) + stability","meaning":"lack of firmness","meaningCN":"缺乏稳固","example":"Slope instability closed the road.","exampleCN":"坡体不稳定导致道路封闭。"},{"word":"establish","structure":"ex- + stabilis","meaning":"to set up firmly","meaningCN":"牢固地建立","example":"They established the station in 1901.","exampleCN":"他们于 1901 年建立了该站。"},{"word":"state","structure":"status (standing, condition)","meaning":"condition in which something stands","meaningCN":"某物所处的状态","example":"The state of the roof is poor.","exampleCN":"屋顶的状况很差。"},{"word":"constant","structure":"con- + stare (standing together)","meaning":"unchanging, steady","meaningCN":"不变的；恒定的","example":"Keep the temperature constant.","exampleCN":"保持温度恒定。"}],"latinEntries":[{"word":"stare","structure":"stare (verb, first conjugation)","meaning":"to stand, to remain","meaningCN":"站立；停留"},{"word":"stabilis","structure":"stare + -bilis","meaning":"able to stand, firm","meaningCN":"能站住的；坚固的"},{"word":"stabilitas","structure":"stabilis + -itas","meaning":"firmness, stability","meaningCN":"坚固；稳定"}],"derivatives":[{"word":"stable","pos":"adj.","zh":"稳定的"},{"word":"stabilize","pos":"v.","zh":"使稳定"},{"word":"stabilization","pos":"n.","zh":"稳定化"},{"word":"stabilizer","pos":"n.","zh":"稳定器"},{"word":"instability","pos":"n.","zh":"不稳定"}]}}]);
